/* AQA GCSE Physics (8463) — grade-separated exam-style practice questions,
   split by the 8 specification topics. 15 questions per grade (4-9) = 90 each.
   Each question: { g, marks, q, scheme: [mark points], answer: model answer } */
export default {
  subjectId: "physics",
  sections: {
    "1. Energy": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "Name the energy store of a moving object.", scheme: ["Kinetic (energy) store"], answer: "The kinetic energy store." },
      { g: 4, marks: 1, q: "Name the energy store of an object raised up above the ground.", scheme: ["Gravitational potential (energy) store"], answer: "The gravitational potential energy store." },
      { g: 4, marks: 1, q: "Name the energy store of a stretched spring.", scheme: ["Elastic potential (energy) store"], answer: "The elastic potential energy store." },
      { g: 4, marks: 1, q: "Name the energy store that increases when an object gets hotter.", scheme: ["Thermal (energy) store"], answer: "The thermal energy store." },
      { g: 4, marks: 1, q: "Name the energy store found in foods and fuels.", scheme: ["Chemical (energy) store"], answer: "The chemical energy store." },
      { g: 4, marks: 1, q: "Name the energy store released in a nuclear reactor.", scheme: ["Nuclear (energy) store"], answer: "The nuclear energy store." },
      { g: 4, marks: 1, q: "State the unit used to measure energy.", scheme: ["Joule (J)"], answer: "The joule (J)." },
      { g: 4, marks: 1, q: "State the unit used to measure power.", scheme: ["Watt (W)"], answer: "The watt (W)." },
      { g: 4, marks: 1, q: "Give one example of a renewable energy resource.", scheme: ["Wind / solar / hydro / tidal / geothermal / bio-fuel / wave (any one)"], answer: "Wind (or solar, hydroelectric, tidal, geothermal, bio-fuel or waves)." },
      { g: 4, marks: 1, q: "Give one example of a non-renewable energy resource.", scheme: ["Coal / oil / gas (fossil fuel) / nuclear (any one)"], answer: "A fossil fuel such as coal (or oil, gas or nuclear fuel)." },
      { g: 4, marks: 1, q: "Name the three fossil fuels.", scheme: ["Coal, oil and (natural) gas"], answer: "Coal, oil and natural gas." },
      { g: 4, marks: 1, q: "What name is given to energy that is wasted or spread out to the surroundings?", scheme: ["Dissipated energy"], answer: "Dissipated (wasted) energy." },
      { g: 4, marks: 1, q: "Name the force that does work when an object is lifted.", scheme: ["Gravity / weight"], answer: "Gravity (weight)." },
      { g: 4, marks: 1, q: "Name a method used to reduce friction between moving parts.", scheme: ["Lubrication (using oil)"], answer: "Lubrication using oil." },
      { g: 4, marks: 1, q: "What is added to a house's walls and roof to reduce heat loss?", scheme: ["Insulation"], answer: "Insulation." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 1, q: "State the principle of conservation of energy.", scheme: ["Energy cannot be created or destroyed, only transferred/stored/dissipated"], answer: "Energy cannot be created or destroyed; it can only be transferred, stored or dissipated." },
      { g: 5, marks: 2, q: "Give two ways that energy can be transferred.", scheme: ["Any two of: mechanically (by a force), electrically, by heating, by radiation (light/sound)"], answer: "Energy can be transferred mechanically (by a force), electrically, by heating, or by radiation such as light and sound." },
      { g: 5, marks: 1, q: "State the equation linking kinetic energy, mass and speed.", scheme: ["Ek = 0.5 x m x v^2"], answer: "Kinetic energy = ½ x mass x speed² (Ek = ½mv²)." },
      { g: 5, marks: 1, q: "State the equation linking gravitational potential energy, mass, gravity and height.", scheme: ["Ep = m x g x h"], answer: "Gravitational potential energy = mass x gravitational field strength x height (Ep = mgh)." },
      { g: 5, marks: 1, q: "State the equation for power in terms of energy and time.", scheme: ["P = E / t"], answer: "Power = energy transferred ÷ time (P = E/t)." },
      { g: 5, marks: 2, q: "What is meant by the efficiency of a device?", scheme: ["Useful output energy transfer ÷ total input energy transfer", "The proportion/fraction of energy usefully transferred"], answer: "Efficiency is the useful output energy transfer divided by the total input energy transfer; it is the fraction of energy that is usefully transferred." },
      { g: 5, marks: 1, q: "State the equation for efficiency.", scheme: ["Efficiency = useful output energy transfer / total input energy transfer"], answer: "Efficiency = useful output energy transfer ÷ total input energy transfer." },
      { g: 5, marks: 2, q: "Name two energy stores involved when a ball falls from a shelf to the ground.", scheme: ["Gravitational potential store (decreasing)", "Kinetic store (increasing)"], answer: "The gravitational potential store decreases and the kinetic store increases as the ball falls." },
      { g: 5, marks: 1, q: "What is meant by a renewable energy resource?", scheme: ["One that is replenished as fast as it is used / will not run out"], answer: "One that is replenished at least as fast as it is used, so it will not run out." },
      { g: 5, marks: 2, q: "Give two renewable energy resources used to generate electricity.", scheme: ["Any two of: wind, solar, hydroelectric, tidal, wave, geothermal, bio-fuel"], answer: "Wind and solar (or hydroelectric, tidal, wave, geothermal or bio-fuel)." },
      { g: 5, marks: 1, q: "Why are fossil fuels described as non-renewable?", scheme: ["They are used up faster than they are formed / will run out"], answer: "They are used up much faster than they form, so they will run out." },
      { g: 5, marks: 2, q: "State two ways of reducing unwanted energy transfers from a machine.", scheme: ["Lubrication to reduce friction", "Thermal insulation to reduce heat loss (any two)"], answer: "Lubricating moving parts to reduce friction and using thermal insulation to reduce heat loss." },
      { g: 5, marks: 1, q: "What happens to the total amount of energy in a closed system?", scheme: ["It stays the same / is constant"], answer: "It stays the same (energy is conserved)." },
      { g: 5, marks: 2, q: "Name the useful and wasted energy transfers from an electric motor.", scheme: ["Useful: kinetic energy (movement)", "Wasted: thermal energy (heat) / sound"], answer: "The useful transfer is to a kinetic store (movement); energy is wasted as thermal energy (heat) and sound." },
      { g: 5, marks: 1, q: "State the equation linking work done, force and distance.", scheme: ["W = F x s"], answer: "Work done = force x distance moved along the line of action of the force (W = Fs)." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Calculate the kinetic energy of a 4 kg object moving at 5 m/s.", scheme: ["Ek = 0.5 x m x v^2 = 0.5 x 4 x 5^2", "= 50 J"], answer: "Ek = ½mv² = 0.5 x 4 x 5² = 0.5 x 4 x 25 = 50 J." },
      { g: 6, marks: 2, q: "Calculate the gravitational potential energy gained when a 2 kg mass is raised 3 m. Take g = 9.8 N/kg.", scheme: ["Ep = m x g x h = 2 x 9.8 x 3", "= 58.8 J"], answer: "Ep = mgh = 2 x 9.8 x 3 = 58.8 J." },
      { g: 6, marks: 2, q: "A lamp transfers 600 J of energy in 20 s. Calculate its power.", scheme: ["P = E / t = 600 / 20", "= 30 W"], answer: "P = E/t = 600 ÷ 20 = 30 W." },
      { g: 6, marks: 2, q: "A device usefully transfers 80 J out of 100 J of input energy. Calculate its efficiency.", scheme: ["efficiency = useful / total = 80 / 100", "= 0.8 (80%)"], answer: "Efficiency = useful ÷ total = 80 ÷ 100 = 0.8 (80%)." },
      { g: 6, marks: 3, q: "Explain how lubricating a machine reduces unwanted energy transfers.", scheme: ["Reduces friction between moving parts", "Less energy transferred to thermal store / wasted as heat", "More energy transferred usefully / higher efficiency"], answer: "Lubrication reduces the friction between moving surfaces, so less energy is wasted as heat to the thermal store and more is transferred usefully, raising efficiency." },
      { g: 6, marks: 2, q: "Explain why a moving car eventually stops when the engine is switched off.", scheme: ["Friction/air resistance acts on the car", "Kinetic energy is transferred (dissipated) to thermal store of surroundings"], answer: "Friction and air resistance transfer the car's kinetic energy to the thermal store of the surroundings, so it slows and stops." },
      { g: 6, marks: 2, q: "Calculate the elastic potential energy in a spring with spring constant 200 N/m extended by 0.1 m.", scheme: ["Ee = 0.5 x k x e^2 = 0.5 x 200 x 0.1^2", "= 1 J"], answer: "Ee = ½ke² = 0.5 x 200 x 0.1² = 0.5 x 200 x 0.01 = 1 J." },
      { g: 6, marks: 3, q: "Describe two ways to increase the thermal insulation of a house and how each reduces energy loss.", scheme: ["Thicker/less conductive walls reduce rate of energy transfer", "Loft/cavity insulation traps air (poor conductor)", "Reduces conduction/heat loss through walls and roof"], answer: "Using thicker walls made of less conductive material slows the rate of energy transfer, and adding loft or cavity insulation traps air, which is a poor conductor, reducing heat loss through the roof and walls." },
      { g: 6, marks: 2, q: "Explain why the thermal conductivity of a material affects heat loss from a house.", scheme: ["Higher conductivity means faster energy transfer through the material", "Lower conductivity means slower heat loss / better insulation"], answer: "A material with high thermal conductivity transfers energy quickly, so heat is lost faster; a low conductivity material transfers energy slowly and reduces heat loss." },
      { g: 6, marks: 2, q: "Calculate the work done when a force of 50 N moves an object 4 m in the direction of the force.", scheme: ["W = F x s = 50 x 4", "= 200 J"], answer: "W = Fs = 50 x 4 = 200 J." },
      { g: 6, marks: 3, q: "Compare wind power and coal for reliability and environmental impact.", scheme: ["Wind is renewable and produces no carbon dioxide when running", "Wind is unreliable (only when windy)", "Coal is reliable but non-renewable and releases carbon dioxide"], answer: "Wind is renewable and gives off no carbon dioxide when running, but it is unreliable because it only works when the wind blows. Coal is reliable and can be used on demand, but it is non-renewable and releases carbon dioxide, a greenhouse gas." },
      { g: 6, marks: 2, q: "A kettle transfers 90 000 J of energy in 45 s. Calculate its power.", scheme: ["P = E / t = 90000 / 45", "= 2000 W"], answer: "P = E/t = 90 000 ÷ 45 = 2000 W (2 kW)." },
      { g: 6, marks: 2, q: "Explain the energy transfers when a battery-powered toy car moves.", scheme: ["Chemical store of the battery decreases", "Transferred electrically to the motor then to a kinetic store", "Some wasted to thermal store (heat/sound)"], answer: "The chemical store in the battery decreases, transferring energy electrically to the motor and then to the kinetic store of the moving car, with some wasted as heat and sound." },
      { g: 6, marks: 3, q: "Explain why geothermal energy is considered reliable but is only used in some places.", scheme: ["Heat from the ground is always available (reliable)", "Renewable and low carbon dioxide", "Only economic where hot rocks are near the surface"], answer: "Geothermal energy uses heat from hot rocks that is always available, so it is reliable, renewable and low in carbon dioxide; however, it is only practical in places where hot rocks are close to the surface, such as volcanic regions." },
      { g: 6, marks: 2, q: "A mass of 5 kg is lifted so that it gains 245 J of gravitational potential energy. Take g = 9.8 N/kg. Calculate the height it was raised.", scheme: ["h = Ep / (m x g) = 245 / (5 x 9.8)", "= 5 m"], answer: "h = Ep ÷ (mg) = 245 ÷ (5 x 9.8) = 245 ÷ 49 = 5 m." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "Calculate the kinetic energy of a 1200 kg car moving at 20 m/s.", scheme: ["Ek = 0.5 x m x v^2 = 0.5 x 1200 x 20^2", "= 0.5 x 1200 x 400", "= 240000 J"], answer: "Ek = ½mv² = 0.5 x 1200 x 20² = 0.5 x 1200 x 400 = 240 000 J (240 kJ)." },
      { g: 7, marks: 4, q: "A 0.5 kg ball is dropped from a height of 1.8 m. Assuming all energy is transferred, calculate its speed just before it hits the ground. Take g = 9.8 N/kg.", scheme: ["Ep = m x g x h = 0.5 x 9.8 x 1.8 = 8.82 J", "Ek = Ep so 8.82 = 0.5 x 0.5 x v^2", "v^2 = 8.82 / 0.25 = 35.28", "v = 5.9 m/s (approx)"], answer: "Ep = mgh = 0.5 x 9.8 x 1.8 = 8.82 J. This becomes kinetic energy: 8.82 = 0.5 x 0.5 x v², so v² = 8.82 ÷ 0.25 = 35.28, giving v = 5.9 m/s." },
      { g: 7, marks: 3, q: "A motor is 60% efficient and has a useful power output of 300 W. Calculate the total power input.", scheme: ["efficiency = useful / total so total = useful / efficiency", "total = 300 / 0.6", "= 500 W"], answer: "Total input = useful output ÷ efficiency = 300 ÷ 0.6 = 500 W." },
      { g: 7, marks: 3, q: "Calculate the energy needed to raise the temperature of 2 kg of water by 30 degrees C. Specific heat capacity of water = 4200 J/kg degrees C.", scheme: ["E = m x c x change in theta = 2 x 4200 x 30", "= 252000 J"], answer: "E = mcΔθ = 2 x 4200 x 30 = 252 000 J (252 kJ)." },
      { g: 7, marks: 4, q: "A crane lifts a 500 kg load to a height of 12 m in 8 s. Take g = 9.8 N/kg. Calculate the useful power output of the crane.", scheme: ["Ep = m x g x h = 500 x 9.8 x 12 = 58800 J", "P = E / t = 58800 / 8", "= 7350 W"], answer: "Ep = mgh = 500 x 9.8 x 12 = 58 800 J. P = E/t = 58 800 ÷ 8 = 7350 W (7.35 kW)." },
      { g: 7, marks: 3, q: "A block of 3 kg metal is given 27 000 J of energy and its temperature rises by 20 degrees C. Calculate the specific heat capacity of the metal.", scheme: ["c = E / (m x change in theta) = 27000 / (3 x 20)", "= 27000 / 60", "= 450 J/kg degrees C"], answer: "c = E ÷ (mΔθ) = 27 000 ÷ (3 x 20) = 27 000 ÷ 60 = 450 J/kg°C." },
      { g: 7, marks: 3, q: "Explain, in terms of energy stores and transfers, what happens as a pendulum swings from its highest point to its lowest point.", scheme: ["At the top energy is in the gravitational potential store", "As it falls, gravitational store transfers to the kinetic store", "At the bottom it has maximum kinetic energy / minimum gravitational"], answer: "At the highest point the energy is in the gravitational potential store. As the pendulum swings down this transfers to the kinetic store, so at the lowest point the kinetic energy is greatest and the gravitational potential energy is least." },
      { g: 7, marks: 3, q: "A spring with a spring constant of 50 N/m stores 4 J of elastic potential energy. Calculate its extension.", scheme: ["Ee = 0.5 x k x e^2 so e^2 = 2 x Ee / k = 2 x 4 / 50", "e^2 = 0.16", "e = 0.4 m"], answer: "Ee = ½ke², so e² = 2Ee ÷ k = (2 x 4) ÷ 50 = 0.16, giving e = 0.4 m." },
      { g: 7, marks: 3, q: "Explain why the efficiency of a device can never be greater than 100%.", scheme: ["Energy cannot be created (conservation of energy)", "Useful output cannot exceed total input", "Some energy is always wasted/dissipated"], answer: "Because energy cannot be created, the useful output energy can never be more than the total input energy, and in practice some is always dissipated, so efficiency is always less than 100%." },
      { g: 7, marks: 4, q: "A wind turbine and a gas power station both generate electricity. Compare them in terms of reliability, running cost and environmental impact.", scheme: ["Wind renewable, low running cost, no carbon dioxide when running", "Wind unreliable (needs wind)", "Gas reliable and can respond to demand", "Gas non-renewable and releases carbon dioxide"], answer: "A wind turbine is renewable, has very low running costs and gives off no carbon dioxide when running, but it is unreliable as it needs wind. A gas power station is reliable and can meet demand quickly, but it is non-renewable, has fuel costs and releases carbon dioxide." },
      { g: 7, marks: 3, q: "Calculate how long it takes a 2000 W kettle to transfer 240 000 J of energy.", scheme: ["t = E / P = 240000 / 2000", "= 120 s", "= 2 minutes"], answer: "t = E/P = 240 000 ÷ 2000 = 120 s (2 minutes)." },
      { g: 7, marks: 4, q: "A ball of mass 0.2 kg is thrown straight up at 6 m/s. Calculate the maximum height it reaches, ignoring air resistance. Take g = 9.8 N/kg.", scheme: ["Ek = 0.5 x m x v^2 = 0.5 x 0.2 x 6^2 = 3.6 J", "At the top Ek transfers fully to Ep: 3.6 = m x g x h", "h = 3.6 / (0.2 x 9.8)", "= 1.84 m (approx)"], answer: "Ek = ½mv² = 0.5 x 0.2 x 6² = 3.6 J. At the top this becomes gravitational potential energy: 3.6 = 0.2 x 9.8 x h, so h = 3.6 ÷ 1.96 = 1.84 m." },
      { g: 7, marks: 3, q: "Explain how a hydroelectric power station transfers energy to generate electricity.", scheme: ["Water stored high up has gravitational potential energy", "Falling water transfers to a kinetic store, turning turbines", "Turbines turn generators, transferring energy electrically"], answer: "Water stored high in a reservoir has a large gravitational potential store; as it flows down it transfers to a kinetic store that turns turbines, which drive generators to transfer energy electrically as a supply." },
      { g: 7, marks: 3, q: "The specific heat capacity of oil is 2000 J/kg degrees C and of water is 4200 J/kg degrees C. Explain which would heat up faster if given the same energy and mass.", scheme: ["Oil has the lower specific heat capacity", "Less energy needed to raise its temperature by 1 degrees C", "So oil heats up faster / reaches a higher temperature"], answer: "Oil has the lower specific heat capacity, so less energy is needed to raise its temperature by 1°C. For the same mass and energy, the oil heats up faster and reaches a higher temperature than the water." },
      { g: 7, marks: 3, q: "A 60 kg athlete runs up a flight of stairs of height 5 m in 4 s. Take g = 9.8 N/kg. Calculate the useful power output.", scheme: ["Ep = m x g x h = 60 x 9.8 x 5 = 2940 J", "P = E / t = 2940 / 4", "= 735 W"], answer: "Ep = mgh = 60 x 9.8 x 5 = 2940 J. P = E/t = 2940 ÷ 4 = 735 W." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "A 1500 kg car accelerates from 8 m/s to 20 m/s. Calculate the increase in its kinetic energy.", scheme: ["Ek at start = 0.5 x 1500 x 8^2 = 48000 J", "Ek at end = 0.5 x 1500 x 20^2 = 300000 J", "Increase = 300000 - 48000", "= 252000 J"], answer: "Starting Ek = 0.5 x 1500 x 8² = 48 000 J; final Ek = 0.5 x 1500 x 20² = 300 000 J. Increase = 300 000 - 48 000 = 252 000 J (252 kJ)." },
      { g: 8, marks: 4, q: "An electric heater supplies 84 000 J to 0.5 kg of water, raising its temperature from 20 degrees C to 60 degrees C. Calculate the specific heat capacity of the water and comment on whether energy was wasted (accepted value 4200 J/kg degrees C).", scheme: ["change in theta = 60 - 20 = 40 degrees C", "c = E / (m x change in theta) = 84000 / (0.5 x 40)", "= 4200 J/kg degrees C", "Matches accepted value, so little/no energy wasted to surroundings"], answer: "Δθ = 60 - 20 = 40°C. c = E ÷ (mΔθ) = 84 000 ÷ (0.5 x 40) = 84 000 ÷ 20 = 4200 J/kg°C. This equals the accepted value, suggesting almost no energy was wasted to the surroundings." },
      { g: 8, marks: 4, q: "A pump raises 300 kg of water through 15 m in 30 s. Take g = 9.8 N/kg. The pump has an input power of 2000 W. Calculate the useful power output and the efficiency.", scheme: ["Ep = m x g x h = 300 x 9.8 x 15 = 44100 J", "Useful P = E / t = 44100 / 30 = 1470 W", "efficiency = useful / total = 1470 / 2000", "= 0.735 (73.5%)"], answer: "Ep = mgh = 300 x 9.8 x 15 = 44 100 J. Useful power = 44 100 ÷ 30 = 1470 W. Efficiency = 1470 ÷ 2000 = 0.735 (73.5%)." },
      { g: 8, marks: 4, q: "Explain, using ideas about energy stores and dissipation, why a bouncing ball does not return to its original height.", scheme: ["Gravitational store transfers to kinetic then elastic on impact", "Some energy dissipated as thermal energy and sound at each bounce", "Less energy in the kinetic store after the bounce", "So it rises to a lower height each time"], answer: "As the ball falls its gravitational store transfers to a kinetic store, and on impact to an elastic store. At each bounce some energy is dissipated as heat and sound, so less energy remains in the kinetic store; therefore the ball rises to a lower height each time." },
      { g: 8, marks: 4, q: "A 0.15 kg arrow is fired from a bow. The bowstring (spring constant 900 N/m) is pulled back 0.5 m. Assuming all elastic potential energy is transferred, calculate the speed of the arrow as it leaves the bow.", scheme: ["Ee = 0.5 x k x e^2 = 0.5 x 900 x 0.5^2 = 112.5 J", "Ee = Ek so 112.5 = 0.5 x 0.15 x v^2", "v^2 = 112.5 / 0.075 = 1500", "v = 38.7 m/s (approx)"], answer: "Ee = ½ke² = 0.5 x 900 x 0.5² = 112.5 J. This transfers to kinetic energy: 112.5 = 0.5 x 0.15 x v², so v² = 112.5 ÷ 0.075 = 1500, giving v = 38.7 m/s." },
      { g: 8, marks: 4, q: "Explain how reducing friction and improving insulation both increase the efficiency of transferring energy usefully.", scheme: ["Friction transfers energy to the thermal store (wasted heat)", "Lubrication reduces friction so less energy wasted", "Insulation reduces the rate of heat loss to surroundings", "Both mean a greater fraction of input energy is transferred usefully"], answer: "Friction wastes energy by transferring it to the thermal store as heat, and lubrication reduces this. Insulation reduces the rate at which heat is lost to the surroundings. Both reduce wasted transfers, so a greater fraction of the input energy is transferred usefully, raising efficiency." },
      { g: 8, marks: 4, q: "Compare nuclear power and solar power as energy resources, considering reliability, environmental impact and running costs.", scheme: ["Nuclear reliable, provides constant large output", "Nuclear produces radioactive waste but little carbon dioxide", "Solar renewable and low carbon dioxide but unreliable (day/weather)", "Solar low running cost; nuclear high build/decommissioning cost"], answer: "Nuclear power is reliable and provides a constant large output with little carbon dioxide, but it produces dangerous radioactive waste and has high building and decommissioning costs. Solar power is renewable, low in carbon dioxide and cheap to run, but it is unreliable because it depends on daylight and weather." },
      { g: 8, marks: 4, q: "A 40 W lamp is 5% efficient at producing light. Calculate the useful light power output and the power wasted, and state the store the wasted energy goes to.", scheme: ["Useful = efficiency x total = 0.05 x 40 = 2 W", "Wasted = 40 - 2 = 38 W", "Wasted energy goes to the thermal store (heat)"], answer: "Useful light power = 0.05 x 40 = 2 W. Wasted power = 40 - 2 = 38 W, which is transferred to the thermal store as heat." },
      { g: 8, marks: 4, q: "Explain why using bio-fuels is sometimes described as carbon neutral, and give one problem with this claim.", scheme: ["Plants absorb carbon dioxide as they grow", "Carbon dioxide released on burning was recently absorbed", "So net carbon dioxide can be close to zero", "Problem: land used for fuel not food / energy used in processing/transport"], answer: "Bio-fuel crops absorb carbon dioxide as they grow, and this is released again when the fuel is burned, so the net carbon dioxide can be near zero. However, growing them uses land that could grow food, and energy used in processing and transport adds to emissions." },
      { g: 8, marks: 4, q: "A rollercoaster car of mass 800 kg starts from rest at the top of a 30 m drop. Take g = 9.8 N/kg. Calculate its speed at the bottom if 10% of the energy is dissipated by friction.", scheme: ["Ep = m x g x h = 800 x 9.8 x 30 = 235200 J", "Useful (kinetic) = 90% = 0.9 x 235200 = 211680 J", "211680 = 0.5 x 800 x v^2 so v^2 = 529.2", "v = 23 m/s (approx)"], answer: "Ep = mgh = 800 x 9.8 x 30 = 235 200 J. With 10% lost, kinetic energy = 0.9 x 235 200 = 211 680 J. So 211 680 = 0.5 x 800 x v², v² = 529.2, giving v = 23 m/s." },
      { g: 8, marks: 4, q: "Explain how the specific heat capacity of water makes it useful in central heating systems and as a coolant.", scheme: ["Water has a high specific heat capacity", "Can store a large amount of energy per kg per degree", "Carries a lot of thermal energy around a heating system", "Can absorb a lot of heat as a coolant without a large temperature rise"], answer: "Water has a high specific heat capacity, so it can store a large amount of energy for each kilogram and each degree of temperature change. This lets it carry a lot of thermal energy around a central heating system, and as a coolant it can absorb a great deal of heat without its temperature rising too much." },
      { g: 8, marks: 4, q: "Two identical blocks are heated with the same power. Block A reaches a higher temperature than block B in the same time. Explain what this tells you about their specific heat capacities.", scheme: ["Same energy supplied to each in the same time", "Block A has a smaller temperature rise per joule reversed: higher temp means less energy per degree", "Block A has the lower specific heat capacity", "Block B needs more energy per degree so heats up more slowly"], answer: "Both blocks receive the same energy in the same time. Block A reaches a higher temperature, so it needs less energy to raise its temperature by 1°C, meaning it has the lower specific heat capacity; block B has the higher specific heat capacity and heats up more slowly." },
      { g: 8, marks: 4, q: "Describe how a pumped storage hydroelectric scheme stores energy and explain why it is useful for meeting sudden demand.", scheme: ["Surplus electricity pumps water up to a high reservoir (gravitational store)", "When demand is high, water is released to drive turbines/generators", "Can be switched on very quickly", "Stores energy for peak demand times"], answer: "When demand is low, surplus electricity is used to pump water up to a high reservoir, storing energy in a gravitational store. When demand suddenly rises, the water is released to turn turbines and generators, and because it can be started very quickly it is ideal for meeting peaks in demand." },
      { g: 8, marks: 4, q: "A kettle transfers 360 000 J of energy to heat water but only 306 000 J usefully heats the water. Calculate the efficiency and suggest where the wasted energy goes.", scheme: ["efficiency = useful / total = 306000 / 360000", "= 0.85 (85%)", "Wasted 54000 J to thermal store of kettle/surroundings (and sound)"], answer: "Efficiency = 306 000 ÷ 360 000 = 0.85 (85%). The wasted 54 000 J is transferred to the thermal store of the kettle body and surroundings, and a little as sound." },
      { g: 8, marks: 4, q: "Explain why building more renewable energy resources can be difficult despite their environmental benefits.", scheme: ["Many are unreliable/intermittent (wind, solar, tidal timing)", "High initial building costs", "Can require large areas of land or specific locations (hydro, geothermal)", "May affect habitats or the landscape"], answer: "Although renewables give off little carbon dioxide, many are unreliable because they depend on the weather or tides, they have high building costs, and some need large areas of land or specific sites such as fast rivers or hot rocks, which can disturb habitats or spoil the landscape." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "A 1000 kg car travelling at 25 m/s brakes to a stop. Calculate the kinetic energy lost, and explain what happens to this energy and how the braking distance would change if the speed were doubled.", scheme: ["Ek = 0.5 x m x v^2 = 0.5 x 1000 x 25^2 = 312500 J", "All kinetic energy transferred to thermal store of brakes (and surroundings) by friction", "Ek is proportional to v^2", "Doubling speed gives 4x the kinetic energy", "So about 4x the work must be done by the brakes", "Braking distance becomes about 4 times greater"], answer: "Ek = ½mv² = 0.5 x 1000 x 25² = 312 500 J. Friction in the brakes transfers all of this to the thermal store of the brakes and surroundings. Because kinetic energy depends on v², doubling the speed gives four times the kinetic energy, so the brakes must do about four times the work and the braking distance becomes roughly four times greater." },
      { g: 9, marks: 6, q: "0.8 kg of water at 15 degrees C is heated by a 500 W immersion heater for 3 minutes. The specific heat capacity of water is 4200 J/kg degrees C. Calculate the final temperature, assuming no energy is wasted, and explain why the real temperature would be lower.", scheme: ["E = P x t = 500 x 180 = 90000 J", "change in theta = E / (m x c) = 90000 / (0.8 x 4200) = 26.8 degrees C (approx)", "Final temp = 15 + 26.8 = 41.8 degrees C", "In reality some energy is transferred to the surroundings / container", "So less energy heats the water", "Real final temperature would be lower"], answer: "E = Pt = 500 x 180 = 90 000 J. Δθ = E ÷ (mc) = 90 000 ÷ (0.8 x 4200) = 90 000 ÷ 3360 = 26.8°C. Final temperature = 15 + 26.8 = 41.8°C. In reality some energy is dissipated to the container and surroundings, so less energy heats the water and the real final temperature would be lower." },
      { g: 9, marks: 6, q: "Evaluate the use of wind, nuclear and fossil fuels for a country's electricity supply, considering reliability, environmental impact and running costs, and give a justified conclusion.", scheme: ["Wind: renewable, low carbon dioxide, but unreliable and needs many turbines", "Nuclear: reliable, low carbon dioxide, but radioactive waste and high costs", "Fossil fuels: reliable and flexible, but non-renewable and release carbon dioxide", "Running costs: wind/nuclear low fuel cost, fossil fuel cost rising", "Reliability trade-off between renewable and non-renewable", "Justified conclusion e.g. a mix balancing reliability and low emissions"], answer: "Wind is renewable with low carbon dioxide but is unreliable and needs many turbines over large areas. Nuclear is reliable and low carbon but produces radioactive waste and is expensive to build and decommission. Fossil fuels are reliable and flexible but are non-renewable and release carbon dioxide. A sensible conclusion is to use a mix: renewables and nuclear to cut emissions, with some flexible sources to keep the supply reliable during peak demand." },
      { g: 9, marks: 6, q: "A ski jumper of mass 70 kg starts from rest and descends a vertical height of 40 m. Take g = 9.8 N/kg. Calculate the theoretical speed at the bottom, then, given the real speed is 25 m/s, calculate the efficiency of the energy transfer and explain the difference.", scheme: ["Ep = m x g x h = 70 x 9.8 x 40 = 27440 J", "Theoretical: 27440 = 0.5 x 70 x v^2 so v^2 = 784, v = 28 m/s", "Real Ek = 0.5 x 70 x 25^2 = 21875 J", "efficiency = 21875 / 27440 = 0.797 (80%)", "Difference due to friction and air resistance dissipating energy as heat/sound"], answer: "Ep = mgh = 70 x 9.8 x 40 = 27 440 J. Theoretical speed: 27 440 = 0.5 x 70 x v², v² = 784, v = 28 m/s. Real Ek = 0.5 x 70 x 25² = 21 875 J, so efficiency = 21 875 ÷ 27 440 = 0.80 (80%). The difference is because friction with the snow and air resistance dissipate energy to the thermal store as heat and some as sound." },
      { g: 9, marks: 6, q: "Explain fully, using the principle of conservation of energy, the energy stores and transfers that take place from the moment a diver stands on a springboard to the moment they hit the water.", scheme: ["Standing high up: gravitational potential store", "Bending the board: energy to elastic potential store", "Board straightens: elastic to kinetic and gravitational (upwards)", "Rising: kinetic transfers to gravitational store", "Falling: gravitational transfers to kinetic store", "Total energy conserved; some dissipated as heat/sound throughout"], answer: "Standing on the raised board the diver has a gravitational potential store. Pressing the board down transfers energy to an elastic potential store; as the board straightens this transfers to kinetic and gravitational stores, pushing the diver up. Rising, the kinetic store transfers back to the gravitational store, and falling, the gravitational store transfers to the kinetic store until impact. Throughout, the total energy is conserved, though some is continually dissipated to the thermal store as heat and sound." },
      { g: 9, marks: 6, q: "A house loses heat at a rate of 3000 W. Loft insulation costing 400 pounds reduces this by 20%, and each joule of gas costs 0.000006 pounds. Assuming the heating runs for an average of 8 hours a day, calculate the annual saving and the payback time. (Use 365 days.)", scheme: ["Power saved = 0.20 x 3000 = 600 W", "Energy saved per day = 600 x 8 x 3600 = 17280000 J", "Annual energy saved = 17280000 x 365 = 6.31 x 10^9 J", "Annual cost saving = 6.31 x 10^9 x 0.000006 = 37.85 pounds (approx)", "Payback = cost / annual saving = 400 / 37.85", "= about 10.6 years"], answer: "Power saved = 0.20 x 3000 = 600 W. Energy saved per day = 600 x 8 x 3600 = 17 280 000 J. Per year = 17 280 000 x 365 = 6.31 x 10^9 J. Annual saving = 6.31 x 10^9 x 0.000006 = 37.85 pounds. Payback time = 400 ÷ 37.85 = about 10.6 years." },
      { g: 9, marks: 6, q: "Two metal blocks, aluminium (specific heat capacity 900 J/kg degrees C) and copper (390 J/kg degrees C), each of mass 1 kg, are given 9000 J of energy. Calculate the temperature rise of each and explain, in terms of particles, why they differ.", scheme: ["Aluminium: change in theta = E / (m x c) = 9000 / (1 x 900) = 10 degrees C", "Copper: change in theta = 9000 / (1 x 390) = 23.1 degrees C (approx)", "Copper has lower specific heat capacity so larger temperature rise", "Specific heat capacity is energy to raise 1 kg by 1 degrees C", "Depends on energy needed to increase kinetic energy of particles", "Copper particles need less energy per degree so heat up more"], answer: "Aluminium: Δθ = 9000 ÷ (1 x 900) = 10°C. Copper: Δθ = 9000 ÷ (1 x 390) = 23.1°C. Copper has the lower specific heat capacity, so it rises more in temperature. Specific heat capacity is the energy needed to raise 1 kg by 1°C; it depends on how much energy is needed to increase the kinetic energy of the particles, and copper's particles need less energy per degree, so it heats up more for the same energy." },
      { g: 9, marks: 6, q: "A wind turbine has blades that sweep an area giving it a maximum power of 2 MW, but it typically operates at 30% of this. Calculate the energy generated in one day of typical operation, and evaluate whether wind is a good choice compared with a 2 MW gas turbine that runs continuously.", scheme: ["Average power = 0.30 x 2000000 = 600000 W", "Energy in a day = P x t = 600000 x 86400 = 5.18 x 10^10 J", "Gas turbine energy = 2000000 x 86400 = 1.728 x 10^11 J", "Wind produces far less energy per day (intermittent/unreliable)", "But wind is renewable and produces no carbon dioxide when running", "Justified conclusion e.g. wind good for cutting emissions but needs backup"], answer: "Average wind power = 0.30 x 2 000 000 = 600 000 W. Energy in a day = 600 000 x 86 400 = 5.18 x 10^10 J. The gas turbine gives 2 000 000 x 86 400 = 1.728 x 10^11 J, over three times as much, because it runs continuously. Wind produces less and is unreliable, but it is renewable and gives off no carbon dioxide when running. Overall, wind is a good choice for reducing emissions but needs reliable backup for when the wind does not blow." },
      { g: 9, marks: 6, q: "A 250 g mass on a spring (spring constant 40 N/m) is pulled down 0.2 m and released. Calculate the elastic potential energy stored, the maximum speed of the mass, and explain why in practice it does not keep oscillating forever.", scheme: ["Ee = 0.5 x k x e^2 = 0.5 x 40 x 0.2^2 = 0.8 J", "At the fastest point Ee transfers to Ek: 0.8 = 0.5 x 0.25 x v^2", "v^2 = 0.8 / 0.125 = 6.4, v = 2.53 m/s (approx)", "Energy dissipated by air resistance/friction to thermal store", "Amplitude decreases each swing", "Eventually all energy dissipated so it stops"], answer: "Ee = ½ke² = 0.5 x 40 x 0.2² = 0.8 J. At the fastest point this becomes kinetic energy: 0.8 = 0.5 x 0.25 x v², so v² = 0.8 ÷ 0.125 = 6.4, giving v = 2.53 m/s. In practice air resistance and friction dissipate energy to the thermal store each swing, so the amplitude decreases and the mass eventually stops oscillating." },
      { g: 9, marks: 6, q: "Explain fully how energy is dissipated in everyday devices, why no device can be 100% efficient, and describe two methods used to reduce wasted energy transfers, linking each to the store the energy would otherwise be lost to.", scheme: ["In every transfer some energy spreads out to less useful stores", "Usually to the thermal store of the surroundings (and sound)", "This dissipated energy is spread out and cannot be usefully recovered", "Conservation of energy means output cannot exceed input, and some is always wasted", "Method 1: lubrication reduces friction, cutting energy lost to thermal store", "Method 2: insulation reduces the rate of heat loss to the surroundings' thermal store"], answer: "In every energy transfer some energy is dissipated, spreading out to less useful stores, usually the thermal store of the surroundings and some as sound; once spread out it cannot be usefully recovered. Because energy is conserved, the useful output can never exceed the input, and since some is always wasted, no device can be 100% efficient. Lubrication reduces friction between moving parts, cutting the energy that would be lost to the thermal store as heat, and insulation reduces the rate at which heat is lost to the surroundings' thermal store, so both increase efficiency." },
      { g: 9, marks: 5, q: "A pump lifts 1500 kg of water to a tank 20 m above in 50 s, using 8400 W of electrical power. Take g = 9.8 N/kg. Calculate the efficiency and suggest two reasons it is not 100%.", scheme: ["Ep = m x g x h = 1500 x 9.8 x 20 = 294000 J", "Useful power = E / t = 294000 / 50 = 5880 W", "efficiency = 5880 / 8400 = 0.7 (70%)", "Energy wasted as heat in the motor (friction/electrical resistance)", "Energy wasted as sound / heating the water and pipes"], answer: "Ep = mgh = 1500 x 9.8 x 20 = 294 000 J. Useful power = 294 000 ÷ 50 = 5880 W. Efficiency = 5880 ÷ 8400 = 0.70 (70%). It is not 100% because energy is wasted as heat in the motor due to friction and electrical resistance, and some is lost as sound and in heating the water and pipes." },
      { g: 9, marks: 6, q: "Describe and explain, in terms of energy stores, transfers and dissipation, everything that happens to the energy from the chemical store of petrol in a car until the car is brought to rest by braking.", scheme: ["Chemical store of fuel released by combustion", "Transferred to thermal store, doing work to move pistons (kinetic)", "Kinetic store of the car increases as it speeds up", "Some energy always wasted as heat/sound (engine, friction, air resistance)", "On braking, friction transfers kinetic store to thermal store of brakes", "Total energy conserved but ends up dissipated to the surroundings"], answer: "Burning petrol releases energy from its chemical store, mostly to a thermal store, which does work on the pistons and transfers energy to the kinetic store of the car so it speeds up. Throughout, energy is continually wasted as heat and sound in the engine and through friction and air resistance. When braking, friction transfers the kinetic store to the thermal store of the brakes. The total energy is conserved, but it all ends up dissipated and spread out to the thermal store of the surroundings." },
      { g: 9, marks: 5, q: "A 2 kg block slides along a rough surface and is brought to rest by friction over a distance of 5 m. It was initially moving at 4 m/s. Calculate the average friction force acting on it.", scheme: ["Ek = 0.5 x m x v^2 = 0.5 x 2 x 4^2 = 16 J", "Work done by friction = kinetic energy lost = 16 J", "W = F x s so F = W / s = 16 / 5", "= 3.2 N"], answer: "Ek = ½mv² = 0.5 x 2 x 4² = 16 J. All of this is transferred by the friction force doing work, so W = 16 J. Since W = Fs, F = W ÷ s = 16 ÷ 5 = 3.2 N." },
      { g: 9, marks: 6, q: "Compare tidal power and wave power as marine energy resources, and evaluate their suitability for providing a reliable national electricity supply.", scheme: ["Tidal: uses a barrage across an estuary, driven by the tides", "Tidal is very predictable (tide times known) but only generates at certain times", "Wave: uses the movement of surface waves, less predictable", "Both renewable and low carbon dioxide", "Both have high building costs and can affect marine habitats", "Justified conclusion e.g. tidal more reliable/predictable but neither alone gives constant supply"], answer: "Tidal power uses a barrage across an estuary driven by the rise and fall of the tides, which is very predictable but only generates around high and low tide. Wave power uses the movement of surface waves and is less predictable as it depends on the weather. Both are renewable and low in carbon dioxide, but both have high building costs and can damage marine habitats. Tidal is more reliable because tides are predictable, but neither on its own can provide a constant national supply, so they would need to be combined with other sources." },
      { g: 9, marks: 6, q: "An electric car is 90% efficient and a petrol car is 30% efficient. Both need 150 000 J of useful energy to complete a journey. Calculate the total input energy each requires, and discuss two further factors needed to judge which is better for the environment.", scheme: ["Electric: total = useful / efficiency = 150000 / 0.9 = 166667 J (approx)", "Petrol: total = 150000 / 0.3 = 500000 J", "Electric car uses far less input energy for the same journey", "Factor 1: how the electricity is generated (renewable vs fossil fuel)", "Factor 2: emissions/energy in manufacturing and battery production/disposal"], answer: "Electric car input = 150 000 ÷ 0.9 = 166 667 J. Petrol car input = 150 000 ÷ 0.3 = 500 000 J, so the electric car needs about three times less input energy for the same journey. To judge which is better for the environment you also need to consider how the electricity is generated, since fossil-fuel electricity still causes emissions, and the energy and emissions involved in manufacturing and disposing of the cars, especially the batteries." },
    ],
    "2. Electricity": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What is the unit of electric current?", scheme: ["Ampere / amp (A)"], answer: "The ampere (amp), symbol A." },
      { g: 4, marks: 1, q: "What is the unit of potential difference (voltage)?", scheme: ["Volt (V)"], answer: "The volt, symbol V." },
      { g: 4, marks: 1, q: "What is the unit of resistance?", scheme: ["Ohm (symbol shown as the Greek letter)"], answer: "The ohm, Ω." },
      { g: 4, marks: 1, q: "What component is used to measure current in a circuit?", scheme: ["Ammeter"], answer: "An ammeter." },
      { g: 4, marks: 1, q: "What component is used to measure potential difference?", scheme: ["Voltmeter"], answer: "A voltmeter." },
      { g: 4, marks: 1, q: "In a circuit, how is an ammeter connected relative to the component?", scheme: ["In series"], answer: "In series with the component." },
      { g: 4, marks: 1, q: "In a circuit, how is a voltmeter connected relative to the component?", scheme: ["In parallel"], answer: "In parallel across the component." },
      { g: 4, marks: 1, q: "What does the abbreviation d.c. stand for?", scheme: ["Direct current"], answer: "Direct current." },
      { g: 4, marks: 1, q: "What does the abbreviation a.c. stand for?", scheme: ["Alternating current"], answer: "Alternating current." },
      { g: 4, marks: 1, q: "Is UK mains electricity a.c. or d.c.?", scheme: ["a.c. / alternating current"], answer: "Alternating current (a.c.)." },
      { g: 4, marks: 1, q: "Name the three wires found in a UK three-core cable.", scheme: ["Live, neutral and earth"], answer: "The live, neutral and earth wires." },
      { g: 4, marks: 1, q: "What is the colour of the insulation on the live wire in a UK plug?", scheme: ["Brown"], answer: "Brown." },
      { g: 4, marks: 1, q: "What is the colour of the insulation on the neutral wire in a UK plug?", scheme: ["Blue"], answer: "Blue." },
      { g: 4, marks: 1, q: "What is the symbol and unit of electric charge?", scheme: ["Coulomb (C)"], answer: "The coulomb, symbol C." },
      { g: 4, marks: 1, q: "What is the unit of electrical power?", scheme: ["Watt (W)"], answer: "The watt, symbol W." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 1, q: "State what electric current is.", scheme: ["The rate of flow of (electric) charge"], answer: "Current is the rate of flow of electric charge." },
      { g: 5, marks: 2, q: "State the equation linking charge, current and time, and give the units.", scheme: ["Q = I x t", "charge in coulombs (C), current in amps (A), time in seconds (s)"], answer: "Q = I x t, where charge Q is in coulombs, current I in amps and time t in seconds." },
      { g: 5, marks: 1, q: "State the equation that links potential difference, current and resistance.", scheme: ["V = I x R"], answer: "V = I x R." },
      { g: 5, marks: 2, q: "Describe the colours of the earth wire in a UK plug.", scheme: ["Green and yellow (striped)"], answer: "Green and yellow stripes." },
      { g: 5, marks: 2, q: "State the UK mains voltage and frequency.", scheme: ["230 V", "50 Hz"], answer: "The UK mains supply is about 230 V at a frequency of 50 Hz." },
      { g: 5, marks: 1, q: "What happens to the resistance of an LDR as the light gets brighter?", scheme: ["Resistance decreases"], answer: "Its resistance decreases as light intensity increases." },
      { g: 5, marks: 1, q: "What happens to the resistance of a thermistor as its temperature rises?", scheme: ["Resistance decreases"], answer: "Its resistance decreases as temperature increases." },
      { g: 5, marks: 2, q: "In a series circuit, what is true about the current at different points?", scheme: ["The current is the same", "At all points / everywhere in the series circuit"], answer: "The current is the same at every point in a series circuit." },
      { g: 5, marks: 2, q: "In a parallel circuit, what is true about the potential difference across each branch?", scheme: ["The p.d. is the same", "Across each branch / component"], answer: "The potential difference is the same across each parallel branch." },
      { g: 5, marks: 1, q: "State the difference between a.c. and d.c. in terms of current direction.", scheme: ["a.c. changes direction; d.c. flows in one direction only"], answer: "Alternating current repeatedly changes direction, while direct current flows in one direction only." },
      { g: 5, marks: 2, q: "Name the circuit symbol described: two parallel lines, one long and one short.", scheme: ["A cell"], answer: "A cell." },
      { g: 5, marks: 1, q: "What is the potential difference of the live wire relative to earth in a UK supply?", scheme: ["About 230 V"], answer: "About 230 V." },
      { g: 5, marks: 1, q: "State the potential difference of the neutral wire (relative to earth) during normal use.", scheme: ["About 0 V"], answer: "About 0 V." },
      { g: 5, marks: 2, q: "Give one everyday use of a thermistor and one of an LDR.", scheme: ["Thermistor: thermostat / temperature sensor", "LDR: automatic lights / light sensor"], answer: "A thermistor is used in a thermostat and an LDR is used in automatic street lights." },
      { g: 5, marks: 1, q: "What is the name for the type of conductor whose resistance stays constant at constant temperature?", scheme: ["An ohmic conductor"], answer: "An ohmic conductor." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "A current of 3 A flows for 10 s. Calculate the charge that flows.", scheme: ["Q = I x t = 3 x 10", "= 30 C"], answer: "Q = I x t = 3 x 10 = 30 C." },
      { g: 6, marks: 2, q: "A charge of 60 C passes a point in 20 s. Calculate the current.", scheme: ["I = Q / t = 60 / 20", "= 3 A"], answer: "I = Q ÷ t = 60 ÷ 20 = 3 A." },
      { g: 6, marks: 2, q: "A resistor has a p.d. of 6 V across it and a current of 2 A through it. Calculate its resistance.", scheme: ["R = V / I = 6 / 2", "= 3 ohms"], answer: "R = V ÷ I = 6 ÷ 2 = 3 Ω." },
      { g: 6, marks: 2, q: "Two resistors of 4 ohms and 6 ohms are connected in series. Calculate the total resistance.", scheme: ["Series: add resistances = 4 + 6", "= 10 ohms"], answer: "In series the resistances add: 4 + 6 = 10 Ω." },
      { g: 6, marks: 2, q: "Describe the shape of the I-V graph for an ohmic conductor at constant temperature.", scheme: ["A straight line through the origin", "Current is directly proportional to p.d."], answer: "It is a straight line through the origin, showing current is directly proportional to potential difference." },
      { g: 6, marks: 3, q: "Explain why the resistance of a filament lamp increases as the current increases.", scheme: ["Current heats the filament", "Temperature rises", "Ions/atoms vibrate more so resistance increases"], answer: "The current heats the filament, raising its temperature; the metal ions vibrate more and obstruct the electrons, so the resistance increases." },
      { g: 6, marks: 2, q: "Describe the I-V characteristic of a diode.", scheme: ["Current only flows in one direction (forward)", "Very high resistance in the reverse direction"], answer: "A diode only lets current flow in one direction (forward); in the reverse direction its resistance is very high so almost no current flows." },
      { g: 6, marks: 2, q: "In a series circuit the supply is 12 V and one component has 8 V across it. Calculate the p.d. across the only other component.", scheme: ["Series p.d. shared: 12 - 8", "= 4 V"], answer: "The p.d. is shared, so 12 - 8 = 4 V." },
      { g: 6, marks: 3, q: "Explain why the total resistance of two resistors in parallel is less than the smaller resistor.", scheme: ["There are more paths for the current", "Total current increases for the same p.d.", "So overall resistance is lower"], answer: "Adding a parallel branch gives the current more paths, so a larger total current flows for the same p.d., meaning the overall resistance is lower than either resistor." },
      { g: 6, marks: 2, q: "A lamp is rated at 60 W and operates at 230 V. Calculate the current through it.", scheme: ["I = P / V = 60 / 230", "= 0.26 A"], answer: "I = P ÷ V = 60 ÷ 230 = 0.26 A." },
      { g: 6, marks: 3, q: "Explain the function of the earth wire and fuse together in a mains appliance.", scheme: ["Earth wire carries current to earth if a fault makes the case live", "Large current melts/blows the fuse", "This disconnects the live wire, making it safe"], answer: "If a fault connects the live wire to the metal case, the earth wire carries a large current to earth; this surge melts the fuse, breaking the live wire and making the appliance safe." },
      { g: 6, marks: 2, q: "State two similarities and one use of the National Grid transformers.", scheme: ["Step-up increases p.d. / step-down decreases p.d.", "Used to transmit power efficiently at high voltage"], answer: "Step-up transformers raise the p.d. and step-down transformers lower it, allowing power to be transmitted efficiently at high voltage." },
      { g: 6, marks: 2, q: "Calculate the energy transferred when a 2000 W kettle runs for 30 s.", scheme: ["E = P x t = 2000 x 30", "= 60000 J"], answer: "E = P x t = 2000 x 30 = 60 000 J (60 kJ)." },
      { g: 6, marks: 2, q: "Explain why a plastic rod becomes charged when rubbed with a cloth.", scheme: ["Electrons are transferred by friction", "Rod gains or loses electrons, becoming charged"], answer: "Rubbing transfers electrons between the rod and cloth; the rod gains or loses electrons and so becomes electrically charged." },
      { g: 6, marks: 2, q: "A resistor carries 2 A and has a resistance of 5 ohms. Calculate the power dissipated using P = I^2 R.", scheme: ["P = I^2 x R = 2^2 x 5", "= 20 W"], answer: "P = I^2 x R = 4 x 5 = 20 W." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "A hairdryer draws a current of 4 A from the 230 V mains. Calculate its power.", scheme: ["P = V x I", "= 230 x 4", "= 920 W"], answer: "P = V x I = 230 x 4 = 920 W." },
      { g: 7, marks: 3, q: "A charge of 40 C is moved through a potential difference of 12 V. Calculate the energy transferred.", scheme: ["E = Q x V", "= 40 x 12", "= 480 J"], answer: "E = Q x V = 40 x 12 = 480 J." },
      { g: 7, marks: 3, q: "A 9 V battery drives a current of 0.5 A through a resistor. Calculate the resistance.", scheme: ["R = V / I", "= 9 / 0.5", "= 18 ohms"], answer: "R = V ÷ I = 9 ÷ 0.5 = 18 Ω." },
      { g: 7, marks: 4, q: "Describe how you would investigate how the current through a resistor varies with the potential difference across it.", scheme: ["Set up resistor with ammeter in series and voltmeter in parallel", "Use a variable resistor to change the p.d.", "Record several pairs of current and p.d. readings", "Plot a graph of current against p.d."], answer: "Connect the resistor with an ammeter in series and a voltmeter in parallel, use a variable resistor to change the p.d., record matching current and p.d. readings, then plot current against potential difference." },
      { g: 7, marks: 3, q: "A 3 A current flows for 5 minutes. Calculate the charge transferred, giving the time in the correct unit.", scheme: ["t = 5 x 60 = 300 s", "Q = I x t = 3 x 300", "= 900 C"], answer: "Time = 5 x 60 = 300 s, so Q = I x t = 3 x 300 = 900 C." },
      { g: 7, marks: 4, q: "Two resistors, 3 ohms and 6 ohms, are in series across a 9 V supply. Calculate the total resistance and the current from the supply.", scheme: ["Total R = 3 + 6 = 9 ohms", "I = V / R", "= 9 / 9", "= 1 A"], answer: "Total resistance = 3 + 6 = 9 Ω, so current = V ÷ R = 9 ÷ 9 = 1 A." },
      { g: 7, marks: 3, q: "Explain why electrical power is transmitted across the National Grid at very high voltage.", scheme: ["High voltage means a smaller current for the same power", "Lower current reduces heating losses in the cables (P = I^2 R)", "So energy is transmitted more efficiently"], answer: "For a given power a higher voltage means a smaller current; because power lost in the cables is I^2 x R, a smaller current greatly reduces heating losses, so transmission is more efficient." },
      { g: 7, marks: 3, q: "A 2.5 kW electric heater is used for 3 minutes. Calculate the energy it transfers in joules.", scheme: ["P = 2500 W, t = 180 s", "E = P x t = 2500 x 180", "= 450000 J"], answer: "E = P x t = 2500 x 180 = 450 000 J (450 kJ)." },
      { g: 7, marks: 3, q: "A device transfers 1200 J of energy when 100 C of charge passes through it. Calculate the potential difference.", scheme: ["V = E / Q", "= 1200 / 100", "= 12 V"], answer: "V = E ÷ Q = 1200 ÷ 100 = 12 V." },
      { g: 7, marks: 3, q: "Explain how an LDR can be used in a circuit to switch on a lamp when it gets dark.", scheme: ["In darkness the LDR resistance is high", "This changes the p.d. shared in the circuit", "The higher p.d. across the sensor switches the lamp on"], answer: "In the dark the LDR has a high resistance, so it takes a larger share of the p.d.; this rise in voltage is used to switch the lamp on." },
      { g: 7, marks: 3, q: "A resistor dissipates 45 W when a current of 3 A flows through it. Use P = I^2 R to find its resistance.", scheme: ["P = I^2 x R so R = P / I^2", "= 45 / 9", "= 5 ohms"], answer: "R = P ÷ I^2 = 45 ÷ 9 = 5 Ω." },
      { g: 7, marks: 3, q: "Explain why connecting more lamps in parallel does not make each one dimmer, unlike adding them in series.", scheme: ["In parallel each lamp gets the full supply p.d.", "In series the p.d. is shared between the lamps", "So parallel lamps stay at full brightness"], answer: "In parallel every lamp receives the full supply p.d., so each stays bright, whereas in series the p.d. is shared, giving each lamp less voltage and making them dimmer." },
      { g: 7, marks: 3, q: "A step-down transformer reduces the voltage from 20 kV to 230 V for homes. Explain the purpose of this transformer.", scheme: ["Power is transmitted at high voltage for efficiency", "The high voltage is dangerous / unsuitable for homes", "The transformer lowers it to a safe usable value"], answer: "Power travels at high voltage to reduce energy loss, but that voltage is unsafe for homes, so the step-down transformer reduces it to a safe, usable 230 V." },
      { g: 7, marks: 3, q: "A kettle transfers 360 000 J of energy in 3 minutes. Calculate its power.", scheme: ["t = 180 s", "P = E / t = 360000 / 180", "= 2000 W"], answer: "P = E ÷ t = 360 000 ÷ 180 = 2000 W (2 kW)." },
      { g: 7, marks: 4, q: "Describe how to obtain the I-V characteristic of a filament lamp, including how to get readings for negative values.", scheme: ["Connect ammeter in series and voltmeter in parallel with the lamp", "Vary p.d. with a variable resistor and record I and V", "Reverse the connections to the supply to get negative values", "Plot current against p.d."], answer: "Connect an ammeter in series and voltmeter in parallel, vary the p.d. with a variable resistor recording current and p.d., then reverse the supply connections to obtain negative readings, and plot current against p.d." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "A 230 V washing machine has a power of 2300 W. Calculate the current it draws and the correct fuse (3 A, 5 A or 13 A) to use.", scheme: ["I = P / V = 2300 / 230 = 10 A", "Fuse must be just above the normal current", "10 A is above 5 A, so choose 13 A", "13 A fuse"], answer: "I = P ÷ V = 2300 ÷ 230 = 10 A. A fuse rated just above this is needed, so the 13 A fuse is chosen." },
      { g: 8, marks: 4, q: "A 4 ohm and a 6 ohm resistor are connected in parallel across a 12 V supply. Calculate the current through each resistor and the total current.", scheme: ["Same p.d. of 12 V across each", "I1 = 12 / 4 = 3 A", "I2 = 12 / 6 = 2 A", "Total = 3 + 2 = 5 A"], answer: "Each has 12 V across it: I1 = 12 ÷ 4 = 3 A and I2 = 12 ÷ 6 = 2 A, so total current = 3 + 2 = 5 A." },
      { g: 8, marks: 4, q: "Explain fully, in terms of current and resistance, why transmitting power at high voltage reduces energy wasted in the cables.", scheme: ["For fixed power, P = V x I so higher V gives lower I", "Power lost in cables = I^2 x R", "Lost power depends on the square of the current", "So reducing I greatly reduces wasted energy"], answer: "For a fixed power, P = V x I, so raising the voltage lowers the current. Because power wasted in the cables equals I^2 x R and depends on the square of the current, a smaller current greatly reduces the heat energy lost." },
      { g: 8, marks: 4, q: "A motor is connected to a 12 V supply and 240 C of charge passes through it in 2 minutes. Calculate the current and the energy transferred.", scheme: ["t = 120 s, I = Q / t = 240 / 120 = 2 A", "E = Q x V = 240 x 12", "= 2880 J"], answer: "I = Q ÷ t = 240 ÷ 120 = 2 A, and E = Q x V = 240 x 12 = 2880 J." },
      { g: 8, marks: 4, q: "Explain how the I-V graphs of an ohmic resistor and a filament lamp differ, and why.", scheme: ["Ohmic resistor: straight line, constant resistance", "Lamp: S-shaped curve, resistance increases", "Lamp filament heats up as current rises", "Higher temperature increases resistance"], answer: "An ohmic resistor gives a straight line because its resistance is constant, while a filament lamp gives an S-shaped curve because the filament heats up as the current increases, and the rising temperature increases its resistance." },
      { g: 8, marks: 4, q: "A 12 V circuit contains a fixed 300 ohm resistor in series with a thermistor. When cold the thermistor is 900 ohms. Calculate the p.d. across the fixed resistor when cold.", scheme: ["Total R = 300 + 900 = 1200 ohms", "I = V / R = 12 / 1200 = 0.01 A", "V across fixed resistor = I x R = 0.01 x 300", "= 3 V"], answer: "Total resistance = 300 + 900 = 1200 Ω, so I = 12 ÷ 1200 = 0.01 A, and the p.d. across the fixed resistor = 0.01 x 300 = 3 V." },
      { g: 8, marks: 4, q: "Explain how a fuse and the earth wire protect a user if a fault makes the metal case of an appliance live.", scheme: ["Earth wire is a low resistance path from the case to earth", "A large current flows through live and earth", "This surge melts the fuse in the live wire", "Live is disconnected so the case is no longer live"], answer: "The earth wire gives a low-resistance path from the case to earth, so a large current flows if the case becomes live; this surge melts the fuse in the live wire, disconnecting the supply so the case can no longer give a shock." },
      { g: 8, marks: 4, q: "A 60 W lamp and a 100 W lamp are both designed for the 230 V mains. Calculate the resistance of each and state which has the greater resistance.", scheme: ["P = V^2 / R so R = V^2 / P", "60 W: R = 230^2 / 60 = 882 ohms", "100 W: R = 230^2 / 100 = 529 ohms", "The 60 W lamp has the greater resistance"], answer: "Using R = V^2 ÷ P: the 60 W lamp is 52900 ÷ 60 = 882 Ω and the 100 W lamp is 52900 ÷ 100 = 529 Ω, so the 60 W lamp has the greater resistance." },
      { g: 8, marks: 4, q: "Explain, in terms of electrons, what happens when a polythene rod is rubbed with a duster and becomes negatively charged.", scheme: ["Friction transfers electrons from the duster to the rod", "Rod gains electrons so becomes negatively charged", "Duster loses electrons so becomes positively charged", "Only electrons move, not the positive nuclei"], answer: "Friction transfers electrons from the duster onto the rod, so the rod gains electrons and becomes negatively charged while the duster loses electrons and becomes positive; only the electrons move." },
      { g: 8, marks: 4, q: "A student measures a p.d. of 5 V and a current of 0.2 A for a component, then 8 V and 0.2 A. Explain what this tells them about the component and calculate the resistance at each point.", scheme: ["R1 = 5 / 0.2 = 25 ohms", "R2 = 8 / 0.2 = 40 ohms", "Resistance increased as p.d. increased", "So it is not an ohmic conductor (e.g. a filament lamp)"], answer: "R1 = 5 ÷ 0.2 = 25 Ω and R2 = 8 ÷ 0.2 = 40 Ω; the resistance increased, so the component is not ohmic and behaves like a filament lamp." },
      { g: 8, marks: 4, q: "Describe how an electric field around a charged object explains why a spark can jump to an earthed object.", scheme: ["A charged object creates an electric field around it", "Field is strongest where charge is concentrated", "A large enough p.d. ionises the air", "Charge flows as a spark to the earthed object"], answer: "A charged object sets up an electric field, strongest close to it; if the field and p.d. are large enough the air is ionised and becomes conducting, so charge jumps across as a spark to the earthed object." },
      { g: 8, marks: 4, q: "A 2 A current flows through a 12 ohm resistor for 5 minutes. Calculate the energy transferred using P = I^2 R and E = P t.", scheme: ["P = I^2 x R = 4 x 12 = 48 W", "t = 5 x 60 = 300 s", "E = P x t = 48 x 300", "= 14400 J"], answer: "P = I^2 x R = 4 x 12 = 48 W, t = 300 s, so E = P x t = 48 x 300 = 14 400 J." },
      { g: 8, marks: 4, q: "Explain why an ammeter is connected in series but a voltmeter is connected in parallel.", scheme: ["Ammeter measures current, which is the same through series components", "Ammeter has very low resistance so does not change the current", "Voltmeter measures p.d. across a component, so must be across it", "Voltmeter has very high resistance so takes almost no current"], answer: "An ammeter goes in series so the same current passes through it, and it has a very low resistance so it does not reduce that current; a voltmeter goes in parallel to measure the p.d. across a component, and its very high resistance means it draws almost no current." },
      { g: 8, marks: 4, q: "A step-up transformer at a power station raises 25 kV to 400 kV. Explain why this reduces the current in the transmission lines and why that is useful.", scheme: ["Transformers conserve power (input power roughly equals output power)", "Since P = V x I, raising V lowers I for the same power", "Lower current reduces I^2 R heating losses", "So less energy is wasted as heat in the cables"], answer: "The transformer keeps the power roughly constant, so raising the voltage from 25 kV to 400 kV lowers the current; because heating loss is I^2 x R, the smaller current wastes far less energy as heat in the lines." },
      { g: 8, marks: 4, q: "A 13 A fuse is fitted to a lamp that normally draws 0.5 A. Explain why this is unsafe and what fuse should be used.", scheme: ["Fuse only blows well above the normal current", "A fault current below 13 A would not melt it", "Wires could overheat and cause a fire", "A fuse rated just above 0.5 A (e.g. 3 A) should be used"], answer: "A 13 A fuse only blows far above the 0.5 A normal current, so a dangerous fault current below 13 A would flow without melting it, letting the wires overheat; a fuse rated just above 0.5 A, such as 3 A, should be used." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "A 3 ohm resistor and a 6 ohm resistor are connected in parallel, and this combination is in series with a 4 ohm resistor across a 12 V supply. Calculate the total resistance and the current drawn from the supply.", scheme: ["Parallel: 1/R = 1/3 + 1/6 = 1/2 so Rp = 2 ohms", "Total R = 2 + 4 = 6 ohms", "I = V / R = 12 / 6", "= 2 A"], answer: "For the parallel pair, 1/R = 1/3 + 1/6 = 1/2, so Rp = 2 Ω. Total resistance = 2 + 4 = 6 Ω, so current = V ÷ R = 12 ÷ 6 = 2 A." },
      { g: 9, marks: 6, q: "Compare and explain the I-V characteristics of an ohmic resistor, a filament lamp and a diode.", scheme: ["Ohmic resistor: straight line through origin, constant resistance", "Filament lamp: S-shaped curve, resistance rises as it heats up", "Diode: current only in the forward direction", "Diode has very high resistance in reverse", "Resistor obeys V = I x R at constant temperature", "Each shape linked to how resistance behaves"], answer: "An ohmic resistor gives a straight line through the origin because its resistance is constant. A filament lamp gives an S-shaped curve because heating raises its resistance as current increases. A diode conducts only in the forward direction and has a very high resistance in reverse, so current flows one way only." },
      { g: 9, marks: 6, q: "A 230 V mains kettle is rated at 3.0 kW. Calculate the current, the charge that flows in 2 minutes, and the energy transferred in that time. Show full working.", scheme: ["I = P / V = 3000 / 230 = 13.0 A", "t = 2 x 60 = 120 s", "Q = I x t = 13.0 x 120 = 1560 C", "E = P x t = 3000 x 120 = 360000 J", "State units clearly"], answer: "I = P ÷ V = 3000 ÷ 230 = 13.0 A. In 120 s, Q = I x t = 13.0 x 120 = 1560 C, and E = P x t = 3000 x 120 = 360 000 J (360 kJ)." },
      { g: 9, marks: 6, q: "Explain fully how a potential divider using a thermistor can be used to control a heater so it switches off when a room is warm.", scheme: ["Thermistor in series with a fixed resistor across a supply", "As temperature rises the thermistor resistance falls", "Its share of the p.d. decreases (fixed resistor gets more)", "The output p.d. is taken across the thermistor (or fixed resistor)", "This changing voltage operates a switching circuit", "So the heater is switched off when warm"], answer: "The thermistor is placed in series with a fixed resistor across the supply. As the room warms, the thermistor's resistance falls, so it takes a smaller share of the p.d. This changing output voltage is fed to a switching circuit that turns the heater off once the room is warm enough." },
      { g: 9, marks: 6, q: "Explain how the National Grid transmits electricity efficiently, referring to both types of transformer and the physics of energy loss.", scheme: ["Power stations generate at moderate voltage (e.g. 25 kV)", "Step-up transformers raise the voltage to 400 kV for transmission", "For fixed power, higher V means lower current (P = V x I)", "Cable losses are I^2 x R, so lower current wastes far less energy", "Step-down transformers reduce voltage to safe values for use", "Conclusion linking high-voltage transmission to efficiency and safety"], answer: "Power is generated at a moderate voltage, then step-up transformers raise it to around 400 kV for transmission. For a fixed power, higher voltage means lower current, and because cable losses equal I^2 x R the reduced current wastes much less energy as heat. Step-down transformers then lower the voltage to safe values for homes, so the grid is both efficient and safe." },
      { g: 9, marks: 6, q: "A 12 ohm resistor and an unknown resistor R are in series across a 24 V supply. The current is 1.5 A. Calculate R, the p.d. across each resistor, and the power dissipated in R.", scheme: ["Total R = V / I = 24 / 1.5 = 16 ohms", "R = 16 - 12 = 4 ohms", "V across 12 ohm = I x R = 1.5 x 12 = 18 V", "V across R = 1.5 x 4 = 6 V", "Power in R = I^2 x R = 1.5^2 x 4", "= 9 W"], answer: "Total resistance = 24 ÷ 1.5 = 16 Ω, so R = 16 - 12 = 4 Ω. The p.d. across the 12 Ω resistor = 1.5 x 12 = 18 V and across R = 1.5 x 4 = 6 V. Power in R = I^2 x R = 2.25 x 4 = 9 W." },
      { g: 9, marks: 6, q: "Explain fully, in terms of electron flow and temperature, why the resistance of a metallic conductor increases when it gets hot, and how this affects a filament lamp.", scheme: ["Current is a flow of electrons through the metal lattice", "Heating makes the metal ions vibrate more", "Electrons collide more often with the vibrating ions", "This opposes the flow, so resistance increases", "In a filament lamp higher current heats the filament more", "So its resistance rises, giving the curved I-V characteristic"], answer: "Current is the flow of electrons through the metal lattice. When the metal heats up, its ions vibrate more, so the electrons collide with them more often; this greater opposition raises the resistance. In a filament lamp a larger current heats the filament more, increasing its resistance and producing the curved I-V graph." },
      { g: 9, marks: 6, q: "A car battery moves 3000 C of charge through the starter motor in 4 s at a p.d. of 12 V. Calculate the current, the power and the energy transferred, showing all working and units.", scheme: ["I = Q / t = 3000 / 4 = 750 A", "P = V x I = 12 x 750 = 9000 W", "E = Q x V = 3000 x 12 = 36000 J", "or E = P x t = 9000 x 4 = 36000 J", "Units stated (A, W, J)"], answer: "I = Q ÷ t = 3000 ÷ 4 = 750 A. P = V x I = 12 x 750 = 9000 W. E = Q x V = 3000 x 12 = 36 000 J (equal to P x t = 9000 x 4)." },
      { g: 9, marks: 6, q: "Explain fully the dangers of static electricity and describe one way it can be made useful, with reference to electric fields.", scheme: ["Charge builds up on an insulator by friction", "A large p.d. builds up between it and earth", "The electric field can ionise the air", "Causing a spark that may ignite flammable vapours (danger)", "Useful example: electrostatic spraying / smoke precipitator", "Charged particles attracted to oppositely charged surface by the field"], answer: "Friction can build up charge on an insulator, creating a large p.d. to earth; the electric field can ionise the surrounding air and cause a spark, which is dangerous near fuel or dust as it may cause a fire or explosion. The same effect is useful in electrostatic paint spraying, where charged paint droplets are attracted evenly to an oppositely charged object by the electric field." },
      { g: 9, marks: 6, q: "Two identical lamps are connected first in series and then in parallel across the same 12 V supply. Explain, using ideas about p.d., current and resistance, why they are brighter in the parallel arrangement.", scheme: ["In series the 12 V is shared, so each lamp gets 6 V", "Series total resistance is higher so current is lower", "In parallel each lamp gets the full 12 V", "Parallel total resistance is lower so a larger current flows", "Each parallel lamp carries more current at higher p.d.", "Greater power (P = V x I) so brighter in parallel"], answer: "In series the 12 V is shared, so each lamp only receives 6 V, and the higher total resistance means a smaller current, so each is dim. In parallel each lamp gets the full 12 V and the lower total resistance gives a larger current through each lamp, so each transfers more power (P = V x I) and is brighter." },
      { g: 9, marks: 6, q: "Describe a full method to determine how the resistance of a thermistor varies with temperature, and explain how you would present and interpret the results.", scheme: ["Place thermistor in a water bath with a thermometer", "Connect ammeter in series and voltmeter across the thermistor", "Vary the temperature and at each value record V and I", "Calculate R = V / I at each temperature", "Plot resistance against temperature", "Interpret: resistance decreases as temperature increases (negative correlation)"], answer: "Put the thermistor in a water bath with a thermometer, with an ammeter in series and a voltmeter across it. Heat the water and at several temperatures record the current and p.d., then calculate R = V ÷ I each time. Plot resistance against temperature; the graph shows resistance falling as temperature rises." },
      { g: 9, marks: 6, q: "A 500 W and a 1500 W heater are both used on the 230 V mains. Calculate the current in each, the resistance of each, and explain which needs a thicker connecting wire.", scheme: ["500 W: I = 500 / 230 = 2.17 A; R = 230 / 2.17 = 106 ohms", "1500 W: I = 1500 / 230 = 6.52 A; R = 230 / 6.52 = 35.3 ohms", "The 1500 W heater draws a larger current", "A larger current causes more heating in the wire (P = I^2 R)", "So the 1500 W heater needs a thicker (lower resistance) wire"], answer: "500 W: I = 500 ÷ 230 = 2.17 A and R = 230 ÷ 2.17 = 106 Ω. 1500 W: I = 1500 ÷ 230 = 6.52 A and R = 230 ÷ 6.52 = 35.3 Ω. The 1500 W heater draws the larger current, and since heating in the wire is I^2 x R it needs a thicker, lower-resistance wire to avoid overheating." },
      { g: 9, marks: 6, q: "Explain fully why UK mains uses alternating current at 230 V and 50 Hz, and describe the roles of the live, neutral and earth wires.", scheme: ["a.c. repeatedly reverses direction 50 times per second", "a.c. is easily changed by transformers for efficient transmission", "Live wire carries the alternating p.d. (about 230 V) to the appliance", "Neutral wire completes the circuit and is near 0 V", "Earth wire is a safety wire connected to the metal case", "Earth carries fault current to ground and blows the fuse"], answer: "Alternating current reverses direction 50 times each second and can be stepped up and down by transformers, allowing efficient transmission. The live wire carries the alternating p.d. of about 230 V to the appliance, the neutral wire completes the circuit and stays near 0 V, and the earth wire is a safety wire joined to the metal case that carries any fault current to ground and blows the fuse." },
      { g: 9, marks: 6, q: "A resistor obeys Ohm's law. When the p.d. is 4 V the current is 0.5 A. Predict the current at 10 V, calculate the resistance, and explain why your prediction is valid only if the temperature stays constant.", scheme: ["R = V / I = 4 / 0.5 = 8 ohms", "At 10 V: I = V / R = 10 / 8 = 1.25 A", "Ohmic conductor: current proportional to p.d.", "This holds only at constant temperature", "If it heats up, resistance rises and current would be lower than predicted"], answer: "R = V ÷ I = 4 ÷ 0.5 = 8 Ω. At 10 V, I = V ÷ R = 10 ÷ 8 = 1.25 A. This is valid because an ohmic conductor has current proportional to p.d., but only at constant temperature; if it heated up its resistance would rise and the actual current would be less than predicted." },
      { g: 9, marks: 6, q: "A phone charger transfers 18 000 J of energy while delivering 2500 C of charge to the phone. Calculate the p.d. of the charger output, and if this takes 25 minutes calculate the average current and the power. Show all working.", scheme: ["V = E / Q = 18000 / 2500 = 7.2 V", "t = 25 x 60 = 1500 s", "I = Q / t = 2500 / 1500 = 1.67 A", "P = E / t = 18000 / 1500 = 12 W", "or P = V x I = 7.2 x 1.67 = 12 W", "Units stated"], answer: "V = E ÷ Q = 18 000 ÷ 2500 = 7.2 V. In t = 1500 s, I = Q ÷ t = 2500 ÷ 1500 = 1.67 A, and P = E ÷ t = 18 000 ÷ 1500 = 12 W (checks with V x I = 7.2 x 1.67 = 12 W)." },
    ],
    "3. Particle model of matter": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "In which state of matter are the particles most tightly packed?", scheme: ["Solid"], answer: "In a solid." },
      { g: 4, marks: 1, q: "Name the quantity that measures the mass of a material in a given volume.", scheme: ["Density"], answer: "Density." },
      { g: 4, marks: 1, q: "In which state of matter can the particles move around and fill the whole container?", scheme: ["Gas"], answer: "In a gas." },
      { g: 4, marks: 1, q: "State the equation that links density, mass and volume.", scheme: ["density = mass / volume"], answer: "Density = mass ÷ volume." },
      { g: 4, marks: 1, q: "What name is given to the change of state from a liquid to a gas?", scheme: ["Evaporation / boiling"], answer: "Evaporation (or boiling)." },
      { g: 4, marks: 1, q: "What name is given to the change of state from a solid to a liquid?", scheme: ["Melting"], answer: "Melting." },
      { g: 4, marks: 1, q: "Is a change of state a physical change or a chemical change?", scheme: ["Physical (change)"], answer: "A physical change." },
      { g: 4, marks: 1, q: "In which two states are the particles closely packed together?", scheme: ["Solids and liquids"], answer: "Solids and liquids." },
      { g: 4, marks: 1, q: "What causes the pressure of a gas on the walls of its container?", scheme: ["Particles colliding with the walls"], answer: "Gas particles colliding with the walls." },
      { g: 4, marks: 1, q: "Give the SI unit of mass.", scheme: ["Kilogram (kg)"], answer: "The kilogram (kg)." },
      { g: 4, marks: 1, q: "What happens to the mass of a substance when it changes state?", scheme: ["It stays the same / is conserved"], answer: "It stays the same (mass is conserved)." },
      { g: 4, marks: 1, q: "In which state of matter do the particles vibrate about fixed positions?", scheme: ["Solid"], answer: "In a solid." },
      { g: 4, marks: 1, q: "What name is given to the change of state from a gas to a liquid?", scheme: ["Condensation / condensing"], answer: "Condensation." },
      { g: 4, marks: 1, q: "As you heat up a gas at fixed volume, does its pressure increase or decrease?", scheme: ["Increase(s)"], answer: "It increases." },
      { g: 4, marks: 1, q: "Are changes of state reversible or irreversible?", scheme: ["Reversible"], answer: "They are reversible." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 1, q: "Define the density of a material.", scheme: ["Mass per unit volume"], answer: "Density is the mass per unit volume of a material." },
      { g: 5, marks: 2, q: "Describe the arrangement and movement of particles in a solid.", scheme: ["Particles closely packed / in a regular pattern", "Vibrate about fixed positions"], answer: "The particles are closely packed in a regular arrangement and vibrate about fixed positions." },
      { g: 5, marks: 2, q: "Describe the arrangement and movement of particles in a gas.", scheme: ["Particles far apart / spread out", "Move quickly in random directions"], answer: "The particles are far apart and move quickly in random directions." },
      { g: 5, marks: 1, q: "State the equation that links thermal energy, mass, specific heat capacity and temperature change.", scheme: ["change in thermal energy = mass * specific heat capacity * temperature change"], answer: "Change in thermal energy = mass × specific heat capacity × temperature change." },
      { g: 5, marks: 2, q: "Explain why the mass of ice is the same as the mass of water it melts into.", scheme: ["No particles are added or removed", "Mass is conserved in a change of state"], answer: "No particles are added or lost when it melts, so the mass is conserved." },
      { g: 5, marks: 1, q: "State the equation that links thermal energy, mass and specific latent heat.", scheme: ["thermal energy = mass * specific latent heat"], answer: "Energy = mass × specific latent heat." },
      { g: 5, marks: 1, q: "What is meant by the internal energy of a system?", scheme: ["The total kinetic and potential energy of all the particles"], answer: "The total kinetic and potential energy stored by the particles in the system." },
      { g: 5, marks: 2, q: "Explain why a gas has a much lower density than a solid.", scheme: ["Gas particles are much further apart", "Fewer particles in the same volume / less mass per volume"], answer: "The particles in a gas are much further apart, so there is less mass in the same volume, giving a lower density." },
      { g: 5, marks: 1, q: "What is the specific heat capacity of a substance?", scheme: ["Energy to raise the temperature of 1 kg by 1 degree C (1 K)"], answer: "The energy needed to raise the temperature of 1 kg of the substance by 1°C." },
      { g: 5, marks: 1, q: "Name the change of state that happens at the melting point.", scheme: ["Melting (solid to liquid)"], answer: "Melting." },
      { g: 5, marks: 2, q: "State two ways in which liquids differ from solids in their particle model.", scheme: ["Liquid particles can move past each other (solids fixed)", "Liquids take the shape of the container / can flow"], answer: "In a liquid the particles can move past one another and flow, whereas in a solid they stay in fixed positions." },
      { g: 5, marks: 1, q: "What is specific latent heat?", scheme: ["Energy needed to change the state of 1 kg of a substance with no temperature change"], answer: "The energy needed to change the state of 1 kg of a substance without changing its temperature." },
      { g: 5, marks: 2, q: "State the units for mass and volume you would use to calculate density in kg/m^3.", scheme: ["Mass in kilograms (kg)", "Volume in cubic metres (m^3)"], answer: "Mass in kilograms and volume in cubic metres." },
      { g: 5, marks: 1, q: "What happens to the temperature of a substance while it is changing state?", scheme: ["It stays constant / does not change"], answer: "It stays constant." },
      { g: 5, marks: 1, q: "Name the two types of specific latent heat.", scheme: ["Latent heat of fusion and latent heat of vaporisation"], answer: "Specific latent heat of fusion and of vaporisation." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Calculate the density of a block with a mass of 240 g and a volume of 60 cm^3.", scheme: ["density = mass / volume = 240 / 60", "= 4 g/cm^3"], answer: "Density = mass ÷ volume = 240 ÷ 60 = 4 g/cm³." },
      { g: 6, marks: 3, q: "Calculate the density of a 900 kg object with a volume of 0.3 m^3. Give the unit.", scheme: ["density = mass / volume = 900 / 0.3", "= 3000", "= 3000 kg/m^3"], answer: "Density = mass ÷ volume = 900 ÷ 0.3 = 3000 kg/m³." },
      { g: 6, marks: 2, q: "Explain why the temperature stays constant while a pure substance is melting.", scheme: ["Energy is used to break bonds / increase potential energy", "Not used to increase kinetic energy, so temperature is constant"], answer: "The energy is used to break the bonds between particles (increasing potential energy) rather than raising their kinetic energy, so the temperature stays constant." },
      { g: 6, marks: 3, q: "Describe how you could measure the density of a small irregular stone.", scheme: ["Measure mass on a balance", "Find volume by displacement in a measuring cylinder (water rise)", "density = mass / volume"], answer: "Measure the mass on a balance, lower the stone into a measuring cylinder of water and record the volume of water it displaces, then use density = mass ÷ volume." },
      { g: 6, marks: 2, q: "Explain why increasing the temperature of a fixed volume of gas increases its pressure.", scheme: ["Particles move faster / gain kinetic energy", "Collide with the walls more often and harder"], answer: "The particles move faster and hit the walls of the container more often and with more force, so the pressure increases." },
      { g: 6, marks: 2, q: "Calculate the mass of a 0.02 m^3 sample of a material of density 2500 kg/m^3.", scheme: ["mass = density * volume = 2500 * 0.02", "= 50 kg"], answer: "Mass = density × volume = 2500 × 0.02 = 50 kg." },
      { g: 6, marks: 2, q: "Explain why a gas can be compressed but a solid cannot.", scheme: ["Gas particles are far apart with space between them", "Solid particles are touching / closely packed with no space"], answer: "In a gas the particles are far apart with space to be pushed closer, but in a solid the particles are already touching so there is no space to compress." },
      { g: 6, marks: 2, q: "Describe how to measure the density of a regularly shaped block.", scheme: ["Measure mass with a balance", "Measure sides and calculate volume, then density = mass / volume"], answer: "Measure its mass on a balance, measure its dimensions and multiply them to find the volume, then use density = mass ÷ volume." },
      { g: 6, marks: 3, q: "A liquid has a mass of 160 g and a volume of 200 cm^3. Calculate its density.", scheme: ["density = mass / volume = 160 / 200", "= 0.8", "= 0.8 g/cm^3"], answer: "Density = mass ÷ volume = 160 ÷ 200 = 0.8 g/cm³." },
      { g: 6, marks: 2, q: "Explain what internal energy is and what it depends on.", scheme: ["Total kinetic and potential energy of the particles", "Increases when the system is heated / temperature rises"], answer: "Internal energy is the total kinetic and potential energy of all the particles; it increases when the substance is heated." },
      { g: 6, marks: 2, q: "Calculate the volume of an object with a mass of 750 kg and a density of 250 kg/m^3.", scheme: ["volume = mass / density = 750 / 250", "= 3 m^3"], answer: "Volume = mass ÷ density = 750 ÷ 250 = 3 m³." },
      { g: 6, marks: 2, q: "Explain why evaporation is described as a physical change.", scheme: ["No new substance is made", "The change can be reversed (by condensing)"], answer: "No new substance is formed and it can be reversed by condensing, so it is a physical change." },
      { g: 6, marks: 3, q: "Calculate the density of a 300 g block with a volume of 150 cm^3.", scheme: ["density = mass / volume", "= 300 / 150", "= 2 g/cm^3"], answer: "Density = mass ÷ volume = 300 ÷ 150 = 2 g/cm³." },
      { g: 6, marks: 2, q: "Explain why a substance changing from liquid to gas needs more energy than melting the same mass.", scheme: ["Vaporising fully separates the particles (more bonds broken)", "So the latent heat of vaporisation is larger"], answer: "Boiling completely separates the particles, breaking more bonds than melting, so more energy (a larger latent heat) is needed." },
      { g: 6, marks: 2, q: "The flat section of a heating graph shows no rise in temperature. Explain what is happening to the substance there.", scheme: ["The substance is changing state (melting or boiling)", "Energy goes to breaking bonds not raising temperature"], answer: "The substance is changing state, and the energy supplied is breaking bonds between particles rather than raising the temperature." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "Calculate the thermal energy needed to raise the temperature of 2 kg of water by 30 degrees C. The specific heat capacity of water is 4200 J/kg degrees C.", scheme: ["E = m * c * change in temp = 2 * 4200 * 30", "= 252000", "= 252000 J (252 kJ)"], answer: "E = mcΔθ = 2 × 4200 × 30 = 252 000 J (252 kJ)." },
      { g: 7, marks: 3, q: "Calculate the energy needed to melt 0.5 kg of ice. The specific latent heat of fusion of ice is 334000 J/kg.", scheme: ["E = m * L = 0.5 * 334000", "= 167000", "= 167000 J (167 kJ)"], answer: "E = mL = 0.5 × 334 000 = 167 000 J (167 kJ)." },
      { g: 7, marks: 4, q: "A 3 kg metal block is heated from 20 degrees C to 70 degrees C using 69000 J of energy. Calculate its specific heat capacity and give the unit.", scheme: ["change in temp = 70 - 20 = 50", "c = E / (m * change in temp) = 69000 / (3 * 50)", "= 69000 / 150 = 460", "= 460 J/kg degrees C"], answer: "Δθ = 50°C; c = E ÷ (m × Δθ) = 69 000 ÷ (3 × 50) = 460 J/kg°C." },
      { g: 7, marks: 3, q: "Calculate the density of an irregular object of mass 810 g that displaces 300 cm^3 of water. Give the unit.", scheme: ["density = mass / volume = 810 / 300", "= 2.7", "= 2.7 g/cm^3"], answer: "Density = mass ÷ volume = 810 ÷ 300 = 2.7 g/cm³." },
      { g: 7, marks: 4, q: "Calculate the energy needed to boil away 0.2 kg of water already at 100 degrees C. The specific latent heat of vaporisation of water is 2260000 J/kg.", scheme: ["E = m * L", "= 0.2 * 2260000", "= 452000", "= 452000 J (452 kJ)"], answer: "E = mL = 0.2 × 2 260 000 = 452 000 J (452 kJ)." },
      { g: 7, marks: 3, q: "Explain, using the particle model, why the pressure of a fixed mass of gas rises when it is heated at constant volume.", scheme: ["Particles gain kinetic energy and move faster", "They collide with the walls more frequently", "And with greater force, so pressure increases"], answer: "Heating gives the particles more kinetic energy so they move faster, colliding with the walls more often and harder, which increases the pressure." },
      { g: 7, marks: 4, q: "A 0.4 kg block of aluminium is heated with 18000 J of energy. Its specific heat capacity is 900 J/kg degrees C. Calculate the temperature rise.", scheme: ["change in temp = E / (m * c)", "= 18000 / (0.4 * 900)", "= 18000 / 360", "= 50 degrees C"], answer: "Δθ = E ÷ (m × c) = 18 000 ÷ (0.4 × 900) = 50°C." },
      { g: 7, marks: 3, q: "Describe the required practical to measure the specific heat capacity of a metal block.", scheme: ["Measure mass of block; use an electric heater and record energy supplied (joulemeter or power * time)", "Record temperature rise with a thermometer", "Calculate c = E / (m * change in temp)"], answer: "Measure the block's mass, heat it with an electric heater recording the energy supplied and the temperature rise, then calculate c = E ÷ (m × Δθ)." },
      { g: 7, marks: 3, q: "Calculate the mass of copper that can be heated from 15 degrees C to 45 degrees C by 46200 J. The specific heat capacity of copper is 385 J/kg degrees C.", scheme: ["change in temp = 45 - 15 = 30", "m = E / (c * change in temp) = 46200 / (385 * 30)", "= 46200 / 11550 = 4 kg"], answer: "Δθ = 30°C; m = E ÷ (c × Δθ) = 46 200 ÷ (385 × 30) = 4 kg." },
      { g: 7, marks: 3, q: "Explain why the specific latent heat of vaporisation is greater than the specific latent heat of fusion for the same substance.", scheme: ["Boiling separates particles completely, breaking all bonds", "Melting only partly weakens/loosens bonds", "So more energy is needed to vaporise"], answer: "Vaporising completely separates the particles and breaks all the bonds between them, whereas melting only loosens them, so more energy per kilogram is needed to boil." },
      { g: 7, marks: 3, q: "Calculate the energy needed to change 0.3 kg of a substance from solid to liquid at its melting point. Its specific latent heat of fusion is 210000 J/kg.", scheme: ["E = m * L = 0.3 * 210000", "= 63000", "= 63000 J (63 kJ)"], answer: "E = mL = 0.3 × 210 000 = 63 000 J (63 kJ)." },
      { g: 7, marks: 4, q: "500 g of water is cooled and releases 42000 J of energy. The specific heat capacity of water is 4200 J/kg degrees C. Calculate the temperature drop.", scheme: ["m = 500 g = 0.5 kg", "change in temp = E / (m * c) = 42000 / (0.5 * 4200)", "= 42000 / 2100", "= 20 degrees C"], answer: "m = 0.5 kg; Δθ = E ÷ (m × c) = 42 000 ÷ (0.5 × 4200) = 20°C." },
      { g: 7, marks: 3, q: "Explain how the temperature of a gas is related to the average kinetic energy of its particles.", scheme: ["Temperature is a measure of average kinetic energy of the particles", "Higher temperature means greater average kinetic energy", "So the particles move faster"], answer: "The temperature of a gas is a measure of the average kinetic energy of its particles, so a higher temperature means the particles have more kinetic energy and move faster." },
      { g: 7, marks: 3, q: "Explain why an object made of the same material always has the same density regardless of its size.", scheme: ["Density is mass per unit volume", "A larger piece has more mass but proportionally more volume", "So the ratio (density) is unchanged"], answer: "Density is mass ÷ volume; a bigger piece has more mass but a proportionally larger volume, so the ratio stays the same." },
      { g: 7, marks: 3, q: "Calculate the density in kg/m^3 of a cube of side 0.5 m and mass 100 kg.", scheme: ["volume = 0.5 * 0.5 * 0.5 = 0.125 m^3", "density = mass / volume = 100 / 0.125", "= 800 kg/m^3"], answer: "Volume = 0.5³ = 0.125 m³; density = 100 ÷ 0.125 = 800 kg/m³." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "Calculate the total energy needed to heat 0.5 kg of ice at 0 degrees C until it has fully melted and the water reaches 20 degrees C. Latent heat of fusion = 334000 J/kg; c of water = 4200 J/kg degrees C.", scheme: ["Melt: E = m * L = 0.5 * 334000 = 167000 J", "Heat water: E = m * c * change in temp = 0.5 * 4200 * 20 = 42000 J", "Total = 167000 + 42000", "= 209000 J (209 kJ)"], answer: "Melting: 0.5 × 334 000 = 167 000 J. Heating: 0.5 × 4200 × 20 = 42 000 J. Total = 209 000 J (209 kJ)." },
      { g: 8, marks: 4, q: "A 2 kg block of metal is heated by a 50 W heater for 3 minutes and its temperature rises by 15 degrees C. Calculate the specific heat capacity, assuming no losses.", scheme: ["E = power * time = 50 * 180 = 9000 J", "c = E / (m * change in temp) = 9000 / (2 * 15)", "= 9000 / 30", "= 300 J/kg degrees C"], answer: "E = 50 × 180 = 9000 J; c = 9000 ÷ (2 × 15) = 300 J/kg°C." },
      { g: 8, marks: 4, q: "Explain fully, using the particle model, the shape of a heating graph for ice being heated steadily into steam, including the flat sections.", scheme: ["Sloped sections: kinetic energy and temperature rise", "First flat section: melting, bonds partly broken (potential energy), constant temperature", "Second flat section: boiling, particles fully separated, constant temperature", "Slopes differ because states have different specific heat capacities"], answer: "On the sloping parts the particles gain kinetic energy so the temperature rises. The flat sections are melting and boiling, where energy breaks bonds (increasing potential energy) at constant temperature. The boiling plateau is longer because vaporisation needs more energy." },
      { g: 8, marks: 4, q: "In a specific heat capacity practical, the measured value is higher than the true value. Explain why, and suggest one improvement.", scheme: ["Some thermal energy is lost to the surroundings", "So more energy appears needed per degree, raising the calculated c", "Improvement: insulate/lag the block or use a lid"], answer: "Thermal energy is lost to the surroundings, so the energy input seems larger than that used to heat the block, giving a higher calculated value. Insulating the block reduces this error." },
      { g: 8, marks: 4, q: "Calculate the energy released when 0.25 kg of steam at 100 degrees C condenses and the water then cools to 40 degrees C. Latent heat of vaporisation = 2260000 J/kg; c of water = 4200 J/kg degrees C.", scheme: ["Condense: E = m * L = 0.25 * 2260000 = 565000 J", "Cool: E = m * c * change in temp = 0.25 * 4200 * 60 = 63000 J", "Total = 565000 + 63000", "= 628000 J (628 kJ)"], answer: "Condensing: 0.25 × 2 260 000 = 565 000 J. Cooling: 0.25 × 4200 × 60 = 63 000 J. Total = 628 000 J (628 kJ)." },
      { g: 8, marks: 4, q: "Explain why substances with a high specific heat capacity, such as water, are useful in central heating systems and as coolants.", scheme: ["High c means a lot of energy stored per degree of temperature change", "Water can carry/transfer a large amount of energy", "It heats up and cools down slowly", "So it transports heat effectively without large temperature swings"], answer: "Water has a high specific heat capacity, so it can absorb and carry a large amount of energy for each degree of temperature change, heating and cooling slowly, which makes it good for transferring heat in radiators and for cooling." },
      { g: 8, marks: 4, q: "A gas is sealed in a rigid container and warmed. Explain, in terms of particles, what happens to its internal energy and pressure.", scheme: ["Particles gain kinetic energy so internal energy increases", "Particles move faster", "They hit the walls more often and harder", "Volume fixed so pressure increases"], answer: "Warming increases the particles' kinetic energy so the internal energy rises. The faster particles collide with the walls more frequently and with greater force, and because the volume is fixed the pressure increases." },
      { g: 8, marks: 4, q: "Calculate the specific latent heat of fusion of a substance if 88000 J melts 0.4 kg of it at its melting point, and state what the value means.", scheme: ["L = E / m = 88000 / 0.4", "= 220000 J/kg", "Meaning: energy to melt 1 kg with no temperature change", "(220 kJ per kg)"], answer: "L = E ÷ m = 88 000 ÷ 0.4 = 220 000 J/kg. This is the energy needed to melt 1 kg of the substance without a temperature change." },
      { g: 8, marks: 4, q: "Compare the internal energy changes when a substance is heated within one state and when it changes state.", scheme: ["Within a state: kinetic energy increases so temperature rises", "Changing state: potential energy increases, temperature constant", "Both increase the total internal energy", "Bonds are broken (or formed) during a change of state"], answer: "Heating within a state raises the particles' kinetic energy so the temperature increases, while during a change of state the energy raises the potential energy as bonds break, keeping the temperature constant; both increase the total internal energy." },
      { g: 8, marks: 4, q: "A 1.5 kg iron block cools from 200 degrees C to 25 degrees C. The specific heat capacity of iron is 450 J/kg degrees C. Calculate the energy released.", scheme: ["change in temp = 200 - 25 = 175", "E = m * c * change in temp = 1.5 * 450 * 175", "= 1.5 * 450 = 675; 675 * 175", "= 118125 J (about 118 kJ)"], answer: "Δθ = 175°C; E = 1.5 × 450 × 175 = 118 125 J (about 118 kJ)." },
      { g: 8, marks: 4, q: "Explain why a fixed volume of gas exerts less pressure when it is cooled, referring to particle collisions.", scheme: ["Cooling lowers the average kinetic energy of the particles", "Particles move more slowly", "They collide with the walls less often and with less force", "So pressure decreases"], answer: "Cooling reduces the particles' average kinetic energy so they move slower, colliding with the walls less often and with less force, so the pressure falls." },
      { g: 8, marks: 4, q: "Calculate the density of a metal cylinder of mass 1.2 kg, radius 2 cm and height 10 cm. Use volume = pi * r^2 * h and give the answer in g/cm^3.", scheme: ["volume = pi * 2^2 * 10 = pi * 40 = 125.6 cm^3", "mass = 1200 g", "density = 1200 / 125.6", "= 9.55 g/cm^3 (about 9.6)"], answer: "Volume = π × 2² × 10 = 125.6 cm³; mass = 1200 g; density = 1200 ÷ 125.6 = 9.55 g/cm³." },
      { g: 8, marks: 4, q: "Explain how you could accurately determine the specific latent heat of fusion of ice using an electric heater and a balance.", scheme: ["Heat ice at 0 degrees C with a known power for a measured time (E = power * time)", "Measure the mass of water collected from the melted ice", "Use a control with the heater off to allow for melting by the room", "L = E / m using the extra mass melted"], answer: "Melt ice at 0°C with a heater of known power for a measured time to find the energy supplied, measure the mass of melted water, use a heater-off control to correct for room melting, then calculate L = E ÷ m." },
      { g: 8, marks: 4, q: "Two blocks of equal mass, one aluminium (c = 900 J/kg degrees C) and one copper (c = 385 J/kg degrees C), are given the same energy. Explain which reaches the higher temperature.", scheme: ["change in temp = E / (m * c)", "Copper has the lower specific heat capacity", "For the same E and m, lower c gives a bigger temperature rise", "So the copper block reaches the higher temperature"], answer: "Since Δθ = E ÷ (mc), the block with the lower specific heat capacity heats more. Copper has the lower c, so the copper block reaches the higher temperature." },
      { g: 8, marks: 4, q: "Explain why the density of a gas increases when it is compressed at constant temperature.", scheme: ["Same mass of gas / same number of particles", "Volume decreases as it is compressed", "Density = mass / volume, so smaller volume gives higher density"], answer: "Compressing the gas keeps the same mass but reduces the volume, and since density = mass ÷ volume, a smaller volume gives a higher density." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "A 0.3 kg block of ice at -10 degrees C is heated until it becomes water at 20 degrees C. Calculate the total energy needed. c of ice = 2100 J/kg degrees C; latent heat of fusion = 334000 J/kg; c of water = 4200 J/kg degrees C.", scheme: ["Warm ice: E = 0.3 * 2100 * 10 = 6300 J", "Melt ice: E = 0.3 * 334000 = 100200 J", "Warm water: E = 0.3 * 4200 * 20 = 25200 J", "Total = 6300 + 100200 + 25200", "= 131700 J", "(about 132 kJ)"], answer: "Warming ice: 0.3 × 2100 × 10 = 6300 J. Melting: 0.3 × 334 000 = 100 200 J. Warming water: 0.3 × 4200 × 20 = 25 200 J. Total = 131 700 J (about 132 kJ)." },
      { g: 9, marks: 6, q: "Explain fully, using the particle model, how heating a substance from a cold solid to a hot gas changes its temperature and internal energy at each stage.", scheme: ["Solid heating: kinetic energy and temperature rise", "Melting: potential energy rises as bonds break, temperature constant", "Liquid heating: kinetic energy and temperature rise", "Boiling: potential energy rises as particles fully separate, temperature constant", "Gas heating: kinetic energy and temperature rise", "Internal energy increases at every stage"], answer: "Heating the solid raises kinetic energy and temperature; at melting the energy raises potential energy as bonds break at constant temperature; heating the liquid again raises kinetic energy; at boiling the particles fully separate (potential energy rises) at constant temperature; heating the gas raises kinetic energy. Internal energy increases throughout." },
      { g: 9, marks: 6, q: "A 2 kg pan of water at 20 degrees C is heated by a 2000 W element. Calculate the time to reach 100 degrees C, then the extra time to boil away 0.5 kg of the water. c of water = 4200 J/kg degrees C; latent heat of vaporisation = 2260000 J/kg. Assume no losses.", scheme: ["Heat to 100: E = 2 * 4200 * 80 = 672000 J", "time = E / power = 672000 / 2000 = 336 s", "Boil 0.5 kg: E = 0.5 * 2260000 = 1130000 J", "time = 1130000 / 2000 = 565 s", "Total time = 336 + 565", "= 901 s (about 15 minutes)"], answer: "Heating: E = 2 × 4200 × 80 = 672 000 J, t = 672 000 ÷ 2000 = 336 s. Boiling: E = 0.5 × 2 260 000 = 1 130 000 J, t = 565 s. Total = 901 s (about 15 min)." },
      { g: 9, marks: 6, q: "(HT) Explain how doing work on a gas by compressing it quickly can raise its temperature, in terms of energy and particles.", scheme: ["Work is done on the gas by the force compressing it", "This transfers energy to the gas particles", "Increases the internal energy of the gas", "Particles gain kinetic energy and move faster", "Average kinetic energy rises so temperature rises", "Happens if too quick for heat to escape"], answer: "Compressing the gas does work on it, transferring energy to the particles and raising the internal energy. The particles gain kinetic energy and move faster, so the average kinetic energy and therefore the temperature rise, especially if the compression is too fast for heat to escape." },
      { g: 9, marks: 5, q: "In a specific heat capacity experiment a student finds c = 480 J/kg degrees C but the true value is 450 J/kg degrees C. Explain the likely cause and how to reduce the error, referring to energy transfer.", scheme: ["Thermal energy lost to the surroundings during heating", "So measured energy input exceeds energy used to heat the block", "E / (m * change in temp) is too large, raising c", "Insulate/lag the block and use a lid to reduce losses", "Ensure good thermal contact for the thermometer/heater"], answer: "Some supplied energy is lost to the surroundings, so the recorded energy is more than that actually used to heat the block, making c = E ÷ (mΔθ) too large. Insulating the block, adding a lid and ensuring good thermal contact would reduce the heat losses and bring the value closer to the true one." },
      { g: 9, marks: 6, q: "Two liquids of equal mass are heated by identical heaters for the same time. Liquid A rises by 40 degrees C and liquid B by 25 degrees C. Explain which has the higher specific heat capacity and calculate the ratio of their specific heat capacities.", scheme: ["Same E and m, so c is inversely proportional to change in temp", "Liquid B has the smaller temperature rise so higher c", "c_A / c_B = change in temp_B / change in temp_A = 25 / 40", "= 0.625", "So c_B is larger; c_A : c_B = 25 : 40 = 5 : 8"], answer: "With equal energy and mass, c is inversely proportional to Δθ, so liquid B (smaller rise) has the higher specific heat capacity. The ratio c_A : c_B = Δθ_B : Δθ_A = 25 : 40 = 5 : 8." },
      { g: 9, marks: 6, q: "Describe how to determine the density of an irregular object that floats, and explain how you would adapt the displacement method. Then calculate the density if it has a mass of 45 g and displaces 90 cm^3 when fully pushed under.", scheme: ["Measure mass on a balance", "Object floats, so push it fully under with a thin rod / use a sinker", "Measure the volume of water displaced", "density = mass / volume = 45 / 90", "= 0.5 g/cm^3", "Less than 1 g/cm^3, so it floats on water"], answer: "Measure the mass, then fully submerge the object using a thin rod or a sinker and record the water displaced as the volume. Density = 45 ÷ 90 = 0.5 g/cm³, which is less than water's 1 g/cm³, so it floats." },
      { g: 9, marks: 6, q: "Explain, using the particle model, why gas pressure increases with temperature at constant volume, and why it would double if the (kelvin) temperature doubled.", scheme: ["Particles have kinetic energy proportional to (kelvin) temperature", "Higher temperature means faster particles", "More frequent collisions with the walls", "Each collision exerts a greater force", "Pressure proportional to (kelvin) temperature at fixed volume", "Doubling kelvin temperature doubles average kinetic energy and so doubles pressure"], answer: "The particles' average kinetic energy is proportional to the kelvin temperature, so raising the temperature makes them move faster, colliding with the walls more often and harder. At fixed volume pressure is proportional to the kelvin temperature, so doubling the kelvin temperature doubles the pressure." },
      { g: 9, marks: 5, q: "A calorimetry experiment gives a specific latent heat of vaporisation of water of 2100000 J/kg, lower than the true 2260000 J/kg. Explain a likely reason and calculate the percentage error.", scheme: ["Some water may be lost as spray / energy loss means not all measured", "Or not all energy went to boiling, mass boiled overestimated", "percentage error = (2260000 - 2100000) / 2260000 * 100", "= 160000 / 2260000 * 100", "= 7.1% (about 7%)"], answer: "Extra water may be lost as spray or some energy escapes, so the mass boiled per joule seems larger, lowering L. Percentage error = (2 260 000 − 2 100 000) ÷ 2 260 000 × 100 = 7.1%." },
      { g: 9, marks: 6, q: "Compare the arrangement, spacing, motion and energy of particles in solids, liquids and gases, and link these to density and compressibility.", scheme: ["Solid: regular, touching, vibrating; high density, incompressible", "Liquid: irregular, touching, moving past each other; similar density, nearly incompressible", "Gas: far apart, random fast motion; low density, easily compressed", "Density falls as spacing increases", "Compressibility rises as spacing increases", "Particles gain energy/kinetic energy from solid to gas"], answer: "Solids have regular, touching, vibrating particles giving high density and no compressibility. Liquids have touching particles that move past each other, similar density and little compressibility. Gases have far-apart, fast, random particles giving low density and easy compression. As spacing increases, density falls and compressibility rises, and the particles have more energy." },
      { g: 9, marks: 6, q: "A 0.6 kg copper block is heated from 20 degrees C to 120 degrees C. It is then placed in 0.4 kg of water at 15 degrees C. c of copper = 385 J/kg degrees C; c of water = 4200 J/kg degrees C. Calculate the energy transferred to the water and its temperature rise, assuming all energy from the block goes to the water.", scheme: ["Energy from block: E = 0.6 * 385 * 100 = 23100 J", "This energy goes to the water", "change in temp of water = E / (m * c) = 23100 / (0.4 * 4200)", "= 23100 / 1680", "= 13.75 degrees C", "(about 13.8 degrees C rise)"], answer: "Block loses E = 0.6 × 385 × 100 = 23 100 J. Water rise Δθ = 23 100 ÷ (0.4 × 4200) = 23 100 ÷ 1680 = 13.75°C." },
      { g: 9, marks: 5, q: "Explain why the temperature of pure water stays at exactly 100 degrees C while it boils, even though energy is still being supplied.", scheme: ["Energy supplied is used to change state, not raise temperature", "It breaks the bonds between the liquid particles", "Increasing potential energy, not kinetic energy", "Temperature depends on average kinetic energy, which is unchanged", "So temperature stays constant until all the liquid has boiled"], answer: "While boiling, the supplied energy breaks the bonds between particles, increasing their potential energy rather than their kinetic energy. Since temperature depends on average kinetic energy, it stays at 100°C until all the water has turned to steam." },
      { g: 9, marks: 6, q: "An alloy is made by mixing 200 cm^3 of metal X (density 8 g/cm^3) with 300 cm^3 of metal Y (density 3 g/cm^3). Assuming volumes add, calculate the density of the alloy.", scheme: ["mass X = density * volume = 8 * 200 = 1600 g", "mass Y = 3 * 300 = 900 g", "total mass = 1600 + 900 = 2500 g", "total volume = 200 + 300 = 500 cm^3", "density = 2500 / 500", "= 5 g/cm^3"], answer: "Mass X = 8 × 200 = 1600 g; mass Y = 3 × 300 = 900 g; total mass = 2500 g; total volume = 500 cm³; density = 2500 ÷ 500 = 5 g/cm³." },
      { g: 9, marks: 6, q: "Explain fully how a heating curve can be used to identify a pure substance and to compare the specific heat capacities and latent heats of different substances.", scheme: ["Pure substance melts/boils at a sharp constant temperature (flat sections)", "Impure substances change state over a range", "Steeper slope means lower specific heat capacity (faster temperature rise)", "Longer flat section means larger latent heat for that mass", "Compare gradients for specific heat capacities", "Compare plateau lengths (energy or time) for latent heats"], answer: "A pure substance shows sharp, flat melting and boiling sections at fixed temperatures, whereas impure substances change over a range. A steeper slope indicates a lower specific heat capacity, and a longer flat section indicates a larger latent heat, so comparing gradients and plateau lengths lets you compare the substances' specific heat capacities and latent heats." },
      { g: 9, marks: 5, q: "(HT) A bicycle pump is blocked at the end and the plunger is pushed in quickly. Explain, in terms of work and internal energy, why the air inside gets hotter, and why pushing slowly has less effect.", scheme: ["Pushing does work on the gas / transfers energy to it", "Internal energy of the gas increases", "Particles gain kinetic energy so temperature rises", "Fast: little time for energy to escape as heat, so bigger rise", "Slow: energy has time to transfer to surroundings, smaller rise"], answer: "Pushing the plunger does work on the gas, transferring energy and raising its internal energy, so the particles gain kinetic energy and the temperature rises. Doing it quickly leaves little time for heat to escape, giving a large rise, while pushing slowly lets energy pass to the surroundings, so the temperature rises less." },
    ],
    "4. Atomic structure": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What is the charge on a proton?", scheme: ["Positive (+1)"], answer: "Positive (+1)." },
      { g: 4, marks: 1, q: "What is the charge on an electron?", scheme: ["Negative (-1)"], answer: "Negative (-1)." },
      { g: 4, marks: 1, q: "What is the charge on a neutron?", scheme: ["No charge / neutral (0)"], answer: "It has no charge; it is neutral." },
      { g: 4, marks: 1, q: "Which two particles are found in the nucleus of an atom?", scheme: ["Protons and neutrons"], answer: "Protons and neutrons." },
      { g: 4, marks: 1, q: "Where are electrons found in an atom?", scheme: ["In shells / orbiting the nucleus"], answer: "In shells orbiting the nucleus." },
      { g: 4, marks: 1, q: "What does the atomic number of an atom tell you?", scheme: ["The number of protons"], answer: "The number of protons in the atom." },
      { g: 4, marks: 1, q: "What is the approximate radius of an atom?", scheme: ["About 1x10^-10 m"], answer: "About 1x10^-10 m." },
      { g: 4, marks: 1, q: "Is the nucleus large or small compared with the whole atom?", scheme: ["Very small (compared with the atom)"], answer: "It is very small compared with the whole atom." },
      { g: 4, marks: 1, q: "What name is given to atoms of the same element with different numbers of neutrons?", scheme: ["Isotopes"], answer: "Isotopes." },
      { g: 4, marks: 1, q: "What is formed when an atom loses or gains electrons?", scheme: ["An ion"], answer: "An ion." },
      { g: 4, marks: 1, q: "Name the three types of nuclear radiation given off in radioactive decay (besides neutrons).", scheme: ["Alpha, beta and gamma"], answer: "Alpha, beta and gamma." },
      { g: 4, marks: 1, q: "What is the unit of activity of a radioactive source?", scheme: ["The becquerel (Bq)"], answer: "The becquerel (Bq)." },
      { g: 4, marks: 1, q: "What name is given to the time taken for half the radioactive nuclei in a sample to decay?", scheme: ["Half-life"], answer: "The half-life." },
      { g: 4, marks: 1, q: "Which type of radiation is the most penetrating: alpha, beta or gamma?", scheme: ["Gamma"], answer: "Gamma." },
      { g: 4, marks: 1, q: "Name the scientist who discovered the neutron.", scheme: ["James Chadwick"], answer: "James Chadwick." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 1, q: "State the relative mass of a proton.", scheme: ["1"], answer: "1 (relative mass)." },
      { g: 5, marks: 1, q: "State the relative mass of an electron.", scheme: ["Very small / about 1/1836 (negligible)"], answer: "Very small, about 1/1836 of a proton (almost negligible)." },
      { g: 5, marks: 2, q: "State what the mass number and atomic number of an atom tell you.", scheme: ["Mass number = total protons + neutrons", "Atomic number = number of protons"], answer: "The mass number is the total number of protons and neutrons; the atomic number is the number of protons." },
      { g: 5, marks: 2, q: "An atom has an atomic number of 6 and a mass number of 14. State the number of protons and neutrons.", scheme: ["6 protons", "14 - 6 = 8 neutrons"], answer: "It has 6 protons and 14 - 6 = 8 neutrons." },
      { g: 5, marks: 1, q: "Why does a neutral atom have no overall charge?", scheme: ["Equal numbers of protons and electrons"], answer: "It has equal numbers of protons and electrons, so the charges cancel." },
      { g: 5, marks: 2, q: "State what alpha radiation is made of and its charge.", scheme: ["Two protons and two neutrons (a helium nucleus)", "Charge +2"], answer: "An alpha particle is two protons and two neutrons (a helium nucleus) with a charge of +2." },
      { g: 5, marks: 2, q: "State what a beta particle is and its charge.", scheme: ["A high-speed electron (from the nucleus)", "Charge -1"], answer: "A beta particle is a high-speed electron emitted from the nucleus, with a charge of -1." },
      { g: 5, marks: 1, q: "What is gamma radiation?", scheme: ["Electromagnetic radiation / a high-energy EM wave (from the nucleus)"], answer: "It is a high-energy electromagnetic wave released from the nucleus." },
      { g: 5, marks: 2, q: "State which materials will stop alpha and beta radiation.", scheme: ["Alpha stopped by paper (or a few cm of air)", "Beta stopped by a few mm of aluminium"], answer: "Alpha is stopped by paper (or a few cm of air); beta is stopped by a few mm of aluminium." },
      { g: 5, marks: 1, q: "What is meant by count-rate from a radioactive source?", scheme: ["Number of decays detected per second (by a detector)"], answer: "The number of decays (counts) detected each second by a detector such as a Geiger-Muller tube." },
      { g: 5, marks: 2, q: "Describe the plum pudding model of the atom.", scheme: ["A ball of positive charge", "With electrons embedded/dotted in it"], answer: "The atom is a ball of positive charge with negative electrons embedded in it, like plums in a pudding." },
      { g: 5, marks: 1, q: "What is background radiation?", scheme: ["Radiation that is around us all the time (from natural and man-made sources)"], answer: "Radiation that is present around us all the time from natural and man-made sources." },
      { g: 5, marks: 1, q: "Give one source of background radiation.", scheme: ["Radon gas / rocks / cosmic rays / food / medical (any one)"], answer: "Radon gas from rocks (or cosmic rays, food, or medical sources)." },
      { g: 5, marks: 2, q: "Order alpha, beta and gamma from most to least ionising.", scheme: ["Most ionising: alpha", "Then beta, then gamma (least)"], answer: "Alpha is the most ionising, then beta, then gamma is the least ionising." },
      { g: 5, marks: 1, q: "What happens to an atom's mass number when it emits a beta particle?", scheme: ["Stays the same / unchanged"], answer: "It stays the same." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "A radioactive source has a half-life of 5 years. It starts with an activity of 80 Bq. What is the activity after 10 years?", scheme: ["10 years = 2 half-lives", "80 -> 40 -> 20 = 20 Bq"], answer: "10 years is 2 half-lives. The activity halves each time: 80 -> 40 -> 20, so it is 20 Bq." },
      { g: 6, marks: 3, q: "A sample has an activity of 240 Bq and a half-life of 3 hours. Calculate the activity after 9 hours. Show your working.", scheme: ["9 hours = 3 half-lives", "240 -> 120 -> 60 -> 30", "= 30 Bq"], answer: "9 hours is 3 half-lives. Halving each time: 240 -> 120 -> 60 -> 30, so the activity is 30 Bq." },
      { g: 6, marks: 2, q: "Explain why alpha radiation is the most ionising type of radiation.", scheme: ["It is large / has a large charge (+2)", "So it collides with and removes electrons from many atoms"], answer: "Alpha particles are large and have a charge of +2, so they collide strongly with atoms and knock off many electrons, making them highly ionising." },
      { g: 6, marks: 3, q: "Describe the results of Rutherford's alpha scattering experiment.", scheme: ["Most alpha particles passed straight through", "Some were deflected", "A few bounced straight back"], answer: "Most alpha particles passed straight through the gold foil, some were deflected, and a very few bounced almost straight back." },
      { g: 6, marks: 2, q: "Write the missing values in this alpha decay. A uranium-238 nucleus (atomic number 92) emits an alpha particle. State the mass number and atomic number of the new nucleus.", scheme: ["Mass number = 238 - 4 = 234", "Atomic number = 92 - 2 = 90"], answer: "The new nucleus has a mass number of 238 - 4 = 234 and an atomic number of 92 - 2 = 90." },
      { g: 6, marks: 2, q: "Explain the difference between irradiation and contamination.", scheme: ["Irradiation: object exposed to radiation (but source not on/in it)", "Contamination: radioactive material gets onto or into an object"], answer: "Irradiation is exposing an object to radiation from an outside source; contamination is when radioactive material gets onto or into the object itself." },
      { g: 6, marks: 2, q: "A count-rate falls from 400 counts/s to 100 counts/s in 8 minutes. How many half-lives is this, and what is the half-life?", scheme: ["400 -> 200 -> 100 = 2 half-lives", "8 / 2 = 4 minutes"], answer: "400 -> 200 -> 100 is 2 half-lives in 8 minutes, so the half-life is 8 / 2 = 4 minutes." },
      { g: 6, marks: 2, q: "Explain why gamma radiation has the longest range in air.", scheme: ["It is the least ionising", "So it loses energy slowly and travels far"], answer: "Gamma is the least ionising, so it loses its energy slowly and can travel a long way through air." },
      { g: 6, marks: 3, q: "Describe the atomic model Rutherford proposed after his experiment (the nuclear model).", scheme: ["Mass concentrated in a tiny central nucleus", "Nucleus is positively charged", "Electrons orbit the nucleus / most of the atom is empty space"], answer: "The mass and positive charge are concentrated in a tiny central nucleus, with electrons orbiting around it, and most of the atom is empty space." },
      { g: 6, marks: 2, q: "A radioactive isotope has a half-life of 6 days. What fraction of the original nuclei remain after 18 days?", scheme: ["18 / 6 = 3 half-lives", "1/2 -> 1/4 -> 1/8"], answer: "18 days is 3 half-lives, so the fraction remaining is 1/2 x 1/2 x 1/2 = 1/8." },
      { g: 6, marks: 2, q: "Explain why a beta particle has a charge of -1 even though it comes from the nucleus.", scheme: ["A neutron changes into a proton and an electron", "The electron (beta particle) is emitted"], answer: "In beta decay a neutron changes into a proton and an electron; the electron is emitted from the nucleus as the beta particle, so it has a charge of -1." },
      { g: 6, marks: 2, q: "Describe what happens in nuclear fission.", scheme: ["A large/unstable nucleus splits into two smaller nuclei", "Releasing energy and (2-3) neutrons"], answer: "A large, unstable nucleus splits into two smaller nuclei, releasing energy and two or three neutrons." },
      { g: 6, marks: 2, q: "Describe what happens in nuclear fusion.", scheme: ["Two light/small nuclei join together", "To form a heavier nucleus, releasing energy"], answer: "Two light nuclei join together to form a heavier nucleus, releasing energy." },
      { g: 6, marks: 2, q: "Give one use of gamma radiation in medicine and explain why gamma is suitable.", scheme: ["Use: medical tracer / treating cancer / sterilising equipment (any one)", "Gamma can pass out of the body / penetrate to reach the target"], answer: "It is used as a medical tracer because gamma radiation can pass out through the body to be detected outside." },
      { g: 6, marks: 3, q: "A sample of a radioactive isotope contains 800 undecayed nuclei. After 12 hours, 100 remain. Calculate the half-life.", scheme: ["800 -> 400 -> 200 -> 100 = 3 half-lives", "12 / 3 = 4", "Half-life = 4 hours"], answer: "800 -> 400 -> 200 -> 100 is 3 half-lives in 12 hours, so the half-life is 12 / 3 = 4 hours." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "A radioactive source has an activity of 6400 Bq and a half-life of 15 minutes. Calculate the activity after 1 hour. Show your working.", scheme: ["1 hour = 60 minutes = 4 half-lives", "6400 -> 3200 -> 1600 -> 800 -> 400", "= 400 Bq"], answer: "1 hour is 60 / 15 = 4 half-lives. Halving each time: 6400 -> 3200 -> 1600 -> 800 -> 400, so the activity is 400 Bq." },
      { g: 7, marks: 3, q: "Complete this alpha decay equation, giving the mass number and atomic number of the daughter nucleus X: radium-226 (atomic number 88) emits an alpha particle to become X. Show your working.", scheme: ["Alpha particle = mass 4, charge 2", "Mass number of X = 226 - 4 = 222", "Atomic number of X = 88 - 2 = 86"], answer: "An alpha particle has mass number 4 and atomic number 2. So X has mass number 226 - 4 = 222 and atomic number 88 - 2 = 86." },
      { g: 7, marks: 3, q: "Complete this beta decay: carbon-14 (atomic number 6) emits a beta particle to become nucleus Y. State the mass number and atomic number of Y and explain the change. Show your working.", scheme: ["Beta particle has mass number 0, charge -1", "Mass number of Y = 14 (unchanged)", "Atomic number of Y = 6 + 1 = 7"], answer: "A beta particle has mass number 0 and charge -1. The mass number of Y stays at 14, and the atomic number increases by 1 to 6 + 1 = 7, because a neutron changes into a proton." },
      { g: 7, marks: 4, q: "A radioactive isotope has a half-life of 2 days. A sample has an initial count-rate of 3200 counts/s. Calculate the count-rate after 10 days and state how many half-lives this is. Show your working.", scheme: ["10 / 2 = 5 half-lives", "3200 -> 1600 -> 800 -> 400 -> 200 -> 100", "= 100 counts/s"], answer: "10 days is 10 / 2 = 5 half-lives. Halving each time: 3200 -> 1600 -> 800 -> 400 -> 200 -> 100, so the count-rate is 100 counts/s." },
      { g: 7, marks: 3, q: "Explain how the results of the alpha scattering experiment led to the plum pudding model being rejected.", scheme: ["Plum pudding predicted alpha would pass straight through / small deflections only", "Some alpha bounced back / were deflected a lot", "Showed a small, dense, positive nucleus (not spread-out charge)"], answer: "The plum pudding model predicted the alpha particles would pass straight through with only small deflections. Because some were deflected a lot and a few bounced back, the charge and mass had to be concentrated in a small, dense, positive nucleus, so the model was rejected." },
      { g: 7, marks: 3, q: "A source has a half-life of 4 hours and an initial activity of 9600 Bq. Calculate the activity after 12 hours. Show your working.", scheme: ["12 / 4 = 3 half-lives", "9600 -> 4800 -> 2400 -> 1200", "= 1200 Bq"], answer: "12 hours is 12 / 4 = 3 half-lives. Halving each time: 9600 -> 4800 -> 2400 -> 1200, so the activity is 1200 Bq." },
      { g: 7, marks: 3, q: "Explain why alpha sources are dangerous if swallowed (contamination) but less dangerous outside the body.", scheme: ["Alpha is highly ionising", "Inside the body it damages nearby cells / cannot escape the body", "Outside the body it is stopped by skin / air / dead cells"], answer: "Alpha is highly ionising, so inside the body it does a lot of damage to nearby cells. Outside the body it is stopped by the air or dead skin cells, so it is much less dangerous." },
      { g: 7, marks: 4, q: "A radioactive isotope has a half-life of 25 years. A sample contains 6.4x10^6 undecayed nuclei. Calculate how many remain after 100 years. Show your working.", scheme: ["100 / 25 = 4 half-lives", "6.4x10^6 -> 3.2x10^6 -> 1.6x10^6 -> 0.8x10^6 -> 0.4x10^6", "= 4x10^5 nuclei"], answer: "100 years is 100 / 25 = 4 half-lives. Halving each time: 6.4x10^6 -> 3.2x10^6 -> 1.6x10^6 -> 0.8x10^6 -> 0.4x10^6, so 4x10^5 nuclei remain." },
      { g: 7, marks: 3, q: "Describe how the model of the atom developed from Dalton to Bohr. Include two key changes.", scheme: ["Dalton: tiny solid spheres / plum pudding: positive ball with electrons", "Rutherford: nuclear model with a tiny positive nucleus", "Bohr: electrons orbit in fixed shells/energy levels"], answer: "Dalton thought atoms were tiny solid spheres, then the plum pudding model had electrons in a ball of positive charge. Rutherford's nuclear model placed the positive charge in a tiny nucleus, and Bohr then showed the electrons orbit in fixed shells at set distances." },
      { g: 7, marks: 3, q: "A radioactive sample decays so that 7/8 of the original nuclei have decayed after 30 minutes. Calculate the half-life. Show your working.", scheme: ["7/8 decayed means 1/8 remains", "1/8 = 3 half-lives (1/2 -> 1/4 -> 1/8)", "30 / 3 = 10 minutes"], answer: "If 7/8 has decayed, 1/8 remains, which is 3 half-lives (1/2 -> 1/4 -> 1/8). So the half-life is 30 / 3 = 10 minutes." },
      { g: 7, marks: 3, q: "Explain why a radioactive tracer used inside the body should have a short half-life and emit gamma radiation.", scheme: ["Gamma can pass out of the body to be detected", "Short half-life so activity falls quickly / does not stay radioactive long", "Reduces damage to the patient's cells"], answer: "Gamma radiation can pass out of the body to be detected outside, and a short half-life means the source stops being radioactive quickly, reducing the radiation dose and damage to the patient." },
      { g: 7, marks: 3, q: "A count-rate is measured as 520 counts/s. The background count-rate is 20 counts/s. The corrected count-rate then halves every 2 hours. Calculate the corrected count-rate after 4 hours. Show your working.", scheme: ["Corrected start = 520 - 20 = 500 counts/s", "4 / 2 = 2 half-lives: 500 -> 250 -> 125", "= 125 counts/s"], answer: "Subtracting background: 520 - 20 = 500 counts/s. 4 hours is 2 half-lives: 500 -> 250 -> 125, so the corrected count-rate is 125 counts/s." },
      { g: 7, marks: 3, q: "Explain how a controlled chain reaction is maintained in a nuclear fission reactor.", scheme: ["Neutron is absorbed by a large nucleus, which splits and releases more neutrons", "These neutrons cause further fissions (chain reaction)", "Control rods absorb neutrons to keep the rate steady"], answer: "A neutron is absorbed by a large nucleus, which splits and releases more neutrons that cause further fissions, forming a chain reaction. Control rods absorb some neutrons so that on average one neutron from each fission causes the next, keeping the reaction controlled." },
      { g: 7, marks: 4, q: "A source has an initial activity of 1000 Bq. After 24 hours its activity is 125 Bq. Calculate the half-life. Show your working.", scheme: ["1000 -> 500 -> 250 -> 125 = 3 half-lives", "24 / 3 = 8", "Half-life = 8 hours"], answer: "1000 -> 500 -> 250 -> 125 is 3 half-lives in 24 hours, so the half-life is 24 / 3 = 8 hours." },
      { g: 7, marks: 3, q: "Explain why the nuclear model of the atom was later refined by Bohr and why his idea was accepted.", scheme: ["Rutherford's model did not explain electron arrangement", "Bohr proposed electrons in fixed shells/energy levels at set distances", "His calculations agreed with experimental observations"], answer: "Rutherford's model did not explain how electrons were arranged. Bohr proposed that electrons orbit in fixed shells at specific distances from the nucleus, and because his theoretical calculations agreed with experimental results, the idea was accepted." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "A radioactive isotope has a half-life of 30 minutes and an initial activity of 12800 Bq. Calculate the activity after 2.5 hours and state the fraction of the original activity remaining. Show your working.", scheme: ["2.5 hours = 150 minutes = 5 half-lives", "12800 -> 6400 -> 3200 -> 1600 -> 800 -> 400", "= 400 Bq", "Fraction = 1/32 (= (1/2)^5)"], answer: "2.5 hours is 150 / 30 = 5 half-lives. Halving each time: 12800 -> 6400 -> 3200 -> 1600 -> 800 -> 400, so the activity is 400 Bq, which is (1/2)^5 = 1/32 of the original." },
      { g: 8, marks: 4, q: "Explain fully how the properties of alpha, beta and gamma radiation relate to their penetrating power and ionising ability.", scheme: ["Alpha: large, +2 charge, very ionising, least penetrating (stopped by paper)", "Beta: small, -1 charge, moderately ionising and penetrating (stopped by aluminium)", "Gamma: EM wave, no charge, least ionising, most penetrating (stopped by thick lead)", "More ionising means less penetrating (loses energy faster)"], answer: "Alpha particles are large with a +2 charge, so they are very ionising but least penetrating and are stopped by paper. Beta particles are small electrons with a -1 charge, so they are moderately ionising and are stopped by a few mm of aluminium. Gamma is an uncharged EM wave, so it is the least ionising but most penetrating, needing thick lead. The more ionising a radiation is, the faster it loses energy, so the less it penetrates." },
      { g: 8, marks: 4, q: "Uranium-235 undergoes fission after absorbing a neutron. Explain how this can start a chain reaction and how it is controlled in a reactor. Show a balanced idea of neutron numbers.", scheme: ["Nucleus absorbs a neutron and splits into two smaller nuclei", "Releases 2 or 3 neutrons plus energy", "These neutrons are absorbed by more nuclei -> further fissions (chain reaction)", "Control rods absorb excess neutrons so one neutron per fission continues the reaction"], answer: "A uranium-235 nucleus absorbs a neutron, becomes unstable and splits into two smaller nuclei, releasing energy and two or three neutrons. These neutrons are absorbed by other uranium nuclei, causing more fissions in a chain reaction. Control rods absorb the excess neutrons so that on average only one neutron from each fission causes the next, keeping the reaction steady and controlled." },
      { g: 8, marks: 4, q: "A sample of a radioactive isotope has an initial count-rate of 6400 counts/s. The background count-rate is 40 counts/s. The half-life is 3 hours. Calculate the measured count-rate (including background) after 9 hours. Show your working.", scheme: ["Corrected start = 6400 - 40 = 6360... treat 6400 as corrected source", "9 / 3 = 3 half-lives: 6400 -> 3200 -> 1600 -> 800", "Add background: 800 + 40 = 840 counts/s"], answer: "Taking 6400 counts/s as the source count-rate, 9 hours is 3 half-lives: 6400 -> 3200 -> 1600 -> 800. Adding the 40 counts/s background gives a measured count-rate of 800 + 40 = 840 counts/s." },
      { g: 8, marks: 4, q: "Explain why contamination can be more dangerous than a single irradiation, and how each hazard can be reduced.", scheme: ["Contamination: radioactive atoms stay on/in the body, giving continuous exposure", "Irradiation stops when the source is removed / shielded", "Reduce contamination: gloves, protective clothing, avoid ingestion", "Reduce irradiation: shielding, distance, short exposure time"], answer: "Contamination means radioactive atoms are on or inside the body, so they keep emitting radiation and give continuous exposure, whereas irradiation stops once the source is removed. Contamination is reduced by wearing gloves and protective clothing and avoiding swallowing the material, while irradiation is reduced by using shielding, keeping your distance and limiting exposure time." },
      { g: 8, marks: 4, q: "Polonium-218 (atomic number 84) decays by alpha emission, and the product then decays by beta emission. Work out the mass number and atomic number of the final nucleus. Show your working.", scheme: ["Alpha: mass 218 - 4 = 214, atomic number 84 - 2 = 82", "Beta: mass number unchanged = 214, atomic number 82 + 1 = 83", "Final nucleus: mass number 214, atomic number 83"], answer: "After alpha decay: mass number 218 - 4 = 214 and atomic number 84 - 2 = 82. After beta decay: the mass number stays 214 and the atomic number becomes 82 + 1 = 83. So the final nucleus has mass number 214 and atomic number 83." },
      { g: 8, marks: 4, q: "Explain why the count-rate measured from a source must be corrected for background radiation, and describe how to measure the background count-rate.", scheme: ["Detectors also pick up background radiation", "This makes the measured count-rate higher than the source alone", "Measure background with no source present (over a set time)", "Subtract the background count-rate from each reading"], answer: "A detector picks up background radiation as well as radiation from the source, making the measured count-rate too high. You first measure the background count-rate with no source present over a set time, then subtract this from each reading so only the source's count-rate remains." },
      { g: 8, marks: 4, q: "A radioactive isotope has a half-life of 5 days. A sample has 4.8x10^7 undecayed nuclei. Calculate the number of nuclei that have decayed after 20 days. Show your working.", scheme: ["20 / 5 = 4 half-lives", "4.8x10^7 -> 2.4x10^7 -> 1.2x10^7 -> 0.6x10^7 -> 0.3x10^7 remain", "Decayed = 4.8x10^7 - 0.3x10^7 = 4.5x10^7"], answer: "20 days is 4 half-lives. Remaining nuclei: 4.8x10^7 -> 2.4x10^7 -> 1.2x10^7 -> 0.6x10^7 -> 0.3x10^7. So the number decayed is 4.8x10^7 - 0.3x10^7 = 4.5x10^7 nuclei." },
      { g: 8, marks: 4, q: "Explain how each stage in the development of the atomic model changed what scientists believed about charge and mass in the atom.", scheme: ["Plum pudding: positive charge spread out, electrons embedded, mass spread", "Alpha scattering: charge and mass concentrated in a tiny nucleus", "Bohr: electrons in fixed shells at set energy levels", "Chadwick: neutrons in the nucleus explain the extra mass"], answer: "In the plum pudding model the positive charge and mass were spread throughout the atom. Alpha scattering showed the charge and most of the mass are concentrated in a tiny central nucleus. Bohr then placed the electrons in fixed shells at set distances, and Chadwick's discovery of the neutron explained the extra mass in the nucleus." },
      { g: 8, marks: 4, q: "Compare nuclear fission and nuclear fusion in terms of the nuclei involved, what happens, and where each occurs.", scheme: ["Fission: a large nucleus splits into two smaller nuclei", "Fusion: two small/light nuclei join to make a larger one", "Both release energy", "Fission used in reactors; fusion occurs in stars / needs very high temperatures"], answer: "In fission a large, unstable nucleus splits into two smaller nuclei, releasing energy and neutrons, and is used in nuclear reactors. In fusion two light nuclei join to form a heavier nucleus, also releasing energy, and this occurs in stars because it needs extremely high temperatures and pressures." },
      { g: 8, marks: 4, q: "A radioactive source has an activity of 800 Bq and a half-life of 2 hours. Draw the reasoning to find how long it takes for the activity to fall to 50 Bq. Show your working.", scheme: ["800 -> 400 -> 200 -> 100 -> 50 = 4 half-lives", "Each half-life = 2 hours", "Time = 4 x 2 = 8 hours"], answer: "800 -> 400 -> 200 -> 100 -> 50 is 4 half-lives. Each half-life is 2 hours, so the time taken is 4 x 2 = 8 hours." },
      { g: 8, marks: 4, q: "Explain why fusion does not readily happen on Earth even though it releases large amounts of energy.", scheme: ["Nuclei are positively charged and repel each other", "Very high temperature and pressure needed to overcome repulsion", "These extreme conditions are hard to create and contain on Earth", "So sustained fusion is very difficult to achieve"], answer: "Nuclei are positively charged and repel each other, so extremely high temperatures and pressures are needed to force them close enough to fuse. These conditions are very hard to create and contain on Earth, which is why sustained fusion is so difficult to achieve here." },
      { g: 8, marks: 4, q: "Nitrogen-13 (atomic number 7) decays to carbon-13 (atomic number 6). Determine the type of decay and explain your reasoning. Show your working.", scheme: ["Mass number unchanged (13 -> 13)", "Atomic number decreases by 1 (7 -> 6)", "This is positron emission / beta-plus (a proton changes to a neutron)"], answer: "The mass number stays at 13 but the atomic number falls by one from 7 to 6. Since a proton has turned into a neutron and a positive particle is emitted, this is positron (beta-plus) emission." },
      { g: 8, marks: 4, q: "Explain how a Geiger-Muller tube and counter can be used to determine the half-life of a source, including how to make the results reliable.", scheme: ["Measure and subtract background count-rate", "Record corrected count-rate at regular time intervals", "Plot count-rate against time and read the time for it to halve", "Repeat / take several halving times and average to improve reliability"], answer: "First measure the background count-rate and subtract it from every reading. Record the corrected count-rate at regular time intervals, then plot count-rate against time. The half-life is the time taken for the count-rate to halve; reading several successive halving times from the graph and averaging them makes the result more reliable." },
      { g: 8, marks: 4, q: "A sample starts with an activity of 25600 Bq and a half-life of 45 minutes. Calculate its activity after 3 hours and 45 minutes. Show your working.", scheme: ["3 h 45 min = 225 minutes", "225 / 45 = 5 half-lives", "25600 -> 12800 -> 6400 -> 3200 -> 1600 -> 800", "= 800 Bq"], answer: "3 hours 45 minutes is 225 minutes, which is 225 / 45 = 5 half-lives. Halving each time: 25600 -> 12800 -> 6400 -> 3200 -> 1600 -> 800, so the activity is 800 Bq." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Describe fully how the model of the atom developed from the plum pudding model to Bohr's model, explaining the evidence at each stage.", scheme: ["Plum pudding: ball of positive charge with electrons embedded", "Rutherford's alpha scattering: most passed through, some deflected, a few bounced back", "Conclusion: tiny, dense, positive nucleus; most of atom empty space", "Bohr: electrons in fixed shells/energy levels at set distances", "Bohr's calculations matched observations", "Chadwick later discovered the neutron in the nucleus"], answer: "The plum pudding model described the atom as a ball of positive charge with electrons embedded in it. Rutherford's alpha scattering experiment showed most particles passed straight through, some were deflected and a few bounced back, meaning the mass and positive charge are concentrated in a tiny, dense nucleus with most of the atom being empty space. Bohr refined this by proposing electrons orbit in fixed shells at set distances, which his calculations supported, and Chadwick later discovered the neutron, explaining the extra mass in the nucleus." },
      { g: 9, marks: 6, q: "A radioactive isotope has a half-life of 8 hours. A sample has an initial activity of 4.8x10^5 Bq. Calculate the activity after 32 hours, the fraction of nuclei remaining, and the percentage that has decayed. Show full working.", scheme: ["32 / 8 = 4 half-lives", "4.8x10^5 -> 2.4x10^5 -> 1.2x10^5 -> 0.6x10^5 -> 0.3x10^5 = 3x10^4 Bq", "Fraction remaining = (1/2)^4 = 1/16", "Percentage decayed = (1 - 1/16) x 100 = 93.75%"], answer: "32 hours is 4 half-lives. Halving the activity: 4.8x10^5 -> 2.4x10^5 -> 1.2x10^5 -> 0.6x10^5 -> 0.3x10^5, so the activity is 3x10^4 Bq. The fraction remaining is (1/2)^4 = 1/16, so the percentage decayed is (1 - 1/16) x 100 = 93.75%." },
      { g: 9, marks: 6, q: "Explain fully, using ideas of ionising power and penetration, how a suitable radioactive isotope is chosen for (a) a smoke detector and (b) a medical tracer inside the body.", scheme: ["Smoke detector: alpha source used", "Alpha is highly ionising (ionises air so a current flows) but low penetration (safe, stays in device)", "Long half-life so it lasts a long time", "Tracer: gamma (or beta) source", "Gamma penetrates out of the body to be detected", "Short half-life so activity falls quickly and dose to patient is low"], answer: "A smoke detector uses an alpha source because alpha is highly ionising, ionising the air so a current flows, but has low penetration so it stays safely inside the device; a long half-life keeps it working for years. A medical tracer uses a gamma emitter because gamma can penetrate out of the body to be detected outside, and it needs a short half-life so its activity falls quickly and the radiation dose to the patient stays low." },
      { g: 9, marks: 6, q: "Thorium-232 (atomic number 90) decays through a series: alpha, then beta, then beta. Work out the mass number and atomic number of the nucleus after all three decays, showing each step. Explain how mass and charge are conserved.", scheme: ["After alpha: mass 232 - 4 = 228, atomic number 90 - 2 = 88", "After first beta: mass 228, atomic number 88 + 1 = 89", "After second beta: mass 228, atomic number 89 + 1 = 90", "Final: mass number 228, atomic number 90", "Conservation: total mass number and total charge are the same before and after"], answer: "After the alpha decay: mass number 232 - 4 = 228, atomic number 90 - 2 = 88. After the first beta decay: mass number stays 228, atomic number 88 + 1 = 89. After the second beta decay: mass number stays 228, atomic number 89 + 1 = 90. The final nucleus has mass number 228 and atomic number 90. Mass and charge are conserved because the total mass number and total charge (atomic number plus emitted particles) are the same before and after each decay." },
      { g: 9, marks: 6, q: "Explain fully why alpha, beta and gamma radiation have different ranges and penetrating powers, linking this to their nature, charge and ionising ability.", scheme: ["Alpha: large, +2 charge, so ionises strongly and loses energy quickly", "So alpha has short range (few cm air) and is stopped by paper", "Beta: light electron, -1 charge, ionises less than alpha", "So beta travels further and is stopped by a few mm aluminium", "Gamma: uncharged EM wave, ionises weakly, loses energy slowly", "So gamma is very penetrating (needs thick lead/concrete) with the longest range"], answer: "Alpha particles are large with a +2 charge, so they interact strongly with atoms, ionise heavily and lose their energy quickly, giving a short range of a few cm in air and being stopped by paper. Beta particles are light electrons with a -1 charge that ionise less, so they travel further and are stopped by a few mm of aluminium. Gamma is an uncharged electromagnetic wave that ionises weakly and loses energy slowly, so it is very penetrating with the longest range and needs thick lead or concrete to stop it." },
      { g: 9, marks: 6, q: "A source has a measured count-rate of 2060 counts/s and the background count-rate is 60 counts/s. The half-life of the source is 20 minutes. Calculate the measured count-rate after 1 hour, and explain why the count-rate never falls to zero. Show full working.", scheme: ["Corrected source count-rate = 2060 - 60 = 2000 counts/s", "1 hour = 60 minutes = 3 half-lives", "2000 -> 1000 -> 500 -> 250 counts/s", "Add background: 250 + 60 = 310 counts/s", "Never zero because background radiation is always present", "Also decay is random / halving never reaches exactly zero"], answer: "Correcting for background: 2060 - 60 = 2000 counts/s from the source. 1 hour is 3 half-lives: 2000 -> 1000 -> 500 -> 250 counts/s. Adding the 60 counts/s background gives a measured count-rate of 250 + 60 = 310 counts/s. The count-rate never falls to zero because background radiation is always present, and the source's count-rate only ever halves so it approaches but never quite reaches zero." },
      { g: 9, marks: 6, q: "Evaluate the use of nuclear fission in power stations compared with the potential use of nuclear fusion.", scheme: ["Fission: reliable, releases large energy, no CO2 in generation", "Fission drawbacks: radioactive waste, risk of accidents, non-renewable fuel", "Fusion: fuel (hydrogen isotopes) abundant, little long-lived waste, huge energy", "Fusion problems: needs extreme temperature/pressure, hard to contain, not yet viable", "Comparison / weighing of advantages and disadvantages", "Justified conclusion"], answer: "Nuclear fission reliably releases large amounts of energy without producing carbon dioxide, but it creates dangerous radioactive waste, carries a risk of accidents and uses non-renewable fuel. Fusion would use abundant hydrogen isotopes, release even more energy and leave little long-lived waste, but it requires extreme temperatures and pressures that are very hard to create and contain, so it is not yet a practical power source. On balance fission is currently the only usable option, while fusion offers a cleaner long-term goal if the technical problems can be solved." },
      { g: 9, marks: 6, q: "A radioactive isotope has a half-life of 12 years. A rock sample is found to contain 1 undecayed nucleus of this isotope for every 15 nuclei of its stable decay product. Estimate the age of the rock, assuming all the product came from this isotope. Show full working.", scheme: ["Ratio 1 : 15 means 1 part remains out of 16 total original", "Fraction remaining = 1/16 = (1/2)^4", "So 4 half-lives have passed", "Age = 4 x 12 = 48 years"], answer: "For every 1 undecayed nucleus there are 15 product nuclei, so 1 out of every 16 original nuclei remains. The fraction remaining is 1/16 = (1/2)^4, which is 4 half-lives. So the rock is about 4 x 12 = 48 years old." },
      { g: 9, marks: 6, q: "Explain how the discovery of the nucleus and later the neutron changed scientists' understanding, and describe how protons, neutrons and electrons account for atomic number, mass number and isotopes.", scheme: ["Alpha scattering showed a tiny dense positive nucleus", "Chadwick discovered the neutron, explaining the extra mass", "Atomic number = number of protons (defines the element)", "Mass number = protons + neutrons", "Isotopes: same protons, different numbers of neutrons", "So isotopes have the same atomic number but different mass numbers"], answer: "Alpha scattering showed the atom has a tiny, dense, positive nucleus rather than spread-out charge, and Chadwick's later discovery of the neutron explained the extra mass in the nucleus that protons alone could not. The atomic number is the number of protons, which defines the element; the mass number is the total of protons and neutrons. Isotopes are atoms of the same element with the same number of protons but different numbers of neutrons, so they share an atomic number but have different mass numbers." },
      { g: 9, marks: 5, q: "A sample of a radioactive isotope has an initial count-rate of 12800 counts/s. Its count-rate falls to 400 counts/s after 2.5 hours. Calculate the half-life and predict the count-rate after a further 30 minutes. Show full working.", scheme: ["12800 -> 6400 -> 3200 -> 1600 -> 800 -> 400 = 5 half-lives", "2.5 hours = 150 minutes; half-life = 150 / 5 = 30 minutes", "A further 30 minutes = 1 more half-life", "400 -> 200 counts/s"], answer: "12800 -> 6400 -> 3200 -> 1600 -> 800 -> 400 is 5 half-lives in 2.5 hours (150 minutes), so the half-life is 150 / 5 = 30 minutes. A further 30 minutes is one more half-life, so the count-rate falls to 400 -> 200 counts/s." },
      { g: 9, marks: 6, q: "Explain why radioactive decay is described as a random process, and how, despite this, half-life is a useful and reliable measure.", scheme: ["Cannot predict which nucleus will decay or when", "Each nucleus has the same chance of decaying in a given time", "With very many nuclei the overall behaviour is predictable", "Half-life = time for half the nuclei (or count-rate) to decay", "It is constant for a given isotope", "So it reliably describes the average decay rate of the sample"], answer: "Radioactive decay is random because you cannot predict which nucleus will decay or exactly when; every nucleus simply has the same chance of decaying in a given time. However, because a sample contains a huge number of nuclei, their combined behaviour is very predictable. The half-life, the time for half the nuclei or the count-rate to fall by half, is constant for a given isotope, so it reliably describes the average rate of decay even though individual decays are random." },
      { g: 9, marks: 6, q: "Radium-226 (atomic number 88) decays by alpha emission to radon (Rn). Write the balanced nuclear equation and explain how it shows conservation of mass number and charge. Show full working.", scheme: ["Alpha particle written as helium-4, atomic number 2", "Rn nucleus: mass 226 - 4 = 222, atomic number 88 - 2 = 86", "Equation: Ra-226 (88) -> Rn-222 (86) + He-4 (2)", "Mass numbers: 226 = 222 + 4", "Atomic numbers/charge: 88 = 86 + 2"], answer: "The alpha particle is a helium-4 nucleus with atomic number 2. The radon nucleus has mass number 226 - 4 = 222 and atomic number 88 - 2 = 86. The equation is Ra-226 (Z=88) -> Rn-222 (Z=86) + He-4 (Z=2). Mass number is conserved because 226 = 222 + 4, and charge is conserved because the atomic numbers balance: 88 = 86 + 2." },
      { g: 9, marks: 5, q: "Explain the difference between irradiation and contamination, and evaluate which poses the greater long-term risk to a worker handling an alpha source.", scheme: ["Irradiation: exposed to radiation from an external source, stops when removed", "Contamination: radioactive atoms get onto/into the body, continuous exposure", "Alpha outside body is stopped by skin (low external hazard)", "But alpha inside the body (contamination) is very ionising and damaging", "Conclusion: contamination poses the greater long-term risk for an alpha source"], answer: "Irradiation is being exposed to radiation from an outside source, and it stops as soon as the source is removed. Contamination is when radioactive atoms get onto or into the body, giving continuous exposure. For an alpha source, the external hazard is low because alpha is stopped by the skin, but if the atoms get inside the body they ionise heavily and cause serious cell damage. Therefore contamination poses the greater long-term risk when handling an alpha source." },
      { g: 9, marks: 6, q: "A radioactive isotope X has a half-life of 6 hours. A sealed sample initially contains 8x10^8 nuclei of X. Calculate how many nuclei of X remain after 1 day, how many have decayed, and the activity ratio compared with the start. Show full working.", scheme: ["1 day = 24 hours = 4 half-lives", "8x10^8 -> 4x10^8 -> 2x10^8 -> 1x10^8 -> 0.5x10^8 remain = 5x10^7", "Decayed = 8x10^8 - 5x10^7 = 7.5x10^8", "Activity ratio = (1/2)^4 = 1/16"], answer: "1 day is 24 hours, which is 4 half-lives. Remaining nuclei: 8x10^8 -> 4x10^8 -> 2x10^8 -> 1x10^8 -> 0.5x10^8, so 5x10^7 nuclei remain. The number decayed is 8x10^8 - 5x10^7 = 7.5x10^8. Since activity is proportional to the number of nuclei, the activity is now (1/2)^4 = 1/16 of the starting activity." },
      { g: 9, marks: 6, q: "Explain fully how a nuclear fission chain reaction works and how a reactor is kept safe and controlled, referring to the roles of neutrons, control rods and the moderator.", scheme: ["A slow neutron is absorbed by a large nucleus (e.g. U-235), which splits", "Fission releases energy and 2-3 fast neutrons", "Moderator slows the neutrons so they can be absorbed to cause further fission", "Neutrons cause more fissions -> chain reaction", "Control rods absorb neutrons to control the rate (one neutron per fission continues)", "Lowering rods slows/stops the reaction; this prevents it running out of control"], answer: "A slow-moving neutron is absorbed by a large nucleus such as uranium-235, which becomes unstable and splits, releasing energy and two or three fast neutrons. A moderator slows these neutrons down so they can be absorbed by more nuclei and cause further fissions, building a chain reaction. Control rods absorb some of the neutrons so that on average only one neutron from each fission goes on to cause the next, keeping the reaction steady. Lowering the control rods absorbs more neutrons and slows or stops the reaction, which keeps the reactor safe and prevents it running out of control." },
    ],
    "5. Forces": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What is the unit of force?", scheme: ["Newton (N)"], answer: "The newton (N)." },
      { g: 4, marks: 1, q: "Is force a scalar or a vector quantity?", scheme: ["Vector"], answer: "A vector." },
      { g: 4, marks: 1, q: "Give one example of a scalar quantity.", scheme: ["Mass / speed / distance / energy / temperature (any one)"], answer: "Mass (or speed, distance, energy, temperature)." },
      { g: 4, marks: 1, q: "Give one example of a contact force.", scheme: ["Friction / air resistance / tension / normal contact force (any one)"], answer: "Friction (or air resistance, tension, normal contact force)." },
      { g: 4, marks: 1, q: "Give one example of a non-contact force.", scheme: ["Gravity / magnetic / electrostatic (any one)"], answer: "Gravitational force (or magnetic, or electrostatic force)." },
      { g: 4, marks: 1, q: "What is the name of the force that pulls objects towards the Earth?", scheme: ["Gravity / weight"], answer: "Gravity (weight)." },
      { g: 4, marks: 1, q: "What piece of equipment is used to measure force?", scheme: ["(Newton) meter / force meter / spring balance"], answer: "A newton meter (force meter)." },
      { g: 4, marks: 1, q: "What is the unit of mass?", scheme: ["Kilogram (kg)"], answer: "The kilogram (kg)." },
      { g: 4, marks: 1, q: "What name is given to a single force that has the same effect as all the forces acting on an object?", scheme: ["Resultant force"], answer: "The resultant force." },
      { g: 4, marks: 1, q: "What is the turning effect of a force called?", scheme: ["Moment"], answer: "A moment." },
      { g: 4, marks: 1, q: "What quantity is calculated using force multiplied by distance moved in the direction of the force?", scheme: ["Work done"], answer: "Work done." },
      { g: 4, marks: 1, q: "What is the unit of work done?", scheme: ["Joule (J)"], answer: "The joule (J)." },
      { g: 4, marks: 1, q: "State the term for the distance travelled in a stated direction.", scheme: ["Displacement"], answer: "Displacement." },
      { g: 4, marks: 1, q: "What quantity is speed in a given direction?", scheme: ["Velocity"], answer: "Velocity." },
      { g: 4, marks: 1, q: "What name is given to the tendency of an object to stay at rest or keep moving at the same velocity?", scheme: ["Inertia"], answer: "Inertia." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 1, q: "State the difference between a scalar and a vector quantity.", scheme: ["Scalar has magnitude only; vector has magnitude and direction"], answer: "A scalar has magnitude only, while a vector has both magnitude and direction." },
      { g: 5, marks: 2, q: "State the difference between mass and weight.", scheme: ["Mass is the amount of matter (kg); it stays the same", "Weight is the force of gravity on the mass (N); it depends on the gravitational field strength"], answer: "Mass is the amount of matter in an object (in kg) and stays the same, while weight is the force of gravity acting on that mass (in N) and depends on the gravitational field strength." },
      { g: 5, marks: 1, q: "State the equation linking weight, mass and gravitational field strength.", scheme: ["Weight = mass x gravitational field strength (W = mg)"], answer: "Weight = mass x gravitational field strength (W = mg)." },
      { g: 5, marks: 1, q: "State the equation for work done.", scheme: ["Work done = force x distance (W = Fs)"], answer: "Work done = force x distance moved along the line of action (W = Fs)." },
      { g: 5, marks: 1, q: "State the equation for the moment of a force.", scheme: ["Moment = force x perpendicular distance (M = Fd)"], answer: "Moment = force x perpendicular distance from the pivot (M = Fd)." },
      { g: 5, marks: 2, q: "Two forces of 6 N and 4 N act on an object in opposite directions along the same line. State the size and direction of the resultant force.", scheme: ["6 - 4 = 2 N", "In the direction of the 6 N force"], answer: "The resultant force is 6 - 4 = 2 N, acting in the direction of the 6 N force." },
      { g: 5, marks: 1, q: "What is meant by the weight of an object acting at a single point?", scheme: ["Centre of mass"], answer: "The weight is considered to act at a single point called the centre of mass." },
      { g: 5, marks: 2, q: "State Newton's first law for an object at rest.", scheme: ["If the resultant force is zero", "A stationary object stays at rest"], answer: "If the resultant force on an object is zero, a stationary object remains at rest." },
      { g: 5, marks: 1, q: "What is the difference between distance and displacement?", scheme: ["Distance is scalar (no direction); displacement is vector (has direction)"], answer: "Distance is a scalar with no direction, while displacement is a vector that includes direction." },
      { g: 5, marks: 1, q: "State the unit of gravitational field strength.", scheme: ["N/kg (newtons per kilogram)"], answer: "Newtons per kilogram (N/kg)." },
      { g: 5, marks: 2, q: "State what is meant by the limit of proportionality for a spring.", scheme: ["The point beyond which extension is no longer proportional to force", "Force and extension are proportional up to this point"], answer: "It is the point beyond which the extension of the spring is no longer directly proportional to the force applied." },
      { g: 5, marks: 1, q: "State the equation linking force, spring constant and extension.", scheme: ["Force = spring constant x extension (F = ke)"], answer: "Force = spring constant x extension (F = ke)." },
      { g: 5, marks: 2, q: "State the difference between elastic and inelastic deformation.", scheme: ["Elastic: object returns to original shape when force removed", "Inelastic: object does not return to original shape"], answer: "In elastic deformation the object returns to its original shape when the force is removed; in inelastic deformation it does not." },
      { g: 5, marks: 1, q: "State the equation linking speed, distance and time.", scheme: ["Speed = distance / time"], answer: "Speed = distance travelled / time taken." },
      { g: 5, marks: 2, q: "State what the gradient and the area under a distance-time graph represent.", scheme: ["Gradient = speed", "Area under a distance-time graph has no useful meaning (accept: gradient gives speed only)"], answer: "The gradient of a distance-time graph gives the speed; the steeper the line, the faster the object." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Calculate the weight of a 12 kg mass. (g = 9.8 N/kg)", scheme: ["W = m x g = 12 x 9.8", "= 117.6 N"], answer: "W = mg = 12 x 9.8 = 117.6 N." },
      { g: 6, marks: 3, q: "A force of 20 N moves a box 5 m in the direction of the force. Calculate the work done.", scheme: ["W = F x s", "= 20 x 5", "= 100 J"], answer: "W = Fs = 20 x 5 = 100 J." },
      { g: 6, marks: 3, q: "A spring has a spring constant of 25 N/m and is extended by 0.4 m. Calculate the force applied. (within the limit of proportionality)", scheme: ["F = k x e", "= 25 x 0.4", "= 10 N"], answer: "F = ke = 25 x 0.4 = 10 N." },
      { g: 6, marks: 3, q: "A force of 15 N acts at a perpendicular distance of 0.3 m from a pivot. Calculate the moment.", scheme: ["M = F x d", "= 15 x 0.3", "= 4.5 Nm"], answer: "M = Fd = 15 x 0.3 = 4.5 Nm." },
      { g: 6, marks: 2, q: "A car travels 150 m in 10 s. Calculate its speed.", scheme: ["speed = distance / time = 150 / 10", "= 15 m/s"], answer: "Speed = distance / time = 150 / 10 = 15 m/s." },
      { g: 6, marks: 2, q: "State the equation linking pressure, force and area, and give the unit of pressure.", scheme: ["Pressure = force / area (p = F/A)", "Unit: pascal (Pa) or N/m^2"], answer: "Pressure = force normal to a surface / area (p = F/A); the unit is the pascal (Pa), or N/m^2." },
      { g: 6, marks: 3, q: "A force of 200 N acts on an area of 0.5 m^2. Calculate the pressure.", scheme: ["p = F / A", "= 200 / 0.5", "= 400 Pa"], answer: "p = F/A = 200 / 0.5 = 400 Pa." },
      { g: 6, marks: 2, q: "Explain why a moving object slows down when the driving force is removed.", scheme: ["Resistive forces (friction/air resistance) still act", "Resultant force acts opposite to motion, so it decelerates"], answer: "Friction and air resistance still act on it, so there is a resultant force opposing its motion and it decelerates." },
      { g: 6, marks: 2, q: "State the two things that add together to give the total stopping distance of a vehicle.", scheme: ["Thinking distance", "Braking distance"], answer: "Thinking distance plus braking distance." },
      { g: 6, marks: 3, q: "A velocity-time graph shows a horizontal line. Describe the motion and explain how you find the distance travelled.", scheme: ["Constant velocity (not accelerating)", "Distance = area under the graph", "Area = velocity x time (rectangle)"], answer: "The object moves at constant velocity. The distance travelled is the area under the line, found as velocity x time." },
      { g: 6, marks: 2, q: "State the equation linking momentum, mass and velocity, and give the unit of momentum.", scheme: ["Momentum = mass x velocity (p = mv)", "Unit: kg m/s"], answer: "Momentum = mass x velocity (p = mv); the unit is kg m/s." },
      { g: 6, marks: 2, q: "Calculate the momentum of a 1200 kg car moving at 15 m/s.", scheme: ["p = m x v = 1200 x 15", "= 18 000 kg m/s"], answer: "p = mv = 1200 x 15 = 18 000 kg m/s." },
      { g: 6, marks: 2, q: "Explain what is meant by terminal velocity.", scheme: ["The maximum (constant) velocity of a falling object", "Reached when weight equals resistive forces so resultant force is zero"], answer: "It is the maximum, steady velocity of a falling object, reached when its weight is balanced by the resistive forces so the resultant force is zero." },
      { g: 6, marks: 2, q: "Explain how a lever makes it easier to lift a heavy load.", scheme: ["Lever acts as a force multiplier", "A small force at a large distance gives a large moment / turning effect"], answer: "A lever acts as a force multiplier: a small effort applied at a large distance from the pivot produces a large enough moment to lift the load." },
      { g: 6, marks: 3, q: "A student stretches a spring in the required practical. Describe how they should measure the extension for each force.", scheme: ["Measure the natural (unstretched) length first", "Add known weights and measure the new length", "Extension = stretched length - natural length"], answer: "First measure the spring's natural length, then add known weights and measure the new length; the extension is the stretched length minus the natural length." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "Calculate the weight of a 65 kg astronaut on the Moon, where g = 1.6 N/kg.", scheme: ["W = m x g", "= 65 x 1.6", "= 104 N"], answer: "W = mg = 65 x 1.6 = 104 N." },
      { g: 7, marks: 4, q: "A resultant force of 12 N acts on a 3 kg trolley. Calculate its acceleration and state the law used.", scheme: ["F = m x a, so a = F / m", "= 12 / 3", "= 4 m/s^2", "Newton's second law"], answer: "Using Newton's second law, F = ma, so a = F/m = 12 / 3 = 4 m/s^2." },
      { g: 7, marks: 3, q: "A 0.5 kg ball is dropped and reaches 6 m/s. Calculate its momentum.", scheme: ["p = m x v", "= 0.5 x 6", "= 3 kg m/s"], answer: "p = mv = 0.5 x 6 = 3 kg m/s." },
      { g: 7, marks: 4, q: "A spring extends by 0.08 m when a force of 4 N is applied. Calculate the spring constant, then find the extension for a 10 N force. (within the limit of proportionality)", scheme: ["k = F / e = 4 / 0.08 = 50 N/m", "e = F / k = 10 / 50", "= 0.2 m"], answer: "k = F/e = 4 / 0.08 = 50 N/m. For 10 N: e = F/k = 10 / 50 = 0.2 m." },
      { g: 7, marks: 3, q: "A crane lifts a 500 N load through a height of 12 m. Calculate the work done and state the energy transfer.", scheme: ["W = F x s = 500 x 12 = 6000 J", "Energy transferred to the gravitational potential energy store"], answer: "W = Fs = 500 x 12 = 6000 J, transferred to the load's gravitational potential energy store." },
      { g: 7, marks: 3, q: "A force of 30 N acts on a piston of area 0.006 m^2. Calculate the pressure produced.", scheme: ["p = F / A", "= 30 / 0.006", "= 5000 Pa"], answer: "p = F/A = 30 / 0.006 = 5000 Pa." },
      { g: 7, marks: 4, q: "A car accelerates uniformly from 8 m/s to 20 m/s in 6 s. Calculate its acceleration.", scheme: ["a = change in velocity / time = (v - u) / t", "= (20 - 8) / 6", "= 12 / 6", "= 2 m/s^2"], answer: "a = (v - u)/t = (20 - 8)/6 = 12/6 = 2 m/s^2." },
      { g: 7, marks: 4, q: "A cyclist accelerates from rest at 1.5 m/s^2 over a distance of 30 m. Calculate the final velocity using v^2 - u^2 = 2as.", scheme: ["v^2 = u^2 + 2as = 0 + (2 x 1.5 x 30)", "v^2 = 90", "v = square root of 90", "= 9.49 m/s (about 9.5 m/s)"], answer: "v^2 = u^2 + 2as = 0 + 2 x 1.5 x 30 = 90, so v = square root of 90 = 9.5 m/s." },
      { g: 7, marks: 3, q: "Calculate the pressure due to a column of water 3 m deep. (density of water = 1000 kg/m^3, g = 9.8 N/kg)", scheme: ["p = h x rho x g", "= 3 x 1000 x 9.8", "= 29 400 Pa"], answer: "p = h rho g = 3 x 1000 x 9.8 = 29 400 Pa." },
      { g: 7, marks: 4, q: "A 40 N force acts 0.5 m from a pivot on one side of a balanced beam. A load acts 0.2 m from the pivot on the other side. Calculate the load using the principle of moments.", scheme: ["Clockwise moment = anticlockwise moment", "40 x 0.5 = load x 0.2", "load = 20 / 0.2", "= 100 N"], answer: "For balance: 40 x 0.5 = load x 0.2, so load = 20 / 0.2 = 100 N." },
      { g: 7, marks: 3, q: "Explain how the thinking distance of a driver is affected by the speed of the car.", scheme: ["Thinking distance = speed x reaction time", "Reaction time is roughly constant", "So thinking distance increases as speed increases (proportionally)"], answer: "Thinking distance is speed multiplied by reaction time; as reaction time stays about the same, a higher speed gives a proportionally greater thinking distance." },
      { g: 7, marks: 3, q: "State Newton's third law and give an example.", scheme: ["When two objects interact, they exert equal and opposite forces on each other", "The forces are equal in size and opposite in direction", "Example: e.g. a swimmer pushes water back, water pushes swimmer forward"], answer: "When two objects interact they exert equal and opposite forces on each other. For example, a swimmer pushes the water backwards and the water pushes the swimmer forwards with an equal force." },
      { g: 7, marks: 3, q: "A skydiver falls at terminal velocity, then opens a parachute. Explain what happens to their motion immediately afterwards.", scheme: ["Air resistance increases (larger area)", "Air resistance now greater than weight -> resultant force upwards", "Skydiver decelerates"], answer: "Opening the parachute increases air resistance so it is now greater than the weight, giving an upward resultant force, so the skydiver decelerates." },
      { g: 7, marks: 3, q: "Calculate the distance travelled by a car shown on a velocity-time graph as a triangle rising uniformly from 0 to 24 m/s over 8 s.", scheme: ["Distance = area under graph = 1/2 x base x height", "= 1/2 x 8 x 24", "= 96 m"], answer: "Distance = area = 1/2 x base x height = 1/2 x 8 x 24 = 96 m." },
      { g: 7, marks: 3, q: "Explain why two identical cars have different braking distances when one is travelling faster.", scheme: ["Faster car has more kinetic energy", "More work must be done by the brakes to stop it", "So braking distance is greater"], answer: "The faster car has more kinetic energy, so the brakes must do more work to stop it, giving a longer braking distance." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "A 1500 kg car accelerates from 10 m/s to 30 m/s in 8 s. Calculate the resultant force needed.", scheme: ["a = (v - u)/t = (30 - 10)/8 = 2.5 m/s^2", "F = m x a", "= 1500 x 2.5", "= 3750 N"], answer: "a = (30 - 10)/8 = 2.5 m/s^2, then F = ma = 1500 x 2.5 = 3750 N." },
      { g: 8, marks: 4, q: "A trolley of mass 2 kg moving at 3 m/s collides with a stationary 1 kg trolley and they move off together. Calculate their common velocity using conservation of momentum. (HT)", scheme: ["Total momentum before = (2 x 3) + (1 x 0) = 6 kg m/s", "Momentum after = (2 + 1) x v", "6 = 3v", "v = 2 m/s"], answer: "Momentum before = 2 x 3 = 6 kg m/s. After: 6 = (2 + 1)v, so v = 6 / 3 = 2 m/s." },
      { g: 8, marks: 4, q: "A spring stores elastic potential energy of 0.9 J when compressed by 0.3 m within its limit of proportionality. Calculate its spring constant. (Ee = 1/2 k e^2)", scheme: ["Ee = 1/2 x k x e^2", "0.9 = 1/2 x k x 0.3^2 = 0.045k", "k = 0.9 / 0.045", "= 20 N/m"], answer: "Ee = 1/2 k e^2, so 0.9 = 0.5 x k x 0.09 = 0.045k, giving k = 0.9 / 0.045 = 20 N/m." },
      { g: 8, marks: 4, q: "A diver of weight 700 N stands on one foot of area 0.014 m^2. Calculate the pressure exerted on the floor, and explain the effect of standing on two feet.", scheme: ["p = F / A = 700 / 0.014 = 50 000 Pa", "On two feet the area doubles", "So the pressure halves (25 000 Pa)"], answer: "p = F/A = 700 / 0.014 = 50 000 Pa. On two feet the area doubles, so the pressure halves to about 25 000 Pa." },
      { g: 8, marks: 4, q: "A resultant horizontal force of 250 N acts on a car of mass 1000 kg against 100 N of resistive force. The 250 N is the engine's driving force. Calculate the acceleration.", scheme: ["Resultant force = 250 - 100 = 150 N", "a = F / m", "= 150 / 1000", "= 0.15 m/s^2"], answer: "Resultant force = 250 - 100 = 150 N, so a = F/m = 150 / 1000 = 0.15 m/s^2." },
      { g: 8, marks: 4, q: "Explain, using Newton's laws, what happens to a passenger in a car that stops suddenly, and why seatbelts are important.", scheme: ["Passenger continues moving forward due to inertia (Newton's first law)", "A large force is needed to decelerate them quickly", "Seatbelt provides this force over a longer time", "Reduces the force on the passenger (F = change in momentum / time), reducing injury"], answer: "By Newton's first law the passenger keeps moving forward due to inertia when the car stops. A seatbelt applies a backward force over a longer time, which by F = change in momentum / time reduces the force on them and so reduces injury." },
      { g: 8, marks: 4, q: "A ball is dropped from rest and falls freely for 2.5 s. Calculate its velocity and the distance fallen. (g = 9.8 m/s^2, ignore air resistance)", scheme: ["v = u + at = 0 + (9.8 x 2.5) = 24.5 m/s", "s = 1/2 x a x t^2 = 1/2 x 9.8 x 2.5^2", "= 0.5 x 9.8 x 6.25", "= 30.6 m"], answer: "v = u + at = 9.8 x 2.5 = 24.5 m/s. Distance s = 1/2 a t^2 = 0.5 x 9.8 x 6.25 = 30.6 m." },
      { g: 8, marks: 4, q: "A resultant force of 50 N acts on a 0.2 kg ball for 0.4 s. Calculate the change in momentum and the change in velocity. (HT)", scheme: ["Change in momentum = F x t = 50 x 0.4 = 20 kg m/s", "Change in velocity = change in momentum / mass", "= 20 / 0.2", "= 100 m/s"], answer: "Change in momentum = Ft = 50 x 0.4 = 20 kg m/s. Change in velocity = 20 / 0.2 = 100 m/s." },
      { g: 8, marks: 4, q: "Explain how gears can be used to change the moment (turning effect) transmitted in a machine.", scheme: ["Gears are toothed wheels that transmit the rotational effect", "A larger gear driven by a smaller one increases the moment", "Because force acts at a greater distance from the axle", "But the larger gear turns more slowly"], answer: "Gears transmit rotation through interlocking teeth. When a small gear drives a larger one, the force acts at a greater distance from the axle so the moment increases, though the larger gear turns more slowly." },
      { g: 8, marks: 4, q: "A rocket of mass 800 kg ejects gas so that it experiences a resultant upward force of 4000 N. Its weight is 7840 N. Explain whether it lifts off, showing working. (g = 9.8 N/kg)", scheme: ["Weight = m x g = 800 x 9.8 = 7840 N (downwards)", "Compare thrust with weight: 4000 N is the resultant upward force stated, but need thrust > weight", "If the 4000 N is the resultant, it is upward so it does lift off; net upward force accelerates it", "a = F/m = 4000/800 = 5 m/s^2 upward"], answer: "The stated 4000 N resultant force acts upward and exceeds nothing else, so the rocket accelerates upward at a = F/m = 4000 / 800 = 5 m/s^2, meaning it lifts off." },
      { g: 8, marks: 4, q: "Explain how the required practical for force and extension is used to identify the limit of proportionality of a spring.", scheme: ["Hang the spring and measure extension for increasing forces", "Plot a graph of force (y) against extension (x)", "Straight line through origin shows F proportional to e", "Limit of proportionality is where the line starts to curve"], answer: "Add increasing known forces and record the extension each time, then plot force against extension. The line is straight through the origin while force and extension are proportional; the point where it begins to curve is the limit of proportionality." },
      { g: 8, marks: 4, q: "A force of 8 N stretches a spring by 0.10 m within its limit of proportionality. Calculate the elastic potential energy stored. (Ee = 1/2 k e^2)", scheme: ["k = F / e = 8 / 0.10 = 80 N/m", "Ee = 1/2 x k x e^2 = 1/2 x 80 x 0.10^2", "= 0.5 x 80 x 0.01", "= 0.4 J"], answer: "k = F/e = 8 / 0.10 = 80 N/m, then Ee = 1/2 k e^2 = 0.5 x 80 x 0.01 = 0.4 J." },
      { g: 8, marks: 4, q: "Explain, in terms of forces, the whole motion of a skydiver from jumping out of a plane to landing.", scheme: ["At first weight is greater than air resistance -> accelerates", "As speed rises, air resistance increases", "When air resistance equals weight, resultant force is zero -> terminal velocity", "Parachute opens -> air resistance greater than weight -> decelerates to a new lower terminal velocity"], answer: "At first the weight is greater than air resistance, so the skydiver accelerates. As speed increases air resistance rises until it equals the weight, giving zero resultant force and terminal velocity. Opening the parachute makes air resistance greater than the weight, so they decelerate to a new, lower terminal velocity before landing." },
      { g: 8, marks: 4, q: "A liquid of density 800 kg/m^3 fills a tank. Calculate the pressure at a depth of 2.5 m and explain why the tank walls are thicker at the bottom. (g = 9.8 N/kg)", scheme: ["p = h x rho x g = 2.5 x 800 x 9.8 = 19 600 Pa", "Pressure increases with depth", "So walls must withstand greater pressure lower down"], answer: "p = h rho g = 2.5 x 800 x 9.8 = 19 600 Pa. Pressure increases with depth, so the walls near the bottom must be thicker to withstand the greater pressure." },
      { g: 8, marks: 4, q: "Explain why atmospheric pressure decreases as altitude increases.", scheme: ["Atmospheric pressure is caused by the weight of air above pressing down", "At higher altitude there is less air above", "The air is also less dense", "So fewer air molecules and less weight above -> lower pressure"], answer: "Atmospheric pressure is due to the weight of the air above pressing down. At higher altitude there is less air above and the air is less dense, so there are fewer molecules and less weight bearing down, giving a lower pressure." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "A 1200 kg car travelling at 24 m/s brakes to rest over a distance of 48 m. Calculate the deceleration, the braking force, and explain one danger of very large decelerations.", scheme: ["v^2 - u^2 = 2as: 0 - 24^2 = 2 x a x 48", "-576 = 96a, so a = -6 m/s^2 (deceleration 6 m/s^2)", "F = m x a = 1200 x 6 = 7200 N", "Large decelerations need very large forces", "Large forces can cause injury / brakes may overheat", "Reasoned link between force and hazard"], answer: "Using v^2 - u^2 = 2as: 0 - 576 = 96a, so a = -6 m/s^2 (a deceleration of 6 m/s^2). Braking force F = ma = 1200 x 6 = 7200 N. Such large decelerations require large forces, which can injure occupants and cause the brakes to overheat." },
      { g: 9, marks: 6, q: "A 0.16 kg ball hits a wall at 12 m/s and rebounds at 8 m/s in the opposite direction. The contact lasts 0.05 s. Calculate the force on the ball. (HT)", scheme: ["Take initial direction as positive: u = +12, v = -8 m/s", "Change in momentum = m(v - u) = 0.16 x (-8 - 12)", "= 0.16 x (-20) = -3.2 kg m/s", "F = change in momentum / time = -3.2 / 0.05", "= -64 N (64 N opposing the original motion)", "Correct treatment of direction/sign"], answer: "Taking the incoming direction as positive, change in momentum = 0.16 x (-8 - 12) = -3.2 kg m/s. Force = change in momentum / time = -3.2 / 0.05 = -64 N, i.e. 64 N acting away from the wall." },
      { g: 9, marks: 6, q: "Explain fully, in terms of forces and energy, how the total stopping distance of a car depends on both speed and road conditions.", scheme: ["Stopping distance = thinking distance + braking distance", "Thinking distance = speed x reaction time -> increases with speed", "Braking distance depends on kinetic energy (1/2 m v^2)", "Doubling speed quadruples braking distance", "Wet/icy roads or worn tyres reduce friction/grip -> longer braking distance", "Braking distance depends on work done by friction against kinetic energy"], answer: "Total stopping distance is thinking distance plus braking distance. Thinking distance is speed x reaction time, so it rises in proportion to speed. Braking distance depends on the kinetic energy (1/2 m v^2), so doubling the speed quadruples it. Poor conditions such as wet or icy roads and worn tyres reduce grip, so more distance is needed for friction to do the work of removing the kinetic energy." },
      { g: 9, marks: 6, q: "Two ice skaters, masses 60 kg and 40 kg, push apart from rest. The 60 kg skater moves at 2 m/s. Calculate the velocity of the 40 kg skater and explain the physics. (HT)", scheme: ["Total momentum before = 0 (both at rest)", "Momentum after must also be 0 (conservation of momentum)", "0 = (60 x 2) + (40 x v)", "120 + 40v = 0, so v = -3 m/s", "The 40 kg skater moves at 3 m/s in the opposite direction", "Newton's third law: equal and opposite forces during the push"], answer: "Total momentum before is zero, so it stays zero. 0 = (60 x 2) + (40 x v), giving v = -3 m/s, so the 40 kg skater moves at 3 m/s in the opposite direction. During the push each skater exerts an equal and opposite force on the other (Newton's third law)." },
      { g: 9, marks: 6, q: "An object of weight 500 N floats in water. Explain, in terms of upthrust and displaced water, why it floats and how the volume submerged is determined. (HT)", scheme: ["Upthrust equals the weight of fluid displaced", "Object floats when upthrust equals its weight", "So it displaces 500 N of water", "The object sinks until enough water is displaced to give this upthrust", "Object floats because its average density is less than water", "Balanced forces -> resultant force zero -> stays floating"], answer: "The upthrust on an object equals the weight of fluid it displaces. It floats when this upthrust equals its weight, so it sinks until it displaces 500 N of water. Because its average density is less than water it can do this while partly submerged; the forces then balance, giving zero resultant force so it stays floating." },
      { g: 9, marks: 5, q: "A force of 6 N is applied at 30 degrees to the horizontal to pull a sledge 10 m horizontally. Calculate the work done on the sledge in the horizontal direction. (HT, cos 30 = 0.87)", scheme: ["Only the horizontal component does work along the motion", "Horizontal component = F cos 30 = 6 x 0.87 = 5.2 N", "W = F x s = 5.2 x 10", "= 52 J", "Correct resolving of the force"], answer: "Only the horizontal component of the force acts along the motion: F cos 30 = 6 x 0.87 = 5.2 N. Work done = 5.2 x 10 = 52 J." },
      { g: 9, marks: 6, q: "Describe how you would use a scale diagram to find the resultant of two forces of 3 N and 4 N acting at right angles, and state the resultant. (HT)", scheme: ["Choose a suitable scale (e.g. 1 cm = 1 N)", "Draw the two forces to scale, tip to tail (or as arrows from a point)", "Complete the parallelogram / draw the resultant from start to finish", "Measure the length and convert using the scale", "Measure the angle with a protractor for direction", "Resultant = 5 N (since 3^2 + 4^2 = 5^2)"], answer: "Pick a scale such as 1 cm = 1 N, draw the two forces to scale as a right angle, then draw the resultant from the tail of the first to the tip of the second and measure it. Converting gives 5 N (as 3^2 + 4^2 = 5^2), and the protractor gives its direction." },
      { g: 9, marks: 6, q: "A car of mass 900 kg accelerates uniformly from rest to 25 m/s in 10 s, then travels at constant speed. Calculate the acceleration, the driving force during acceleration, and the distance covered in the first 10 s.", scheme: ["a = (v - u)/t = (25 - 0)/10 = 2.5 m/s^2", "F = m x a = 900 x 2.5 = 2250 N", "Distance = area under v-t graph = 1/2 x base x height", "= 1/2 x 10 x 25", "= 125 m", "Correct use of all three relationships"], answer: "a = (25 - 0)/10 = 2.5 m/s^2. Driving force F = ma = 900 x 2.5 = 2250 N. Distance in the first 10 s = area under the graph = 1/2 x 10 x 25 = 125 m." },
      { g: 9, marks: 6, q: "Explain, using Newton's laws and momentum, how crumple zones and airbags reduce injury in a car crash. (HT)", scheme: ["In a crash the occupant's momentum must be reduced to zero", "Force = change in momentum / time", "Crumple zones and airbags increase the time of the collision", "Increasing time reduces the rate of change of momentum", "So the force on the occupant is smaller", "Smaller force reduces injury"], answer: "In a crash the occupant's momentum must fall to zero. Since force = change in momentum / time, extending the time over which this happens reduces the force. Crumple zones and airbags increase the collision time, so the rate of change of momentum, and therefore the force on the occupant, is smaller, reducing injury." },
      { g: 9, marks: 5, q: "A spring obeys Hooke's law up to 5 N, where its extension is 0.10 m. Beyond this it deforms inelastically. Explain what the force-extension graph looks like and calculate the work done stretching it to the limit of proportionality.", scheme: ["Straight line through the origin up to the limit (proportional region)", "Beyond the limit the line curves (extension increases faster)", "Work done = area under the straight section = 1/2 x F x e", "= 1/2 x 5 x 0.10", "= 0.25 J"], answer: "The graph is a straight line through the origin up to the limit of proportionality, then curves as the spring extends more per unit force. Work done to the limit = area = 1/2 x F x e = 0.5 x 5 x 0.10 = 0.25 J." },
      { g: 9, marks: 6, q: "A submarine dives to a depth of 120 m in seawater of density 1030 kg/m^3. Calculate the water pressure at that depth and explain, in terms of forces, why the submarine does not get crushed. (g = 9.8 N/kg)", scheme: ["p = h x rho x g = 120 x 1030 x 9.8", "= 1 211 280 Pa (about 1.21 MPa)", "Water pushes inwards with a large force on the hull", "The hull is strong / thick to withstand this", "Internal pressure and hull strength provide an outward/balancing effect", "Resultant inward force is resisted so it is not crushed"], answer: "p = h rho g = 120 x 1030 x 9.8 = 1 211 280 Pa (about 1.21 MPa). The water pushes inwards on the hull with a large force, but the hull is built strong and thick so it can withstand this pressure without being crushed." },
      { g: 9, marks: 6, q: "A ball of mass 0.5 kg is thrown straight up at 20 m/s. Ignoring air resistance, calculate the maximum height reached and the time to reach it. (g = 9.8 m/s^2)", scheme: ["At the top v = 0", "v^2 - u^2 = 2as: 0 - 20^2 = 2 x (-9.8) x s", "-400 = -19.6s, so s = 20.4 m", "Time: v = u + at, 0 = 20 - 9.8t", "t = 20 / 9.8 = 2.04 s"], answer: "At the highest point v = 0. Using v^2 - u^2 = 2as: -400 = -19.6s, so s = 20.4 m. Time: 0 = 20 - 9.8t, so t = 20 / 9.8 = 2.04 s." },
      { g: 9, marks: 5, q: "Explain the difference between mass, weight and inertia, and how each would change for an object taken from Earth to the Moon.", scheme: ["Mass is the amount of matter; it stays the same on the Moon", "Weight is the gravitational force (W = mg); it decreases on the Moon (smaller g)", "Inertia is the resistance to a change in motion; it depends on mass so is unchanged", "Clear link between inertia and mass", "Correct statement that only weight changes"], answer: "Mass is the amount of matter and stays the same on the Moon. Weight is the gravitational force (W = mg) and is smaller on the Moon because g is smaller. Inertia is the resistance to a change in motion and depends only on mass, so it is unchanged; only the weight changes." },
      { g: 9, marks: 6, q: "A gear system has a driver gear of 10 teeth turning a gear of 40 teeth. The driver applies a moment of 5 Nm. Explain the effect on turning speed and moment, and estimate the output moment.", scheme: ["The larger gear turns more slowly (4 times slower, ratio 40:10)", "Speed ratio = 10:40 = 1:4", "Moment (turning effect) increases in the same ratio", "Output moment = 5 x 4 = 20 Nm", "Because force acts at a greater radius on the larger gear", "Trade-off: greater moment but lower rotational speed"], answer: "The 40-tooth gear turns 4 times more slowly than the 10-tooth driver (ratio 40:10). The turning effect increases by the same factor, so the output moment is about 5 x 4 = 20 Nm. This is because the force acts at a greater radius, giving a larger moment at the cost of lower rotational speed." },
      { g: 9, marks: 6, q: "A 2000 kg lorry moving at 15 m/s collides with a stationary 1000 kg car. After the collision the lorry continues at 9 m/s in the same direction. Calculate the velocity of the car immediately after the collision. (HT)", scheme: ["Total momentum before = (2000 x 15) + (1000 x 0) = 30 000 kg m/s", "Momentum after = (2000 x 9) + (1000 x v)", "30 000 = 18 000 + 1000v", "1000v = 12 000", "v = 12 m/s in the original direction", "Correct use of conservation of momentum"], answer: "Momentum before = 2000 x 15 = 30 000 kg m/s. After: 30 000 = (2000 x 9) + 1000v = 18 000 + 1000v, so 1000v = 12 000 and v = 12 m/s in the original direction of travel." },
    ],
    "6. Waves": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What type of wave is a sound wave?", scheme: ["Longitudinal"], answer: "A longitudinal wave." },
      { g: 4, marks: 1, q: "Give one example of a transverse wave.", scheme: ["Light / electromagnetic wave / water wave / wave on a rope (any one)"], answer: "A light wave (or a water wave or a wave on a rope)." },
      { g: 4, marks: 1, q: "What name is given to the maximum displacement of a wave from its rest position?", scheme: ["Amplitude"], answer: "The amplitude." },
      { g: 4, marks: 1, q: "What name is given to the distance from one wave crest to the next?", scheme: ["Wavelength"], answer: "The wavelength." },
      { g: 4, marks: 1, q: "What is the frequency of a wave measured in?", scheme: ["Hertz (Hz)"], answer: "Hertz (Hz)." },
      { g: 4, marks: 1, q: "What does frequency tell you about a wave?", scheme: ["Number of waves passing a point each second"], answer: "The number of waves passing a point each second." },
      { g: 4, marks: 1, q: "Which type of wave has areas of compression and rarefaction?", scheme: ["Longitudinal"], answer: "A longitudinal wave." },
      { g: 4, marks: 1, q: "In which direction do the vibrations move in a transverse wave, compared with the direction the wave travels?", scheme: ["At right angles / perpendicular to the direction of travel"], answer: "At right angles (perpendicular) to the direction the wave travels." },
      { g: 4, marks: 1, q: "Name the part of the electromagnetic spectrum that we can see with our eyes.", scheme: ["Visible light"], answer: "Visible light." },
      { g: 4, marks: 1, q: "Which type of electromagnetic wave is used to cook food in a microwave oven?", scheme: ["Microwaves"], answer: "Microwaves." },
      { g: 4, marks: 1, q: "Name the electromagnetic wave used in a television remote control.", scheme: ["Infrared"], answer: "Infrared." },
      { g: 4, marks: 1, q: "Which type of electromagnetic wave is used to take images of broken bones?", scheme: ["X-rays"], answer: "X-rays." },
      { g: 4, marks: 1, q: "What can waves transfer from one place to another without transferring matter?", scheme: ["Energy (and information)"], answer: "Energy (and information)." },
      { g: 4, marks: 1, q: "What happens to a wave when it bounces off a surface?", scheme: ["It is reflected / reflection"], answer: "It is reflected." },
      { g: 4, marks: 1, q: "State the range of frequencies that a healthy human can hear.", scheme: ["20 Hz to 20 000 Hz (20 kHz)"], answer: "From 20 Hz to 20 000 Hz (20 kHz)." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 1, q: "Define the amplitude of a wave.", scheme: ["Maximum displacement of a point from its rest/undisturbed position"], answer: "The maximum displacement of a point on the wave from its rest position." },
      { g: 5, marks: 1, q: "Define the wavelength of a wave.", scheme: ["Distance from a point on one wave to the same point on the next wave"], answer: "The distance from a point on one wave to the equivalent point on the next wave." },
      { g: 5, marks: 1, q: "Define the frequency of a wave.", scheme: ["Number of waves passing a point (or produced) per second"], answer: "The number of waves passing a point each second." },
      { g: 5, marks: 1, q: "State the equation linking period and frequency.", scheme: ["period = 1 / frequency (T = 1/f)"], answer: "Period = 1 / frequency, so T = 1/f." },
      { g: 5, marks: 2, q: "State the wave speed equation and give the unit of wave speed.", scheme: ["wave speed = frequency x wavelength (v = f x wavelength)", "Unit is metres per second (m/s)"], answer: "Wave speed = frequency x wavelength (v = fλ), measured in m/s." },
      { g: 5, marks: 2, q: "Give two differences between transverse and longitudinal waves.", scheme: ["Transverse: vibrations perpendicular to travel; longitudinal: vibrations parallel to travel", "Longitudinal has compressions and rarefactions; transverse has crests and troughs"], answer: "In transverse waves the vibrations are perpendicular to travel with crests and troughs; in longitudinal waves the vibrations are parallel to travel with compressions and rarefactions." },
      { g: 5, marks: 1, q: "In which type of wave do the particles vibrate parallel to the direction the wave travels?", scheme: ["Longitudinal"], answer: "A longitudinal wave." },
      { g: 5, marks: 1, q: "State the period of a wave in words.", scheme: ["The time taken for one complete wave/oscillation to pass a point"], answer: "The time taken for one complete wave to pass a point." },
      { g: 5, marks: 2, q: "A wave has a frequency of 2 Hz. Calculate its period.", scheme: ["T = 1/f = 1/2", "= 0.5 s"], answer: "T = 1/f = 1/2 = 0.5 s." },
      { g: 5, marks: 2, q: "List the seven groups of the electromagnetic spectrum in order of increasing frequency.", scheme: ["Radio, microwave, infrared, visible, ultraviolet", "X-ray, gamma"], answer: "Radio, microwave, infrared, visible, ultraviolet, X-ray, gamma." },
      { g: 5, marks: 1, q: "At what speed do all electromagnetic waves travel in a vacuum?", scheme: ["The same speed (the speed of light, 3 x 10^8 m/s)"], answer: "They all travel at the same speed, the speed of light (3 x 10^8 m/s)." },
      { g: 5, marks: 1, q: "Are all electromagnetic waves transverse or longitudinal?", scheme: ["Transverse"], answer: "They are all transverse." },
      { g: 5, marks: 2, q: "State one use of ultrasound.", scheme: ["Prenatal (pregnancy) scanning / medical imaging / echo sounding / cleaning (any one)"], answer: "Ultrasound is used for prenatal scanning of a baby (or for echo sounding)." },
      { g: 5, marks: 1, q: "What happens to the direction of a wave when it is reflected from a flat mirror?", scheme: ["The angle of reflection equals the angle of incidence"], answer: "It reflects so that the angle of reflection equals the angle of incidence." },
      { g: 5, marks: 2, q: "Name the two types of seismic wave produced by an earthquake.", scheme: ["P waves (longitudinal)", "S waves (transverse)"], answer: "P waves (longitudinal) and S waves (transverse)." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "A wave has a frequency of 5 Hz and a wavelength of 2 m. Calculate its speed.", scheme: ["v = f x wavelength = 5 x 2", "= 10 m/s"], answer: "v = fλ = 5 x 2 = 10 m/s." },
      { g: 6, marks: 2, q: "A wave travels at 340 m/s with a wavelength of 0.85 m. Calculate its frequency.", scheme: ["f = v / wavelength = 340 / 0.85", "= 400 Hz"], answer: "f = v / λ = 340 / 0.85 = 400 Hz." },
      { g: 6, marks: 2, q: "A wave has a period of 0.02 s. Calculate its frequency.", scheme: ["f = 1/T = 1/0.02", "= 50 Hz"], answer: "f = 1/T = 1/0.02 = 50 Hz." },
      { g: 6, marks: 3, q: "A sound wave travels at 330 m/s and has a frequency of 220 Hz. Calculate its wavelength.", scheme: ["wavelength = v / f = 330 / 220", "= 1.5", "= 1.5 m"], answer: "Wavelength = v / f = 330 / 220 = 1.5 m." },
      { g: 6, marks: 2, q: "Explain why we describe a sound wave as a longitudinal wave.", scheme: ["The air particles vibrate back and forth", "In the same direction as the wave travels (parallel)"], answer: "The air particles vibrate back and forth in the same direction that the wave travels, so it is longitudinal." },
      { g: 6, marks: 2, q: "Explain what is meant by refraction of a wave.", scheme: ["The wave changes direction / bends", "When it crosses a boundary between two different materials/media"], answer: "Refraction is when a wave changes direction as it crosses a boundary between two different media." },
      { g: 6, marks: 2, q: "Give one use and one danger of ultraviolet radiation.", scheme: ["Use: security marking / detecting forged notes / disinfecting water / tanning (any one)", "Danger: skin ageing / skin cancer / eye damage (any one)"], answer: "Use: security marking. Danger: it can cause skin cancer." },
      { g: 6, marks: 3, q: "Describe how you could measure the speed of a wave on a string using a signal generator and vibration transducer.", scheme: ["Measure the frequency from the signal generator", "Measure the wavelength (e.g. length of one or more loops of the standing wave)", "Use v = f x wavelength to calculate the speed"], answer: "Read the frequency from the signal generator, measure the wavelength from the loops of the standing wave, then calculate speed using v = fλ." },
      { g: 6, marks: 2, q: "State one use of infrared radiation and explain why it is suitable.", scheme: ["Use: cooking / heaters / thermal imaging / remote controls (any one)", "Suitable because it is absorbed and transfers energy by heating (or detected as heat)"], answer: "Infrared is used in electric heaters because it is absorbed by objects and transfers energy by heating them." },
      { g: 6, marks: 2, q: "A microwave has a frequency of 3 x 10^9 Hz and travels at 3 x 10^8 m/s. Calculate its wavelength.", scheme: ["wavelength = v / f = (3 x 10^8) / (3 x 10^9)", "= 0.1 m"], answer: "Wavelength = v / f = (3 x 10^8) / (3 x 10^9) = 0.1 m." },
      { g: 6, marks: 2, q: "Describe how ultrasound can be used to measure the depth of the sea (echo sounding).", scheme: ["A pulse of ultrasound is sent down and reflects off the sea bed", "The time for the echo to return is measured and used with the speed to find distance"], answer: "A pulse of ultrasound is sent to the sea bed, reflects back, and the time for the echo is measured; using distance = speed x time gives the depth." },
      { g: 6, marks: 2, q: "Explain why radio waves are used for broadcasting and communication.", scheme: ["They can travel long distances / through the atmosphere", "They are not strongly absorbed / can be transmitted and received by aerials"], answer: "Radio waves can travel long distances through the atmosphere and are easily transmitted and received by aerials." },
      { g: 6, marks: 2, q: "State two properties that are the same for all electromagnetic waves.", scheme: ["They are all transverse", "They all travel at the same speed in a vacuum"], answer: "They are all transverse and all travel at the same speed in a vacuum." },
      { g: 6, marks: 3, q: "A student counts 10 complete water waves passing a point in 5 seconds. The wavelength is 0.4 m. Calculate the wave speed.", scheme: ["f = 10 / 5 = 2 Hz", "v = f x wavelength = 2 x 0.4", "= 0.8 m/s"], answer: "f = 10/5 = 2 Hz, then v = fλ = 2 x 0.4 = 0.8 m/s." },
      { g: 6, marks: 2, q: "Explain the difference between a P wave and an S wave in terms of the material they can pass through.", scheme: ["P waves (longitudinal) can travel through solids and liquids", "S waves (transverse) can only travel through solids"], answer: "P waves are longitudinal and travel through both solids and liquids, but S waves are transverse and travel only through solids." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "A wave has a frequency of 50 Hz and a wavelength of 0.2 m. Calculate its speed and give the unit.", scheme: ["v = f x wavelength", "= 50 x 0.2", "= 10 m/s"], answer: "v = fλ = 50 x 0.2 = 10 m/s." },
      { g: 7, marks: 3, q: "A radio wave has a wavelength of 300 m and travels at 3 x 10^8 m/s. Calculate its frequency.", scheme: ["f = v / wavelength", "= (3 x 10^8) / 300", "= 1 000 000 Hz (1 x 10^6 Hz)"], answer: "f = v / λ = (3 x 10^8) / 300 = 1 000 000 Hz (1 x 10^6 Hz)." },
      { g: 7, marks: 3, q: "An object is 2 cm tall and its image is 6 cm tall. Calculate the magnification produced by the lens.", scheme: ["magnification = image height / object height", "= 6 / 2", "= 3 (no unit)"], answer: "Magnification = image height / object height = 6 / 2 = 3." },
      { g: 7, marks: 4, q: "Describe the required practical to measure the speed of water waves in a ripple tank.", scheme: ["Use a signal generator/dipper to make waves of known frequency", "Measure the wavelength (e.g. distance across several waves / using a shadow on paper, then divide)", "Calculate speed using v = frequency x wavelength", "Repeat and take a mean to improve accuracy"], answer: "Set the dipper to a known frequency, measure the wavelength by finding the distance across several waves and dividing, then use v = fλ to find the speed, repeating for a mean." },
      { g: 7, marks: 3, q: "A sound wave in air has a period of 0.004 s and a wavelength of 1.32 m. Calculate the speed of sound.", scheme: ["f = 1/T = 1/0.004 = 250 Hz", "v = f x wavelength = 250 x 1.32", "= 330 m/s"], answer: "f = 1/T = 1/0.004 = 250 Hz, then v = fλ = 250 x 1.32 = 330 m/s." },
      { g: 7, marks: 3, q: "Explain, using wave fronts, how a wave changes direction when it slows down as it crosses a boundary.", scheme: ["The wave fronts reach the boundary at an angle and slow down", "The part that enters first slows first, so the wave fronts bend/change direction", "The wave bends towards the normal"], answer: "When the wave fronts meet the boundary at an angle, the side that enters the slower medium first slows first, so the wave fronts bend and the wave changes direction, bending towards the normal." },
      { g: 7, marks: 3, q: "Explain why the frequency of a wave stays the same but its wavelength changes when it refracts. (HT)", scheme: ["Frequency is set by the source and does not change", "The wave speed changes in the new medium", "Since v = f x wavelength and f is constant, wavelength must change"], answer: "The source fixes the frequency so it stays constant; when the wave speed changes in the new medium, wavelength changes because v = fλ with f fixed." },
      { g: 7, marks: 4, q: "Describe how radio waves can be produced and how they can be absorbed. (HT)", scheme: ["Produced by oscillations/alternating current in an electrical circuit", "The oscillating charges create the radio waves emitted by an aerial", "When absorbed by another aerial they induce an alternating current", "This current has the same frequency as the radio wave"], answer: "Radio waves are produced by oscillations (alternating currents) in a circuit connected to an aerial. When they are absorbed by another aerial they cause an alternating current of the same frequency as the radiation." },
      { g: 7, marks: 3, q: "A converging lens forms an image. The object is 4 cm tall and the magnification is 2.5. Calculate the image height.", scheme: ["image height = magnification x object height", "= 2.5 x 4", "= 10 cm"], answer: "Image height = magnification x object height = 2.5 x 4 = 10 cm." },
      { g: 7, marks: 3, q: "Explain why a converging (convex) lens is described as converging.", scheme: ["Parallel rays passing through are refracted", "They are brought together / converge to a point (the principal focus)", "Because the lens is thicker in the middle"], answer: "A converging lens is thicker in the middle, so it refracts parallel rays inwards to meet at the principal focus." },
      { g: 7, marks: 3, q: "Sound waves cannot travel through a vacuum but light can. Explain why.", scheme: ["Sound needs particles/a medium to vibrate and pass on the wave", "A vacuum has no particles", "Light is an electromagnetic wave and does not need a medium"], answer: "Sound is a longitudinal wave that needs particles to vibrate, and a vacuum has none, whereas light is an electromagnetic wave that does not need a medium." },
      { g: 7, marks: 3, q: "Explain how ultrasound is used to produce an image of a baby in the womb.", scheme: ["Ultrasound pulses are sent into the body", "They are partly reflected at boundaries between different tissues", "The reflected pulses (and their timing) are processed to build an image"], answer: "Ultrasound pulses enter the body and are partly reflected at each boundary between tissues; the reflections and their timings are processed by a computer to form an image." },
      { g: 7, marks: 3, q: "An X-ray machine emits waves of frequency 3 x 10^18 Hz. Calculate the wavelength. (speed = 3 x 10^8 m/s)", scheme: ["wavelength = v / f = (3 x 10^8) / (3 x 10^18)", "= 1 x 10^-10 m", "(0.1 nm)"], answer: "Wavelength = v / f = (3 x 10^8) / (3 x 10^18) = 1 x 10^-10 m." },
      { g: 7, marks: 3, q: "Explain why gamma rays and X-rays are dangerous to living cells.", scheme: ["They are ionising radiation", "They can damage or mutate cells / DNA", "This can cause cancer"], answer: "They are ionising, so they can damage cells and cause mutations in DNA, which can lead to cancer." },
      { g: 7, marks: 3, q: "The speed of light in glass is less than in air. Explain what happens to a light ray as it passes from air into a glass block at an angle. (HT)", scheme: ["The light slows down in the glass", "It refracts / changes direction", "It bends towards the normal"], answer: "The light slows down in the glass and refracts, bending towards the normal as it enters." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "A wave on a string has a frequency of 40 Hz. Five complete wavelengths fit into a length of 1.5 m. Calculate the wave speed.", scheme: ["wavelength = 1.5 / 5 = 0.3 m", "v = f x wavelength = 40 x 0.3", "= 12 m/s", "Unit m/s given"], answer: "Wavelength = 1.5/5 = 0.3 m, then v = fλ = 40 x 0.3 = 12 m/s." },
      { g: 8, marks: 4, q: "Explain how the structure of a converging lens and a diverging lens leads to their different effects on parallel light rays.", scheme: ["Converging lens is thicker in the middle", "It refracts parallel rays to a real principal focus (they converge)", "Diverging lens is thinner in the middle", "It spreads parallel rays out so they appear to come from a virtual focus"], answer: "A converging lens is thicker in the middle so it bends parallel rays inwards to a real focus, while a diverging lens is thinner in the middle so it spreads parallel rays outwards, appearing to come from a virtual focus." },
      { g: 8, marks: 4, q: "A ship sends an ultrasound pulse to the sea bed and the echo returns after 0.6 s. The speed of sound in water is 1500 m/s. Calculate the depth of the sea.", scheme: ["Total distance = speed x time = 1500 x 0.6 = 900 m", "This is there and back, so depth = 900 / 2", "= 450 m", "Correct unit m"], answer: "Total distance = 1500 x 0.6 = 900 m; this is to the sea bed and back, so depth = 900/2 = 450 m." },
      { g: 8, marks: 4, q: "Describe and explain the properties of an image formed by a converging lens when the object is placed beyond twice the focal length.", scheme: ["The image is real", "It is inverted", "It is smaller (diminished)", "It forms on the opposite side of the lens to the object"], answer: "The image is real, inverted and smaller than the object, and it forms on the opposite side of the lens." },
      { g: 8, marks: 4, q: "Explain fully how a change in wave speed at a boundary causes refraction, referring to wavelength and frequency. (HT)", scheme: ["Frequency stays constant as it is set by the source", "In the new medium the wave travels at a different speed", "Because v = f x wavelength, the wavelength changes", "If it slows, wavelength decreases and the wave bends towards the normal"], answer: "The frequency is fixed by the source, so when the wave enters a medium where it travels at a different speed the wavelength must change (v = fλ). If it slows, the wavelength shortens and the wave bends towards the normal." },
      { g: 8, marks: 4, q: "Explain how seismic P and S waves provide evidence about the Earth's internal structure. (HT)", scheme: ["P waves travel through both solids and liquids; S waves only through solids", "S waves are not detected on the far side of the Earth", "This shows there is a liquid outer core (S waves cannot pass)", "P waves change direction (refract), showing boundaries between layers"], answer: "P waves pass through solids and liquids but S waves only through solids. S waves are not detected across the Earth, showing the outer core is liquid, and the way P waves refract reveals the boundaries between the Earth's layers." },
      { g: 8, marks: 4, q: "A converging lens has an object 3 cm tall placed in front of it. The real image is 9 cm tall. Calculate the magnification and state whether the image is magnified.", scheme: ["magnification = image height / object height = 9 / 3", "= 3", "No unit", "Image is magnified (larger than object)"], answer: "Magnification = 9/3 = 3, which has no unit; as it is greater than 1 the image is magnified." },
      { g: 8, marks: 4, q: "Explain how a perfect black body both absorbs and emits radiation. (Physics only)", scheme: ["A perfect black body absorbs all radiation that falls on it (reflects/transmits none)", "It is also the best possible emitter of radiation", "As it gets hotter it emits more radiation / at shorter wavelengths (higher peak frequency)"], answer: "A perfect black body absorbs all the radiation falling on it and reflects none, and it is also the best possible emitter; as it heats up it emits more radiation and at shorter wavelengths." },
      { g: 8, marks: 4, q: "Explain, in terms of absorbing and emitting radiation, how the temperature of the Earth is kept roughly constant. (Physics only)", scheme: ["The Earth absorbs radiation from the Sun (mainly visible/shorter wavelengths)", "The Earth emits radiation back into space (mainly infrared/longer wavelengths)", "When the rate of absorption equals the rate of emission, temperature is constant", "If they are unequal the temperature rises or falls"], answer: "The Earth absorbs short-wavelength radiation from the Sun and emits longer-wavelength infrared to space; when the rate absorbed equals the rate emitted its temperature stays constant, but if they differ its temperature rises or falls." },
      { g: 8, marks: 4, q: "A sound of frequency 25 000 Hz is produced. Explain whether a human can hear it and state what such sound is called.", scheme: ["Human hearing range is 20 Hz to 20 000 Hz", "25 000 Hz is above 20 000 Hz", "So it cannot be heard", "It is called ultrasound"], answer: "Human hearing goes up to 20 000 Hz, and 25 000 Hz is above this, so it cannot be heard; it is called ultrasound." },
      { g: 8, marks: 4, q: "Describe how sound is converted so that it can be heard in the human ear. (HT)", scheme: ["Sound waves cause the ear drum to vibrate", "These vibrations pass through small bones in the ear", "The vibrations are passed to other structures which turn them into signals", "Only frequencies in the 20 Hz to 20 kHz range are detected"], answer: "Sound waves make the ear drum vibrate; these vibrations are passed on by small bones to other structures that convert them into signals, but only frequencies from 20 Hz to 20 kHz can be detected." },
      { g: 8, marks: 4, q: "Compare the wavelength, frequency and energy of radio waves and gamma rays in the electromagnetic spectrum.", scheme: ["Radio waves have the longest wavelength; gamma rays the shortest", "Radio waves have the lowest frequency; gamma rays the highest", "Gamma rays carry the most energy; radio waves the least", "Both are transverse and travel at the same speed in a vacuum"], answer: "Radio waves have the longest wavelength, lowest frequency and least energy, while gamma rays have the shortest wavelength, highest frequency and most energy; both are transverse and travel at the same speed in a vacuum." },
      { g: 8, marks: 4, q: "A ripple tank produces 15 waves in 3 seconds. The distance across 6 waves is measured as 1.2 m. Calculate the speed of the waves.", scheme: ["f = 15 / 3 = 5 Hz", "wavelength = 1.2 / 6 = 0.2 m", "v = f x wavelength = 5 x 0.2", "= 1 m/s"], answer: "f = 15/3 = 5 Hz, wavelength = 1.2/6 = 0.2 m, so v = fλ = 5 x 0.2 = 1 m/s." },
      { g: 8, marks: 4, q: "Explain why using a wall to measure the speed of sound by echoes can give inaccurate results, and how the method could be improved.", scheme: ["The time interval is very short and hard to measure by hand", "Reaction time causes large errors", "Improve by standing further away / measuring many echoes and averaging", "Use electronic timing (microphones and a data logger)"], answer: "The echo time is very short, so human reaction time causes large errors; standing further away, timing many echoes and averaging, or using microphones with a data logger would improve accuracy." },
      { g: 8, marks: 4, q: "Explain why microwaves are suitable for satellite communication but not all electromagnetic waves are.", scheme: ["Microwaves can pass through the atmosphere / are not fully absorbed by it", "They can travel to and from satellites in space", "Some waves (e.g. certain radio waves) are reflected or absorbed by the atmosphere", "Their short wavelength allows them to carry information"], answer: "Microwaves pass through the Earth's atmosphere without being fully absorbed, so they can reach satellites and return, unlike some radio waves that are reflected or absorbed, and their short wavelength lets them carry information." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Compare transverse and longitudinal waves fully, using examples and describing how each transfers energy.", scheme: ["Transverse: vibrations perpendicular to the direction of energy transfer", "Transverse examples: electromagnetic waves / water waves / waves on a rope", "Transverse have crests and troughs", "Longitudinal: vibrations parallel to the direction of energy transfer", "Longitudinal examples: sound / some seismic (P) waves", "Longitudinal have compressions and rarefactions; both transfer energy not matter"], answer: "In transverse waves the oscillations are perpendicular to the direction of energy transfer, with crests and troughs; examples are electromagnetic and water waves. In longitudinal waves the oscillations are parallel to the transfer, with compressions and rarefactions; examples are sound and P waves. Both transfer energy, not matter." },
      { g: 9, marks: 6, q: "A wave generator on a string is set to 60 Hz. Four complete loops (half-wavelengths) fit into a 1.2 m length. Calculate the wavelength, then the wave speed, showing full working and units.", scheme: ["Each loop is half a wavelength, so length of one loop = 1.2 / 4 = 0.3 m", "wavelength = 2 x 0.3 = 0.6 m", "v = f x wavelength = 60 x 0.6", "= 36 m/s", "Unit m/s stated", "Working shown clearly"], answer: "Each loop is half a wavelength: 1.2/4 = 0.3 m per loop, so wavelength = 2 x 0.3 = 0.6 m. Then v = fλ = 60 x 0.6 = 36 m/s." },
      { g: 9, marks: 6, q: "Explain the properties, one use and one danger of each of these electromagnetic waves: ultraviolet, X-rays and gamma rays.", scheme: ["Ultraviolet: use security marking/sterilising; danger skin cancer/eye damage", "X-rays: use medical imaging of bones/security scanning; danger ionising, damages cells", "Gamma: use treating cancer/sterilising equipment; danger ionising, causes mutations/cancer", "All three are transverse and travel at the speed of light in a vacuum", "Frequency increases UV -> X-ray -> gamma", "Higher frequency means more energy and greater ionising ability"], answer: "Ultraviolet is used for security marking but can cause skin cancer; X-rays image bones but are ionising and damage cells; gamma rays treat cancer and sterilise equipment but cause mutations. All are transverse and travel at the speed of light, and as frequency rises from UV to X-ray to gamma the energy and ionising ability increase." },
      { g: 9, marks: 6, q: "A ship uses ultrasound of frequency 40 000 Hz to map the sea bed. The pulse returns after 0.8 s and the speed of sound in water is 1500 m/s. Calculate the depth of the sea and the wavelength of the ultrasound, showing full working.", scheme: ["Total distance = speed x time = 1500 x 0.8 = 1200 m", "Depth = 1200 / 2 = 600 m", "wavelength = v / f = 1500 / 40 000", "= 0.0375 m", "Units m stated for both", "Working shown clearly"], answer: "Distance = 1500 x 0.8 = 1200 m, so depth = 1200/2 = 600 m. Wavelength = v/f = 1500/40 000 = 0.0375 m." },
      { g: 9, marks: 6, q: "Explain fully, using v = f x wavelength, why a wave refracts when it passes from deep to shallow water at an angle, referring to wave fronts, speed, wavelength and frequency. (HT)", scheme: ["The wave slows down in shallow water", "Frequency stays constant (set by the source)", "So wavelength decreases because v = f x wavelength", "Wave fronts reach the boundary at an angle", "The part entering shallow water first slows first", "This bends the wave fronts, so the wave changes direction (towards the normal)"], answer: "In shallow water the wave slows down, but the frequency stays constant, so from v = fλ the wavelength decreases. Because the wave fronts meet the boundary at an angle, the part reaching the shallow water first slows first, bending the wave fronts so the wave changes direction towards the normal." },
      { g: 9, marks: 6, q: "Describe the required practical to measure the speed of a wave on a string, explaining how to obtain accurate values of frequency and wavelength.", scheme: ["Attach a string to a vibration transducer driven by a signal generator, with a mass over a pulley for tension", "Adjust the frequency until a clear standing wave with whole loops is seen", "Read the frequency directly from the signal generator", "Measure the length of several loops and divide to reduce error; each loop is half a wavelength", "Calculate wavelength then v = f x wavelength", "Repeat and take means / vary frequency to check"], answer: "Set up a string on a vibration transducer driven by a signal generator with a hanging mass for tension, then adjust the frequency until a clear standing wave forms. Read the frequency from the generator, measure several loops and divide to find the loop length (each loop is half a wavelength), calculate the wavelength and then v = fλ, repeating for a mean." },
      { g: 9, marks: 6, q: "An object 5 cm tall is placed in front of a converging lens and forms a real image 20 cm tall. For a second, more distant object the same lens gives a magnification of 0.5. Calculate both magnifications and the second image height, and comment on the two images.", scheme: ["First magnification = image / object = 20 / 5 = 4", "First image is magnified (x4) and, being real, inverted", "Second image height = magnification x object height = 0.5 x 5 = 2.5 cm", "Second magnification is 0.5 (given)", "Second image is diminished (smaller than object)", "Full working and no unit on magnification"], answer: "First magnification = 20/5 = 4, so that image is magnified (and, being real, inverted). For the second object, image height = 0.5 x 5 = 2.5 cm, a magnification of 0.5, so that image is diminished." },
      { g: 9, marks: 6, q: "Explain how the balance between absorption and emission of radiation determines the temperature of an object, and apply this to explain how human activity could raise the Earth's temperature. (Physics only)", scheme: ["Objects both absorb and emit radiation at all times", "If absorption rate equals emission rate the temperature is constant", "If absorption exceeds emission the temperature rises (and vice versa)", "The Earth absorbs short-wavelength radiation from the Sun and emits infrared", "Greenhouse gases absorb some outgoing infrared and re-emit it back", "This reduces the rate energy leaves, so more is absorbed than emitted and the Earth warms"], answer: "Every object absorbs and emits radiation; when the rates are equal its temperature is constant, but if it absorbs faster than it emits its temperature rises. The Earth absorbs short-wavelength solar radiation and emits infrared, but greenhouse gases absorb some of this outgoing infrared and re-emit it back, so less energy escapes and the Earth warms." },
      { g: 9, marks: 6, q: "Explain how seismologists use P and S waves to deduce the structure of the Earth, including why a shadow zone forms. (HT)", scheme: ["P waves are longitudinal and travel through solids and liquids", "S waves are transverse and travel only through solids", "S waves are not detected on the opposite side of the Earth", "This shows the outer core is liquid (S waves are stopped)", "P waves refract as they cross boundaries between layers of different density", "This refraction and the missing S waves create shadow zones, mapping the core"], answer: "P waves travel through solids and liquids but S waves only through solids. Because S waves do not reach the far side of the Earth, the outer core must be liquid. P waves refract as they pass through layers of differing density, and this bending together with the missing S waves creates shadow zones that let scientists map the core." },
      { g: 9, marks: 6, q: "A sound wave of frequency 500 Hz travels through air at 340 m/s and then into water where its speed becomes 1500 m/s. Calculate the wavelength in each material and explain what happens to the frequency, showing full working. (HT)", scheme: ["In air: wavelength = v / f = 340 / 500 = 0.68 m", "In water: wavelength = v / f = 1500 / 500 = 3 m", "Frequency stays the same (500 Hz) because it is set by the source", "So the wavelength increases as the speed increases", "Uses v = f x wavelength correctly", "Units (m) stated"], answer: "In air, wavelength = 340/500 = 0.68 m; in water, wavelength = 1500/500 = 3 m. The frequency stays 500 Hz because it is fixed by the source, so as the speed increases the wavelength increases (v = fλ)." },
      { g: 9, marks: 6, q: "Explain fully why electromagnetic waves form a continuous spectrum, and how their frequency links to their uses and dangers.", scheme: ["All EM waves are transverse and travel at the same speed in a vacuum", "They differ in frequency and wavelength, forming a continuous spectrum from radio to gamma", "Low frequency (radio/micro) used for communication as they are not strongly absorbed", "Infrared/visible used for heating, cooking, vision and communication (fibre optics)", "High frequency (UV, X-ray, gamma) carry more energy and are ionising", "So high-frequency waves are more dangerous (cell/DNA damage, cancer)"], answer: "All electromagnetic waves are transverse and travel at the same speed in a vacuum, differing only in frequency and wavelength, so they form a continuous spectrum. Low-frequency radio and microwaves are used for communication because they are not strongly absorbed; infrared and visible light are used for heating, vision and fibre optics; while high-frequency UV, X-rays and gamma carry more energy and are ionising, making them more dangerous as they can damage DNA and cause cancer." },
      { g: 9, marks: 6, q: "A student measures the speed of water waves in a ripple tank. They count 20 waves passing a point in 8 s, and measure the distance across 5 waves as 0.15 m. Calculate the wave speed, then explain two ways the student could reduce measurement error.", scheme: ["f = 20 / 8 = 2.5 Hz", "wavelength = 0.15 / 5 = 0.03 m", "v = f x wavelength = 2.5 x 0.03 = 0.075 m/s", "Reduce error: measure across many waves then divide (reduces uncertainty in wavelength)", "Reduce error: time many waves / use a stroboscope or freeze the image to count accurately", "Repeat readings and take a mean"], answer: "f = 20/8 = 2.5 Hz, wavelength = 0.15/5 = 0.03 m, so v = fλ = 2.5 x 0.03 = 0.075 m/s. Error can be reduced by measuring the distance across many waves before dividing, and by timing many waves (or using a stroboscope to freeze the image), repeating for a mean." },
      { g: 9, marks: 6, q: "Explain how radio waves are produced and received, and how information can be sent using them. (HT)", scheme: ["Radio waves are produced by oscillations (alternating current) in a circuit/aerial", "The oscillating charges emit radio waves with the same frequency as the oscillations", "The waves travel through the air/space and reach a receiving aerial", "They induce an alternating current in the receiver of the same frequency", "The signal is decoded to recover the information", "Different frequencies carry different channels/information"], answer: "Radio waves are produced when charges oscillate (an alternating current) in an aerial, emitting waves of the same frequency. These travel to a receiving aerial where they induce an alternating current of the same frequency, which is decoded to recover the information, with different frequencies carrying different channels." },
      { g: 9, marks: 6, q: "A microwave signal of frequency 1.2 x 10^10 Hz is sent to a satellite 3.6 x 10^7 m away and reflected back. Calculate the wavelength and the total time for the signal to travel there and back. (speed = 3 x 10^8 m/s)", scheme: ["wavelength = v / f = (3 x 10^8) / (1.2 x 10^10)", "= 0.025 m", "Total distance = 2 x 3.6 x 10^7 = 7.2 x 10^7 m", "time = distance / speed = (7.2 x 10^7) / (3 x 10^8)", "= 0.24 s", "Units (m and s) stated with full working"], answer: "Wavelength = v/f = (3 x 10^8)/(1.2 x 10^10) = 0.025 m. Total distance = 2 x 3.6 x 10^7 = 7.2 x 10^7 m, so time = (7.2 x 10^7)/(3 x 10^8) = 0.24 s." },
      { g: 9, marks: 6, q: "Compare converging and diverging lenses, describing how to draw a ray diagram for each and the nature of the images they produce.", scheme: ["Converging lens is thicker in the middle; diverging thinner in the middle", "Converging: a ray parallel to the axis refracts through the principal focus", "Converging can form real, inverted images (or a virtual, upright, magnified image when object is close)", "Diverging: a ray parallel to the axis refracts so it appears to come from the virtual focus", "Diverging always forms a virtual, upright, diminished image", "A ray through the centre of either lens passes straight through"], answer: "A converging lens is thicker in the middle and a diverging lens thinner. For a converging lens a parallel ray refracts through the principal focus and a ray through the centre goes straight on, forming real inverted images (or a virtual, upright, magnified image when the object is very close). For a diverging lens a parallel ray refracts so it appears to come from the virtual focus, always giving a virtual, upright, diminished image." },
    ],
    "7. Magnetism & electromagnetism": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "Name the two poles of a magnet.", scheme: ["North and south"], answer: "The north pole and the south pole." },
      { g: 4, marks: 1, q: "What happens when two north poles are brought close together?", scheme: ["They repel"], answer: "They repel each other." },
      { g: 4, marks: 1, q: "What happens when a north pole and a south pole are brought close together?", scheme: ["They attract"], answer: "They attract each other." },
      { g: 4, marks: 1, q: "Name one metal that is magnetic.", scheme: ["Iron / steel / cobalt / nickel (any one)"], answer: "Iron (or steel, cobalt or nickel)." },
      { g: 4, marks: 1, q: "What is a magnet that produces its own magnetic field all the time called?", scheme: ["Permanent magnet"], answer: "A permanent magnet." },
      { g: 4, marks: 1, q: "What is the region around a magnet where a magnetic force acts called?", scheme: ["Magnetic field"], answer: "The magnetic field." },
      { g: 4, marks: 1, q: "In which direction do magnetic field lines point outside a magnet?", scheme: ["From north to south"], answer: "From the north pole to the south pole." },
      { g: 4, marks: 1, q: "Where is the magnetic field of a bar magnet strongest?", scheme: ["At the poles"], answer: "At the poles." },
      { g: 4, marks: 1, q: "What piece of equipment is used to plot a magnetic field?", scheme: ["(Plotting) compass"], answer: "A plotting compass." },
      { g: 4, marks: 1, q: "What does a magnetic compass needle point towards?", scheme: ["(Magnetic) north"], answer: "Magnetic north." },
      { g: 4, marks: 1, q: "Why does a compass needle point north?", scheme: ["The Earth has a magnetic field"], answer: "Because the Earth has its own magnetic field." },
      { g: 4, marks: 1, q: "What is the name for a magnet that can be switched on and off?", scheme: ["Electromagnet"], answer: "An electromagnet." },
      { g: 4, marks: 1, q: "What is produced around a wire when a current flows through it?", scheme: ["A magnetic field"], answer: "A magnetic field." },
      { g: 4, marks: 1, q: "Name one device that uses an electromagnet.", scheme: ["Scrapyard crane / electric bell / relay (any one)"], answer: "A scrapyard crane (or an electric bell or relay)." },
      { g: 4, marks: 1, q: "Is copper a magnetic material?", scheme: ["No"], answer: "No, copper is not magnetic." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 2, q: "State the difference between a permanent magnet and an induced magnet.", scheme: ["Permanent magnet produces its own field all the time", "Induced magnet is only magnetic when placed in a magnetic field"], answer: "A permanent magnet produces its own magnetic field all the time, while an induced magnet is only magnetic when it is in a magnetic field." },
      { g: 5, marks: 1, q: "What is a material called that becomes a magnet only when placed in a magnetic field?", scheme: ["Induced magnet"], answer: "An induced magnet." },
      { g: 5, marks: 2, q: "Describe the force between an induced magnet and a permanent magnet.", scheme: ["It is always attraction", "Induced magnetism produces attraction only"], answer: "The force is always one of attraction, because induced magnetism only produces attraction." },
      { g: 5, marks: 1, q: "Name the three metals, other than iron, that are magnetic.", scheme: ["Steel, cobalt and nickel"], answer: "Steel, cobalt and nickel." },
      { g: 5, marks: 2, q: "State two ways the strength of a magnetic field can be shown using field lines.", scheme: ["Field lines closer together means a stronger field", "Field lines further apart means a weaker field"], answer: "Where the field lines are closer together the field is stronger, and where they are further apart the field is weaker." },
      { g: 5, marks: 1, q: "State the direction of a magnetic field line at any point.", scheme: ["The direction a compass (north pole) would point"], answer: "The direction in which the north pole of a compass would point." },
      { g: 5, marks: 2, q: "Describe how the field around a bar magnet changes with distance from the poles.", scheme: ["Field is strongest near the poles", "Field gets weaker further away"], answer: "The field is strongest close to the poles and becomes weaker further away from the magnet." },
      { g: 5, marks: 1, q: "What is a coil of wire used to make an electromagnet called?", scheme: ["Solenoid"], answer: "A solenoid." },
      { g: 5, marks: 2, q: "State two ways to make an electromagnet stronger.", scheme: ["Increase the current", "Add more turns / add an iron core (any two)"], answer: "Increase the current and add more turns of wire (or add an iron core)." },
      { g: 5, marks: 1, q: "What shape is the magnetic field around a long straight current-carrying wire?", scheme: ["Concentric circles (around the wire)"], answer: "Concentric circles around the wire." },
      { g: 5, marks: 2, q: "Describe the magnetic field produced by a solenoid.", scheme: ["Strong uniform field inside the solenoid", "Field outside is like that of a bar magnet"], answer: "There is a strong, uniform field inside the solenoid, and outside the field is like that of a bar magnet." },
      { g: 5, marks: 1, q: "What happens to the strength of the field around a wire if the current increases?", scheme: ["The field gets stronger"], answer: "The magnetic field gets stronger." },
      { g: 5, marks: 2, q: "State one advantage of an electromagnet over a permanent magnet.", scheme: ["Can be switched on and off", "Strength can be changed / can be reversed (any one more)"], answer: "An electromagnet can be switched on and off, and its strength can be changed." },
      { g: 5, marks: 1, q: "Name the effect that produces a force on a current-carrying wire in a magnetic field.", scheme: ["The motor effect"], answer: "The motor effect." },
      { g: 5, marks: 2, q: "Give two uses of electromagnets.", scheme: ["Scrapyard crane", "Electric bell / relay / loudspeaker (any one more)"], answer: "A scrapyard crane and an electric bell (or a relay or loudspeaker)." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Explain why a steel paperclip is attracted to either pole of a magnet.", scheme: ["The magnet induces magnetism in the paperclip", "Induced magnetism always causes attraction"], answer: "The magnet induces magnetism in the steel, and because induced magnetism only produces attraction the paperclip is attracted to either pole." },
      { g: 6, marks: 3, q: "Describe how to plot the magnetic field around a bar magnet using a compass.", scheme: ["Place the compass near the magnet and mark the needle direction", "Move the compass to follow the needle and mark more points", "Join the points to draw the field lines from N to S"], answer: "Place a plotting compass near the magnet, mark where the needle points, move the compass to that point and repeat, then join the marks to draw field lines running from north to south." },
      { g: 6, marks: 2, q: "Explain why the field lines are drawn closer together near the poles of a magnet.", scheme: ["The field is strongest at the poles", "Closer lines represent a stronger field"], answer: "The field is strongest at the poles, and lines drawn closer together represent a stronger magnetic field." },
      { g: 6, marks: 3, q: "Describe three ways to increase the strength of an electromagnet.", scheme: ["Increase the current", "Increase the number of turns on the coil", "Add an iron core"], answer: "Increase the current, increase the number of turns on the coil, and add an iron core." },
      { g: 6, marks: 2, q: "Explain why an iron core makes an electromagnet stronger but iron is used rather than steel.", scheme: ["Iron becomes strongly magnetised, increasing the field", "Iron loses its magnetism when the current is off (steel keeps it)"], answer: "Iron becomes strongly magnetised to increase the field, and unlike steel it loses its magnetism when the current is switched off, so the magnet can be turned off." },
      { g: 6, marks: 2, q: "Describe how the right-hand grip rule gives the direction of the field around a wire.", scheme: ["Thumb points in the direction of the (conventional) current", "Curled fingers show the direction of the circular field"], answer: "Point the right thumb in the direction of the current and the curled fingers show the direction of the circular magnetic field." },
      { g: 6, marks: 2, q: "Explain why the Earth behaves as if it has a bar magnet inside it.", scheme: ["The Earth has a magnetic field", "A compass lines up with this field / core produces the field"], answer: "The Earth produces a magnetic field, so a compass lines up with it as though a bar magnet were inside the Earth." },
      { g: 6, marks: 3, q: "Describe the shape and features of the magnetic field around a solenoid.", scheme: ["Field lines inside are parallel / uniform and strong", "One end acts as north, the other as south", "Outside the field is like a bar magnet"], answer: "Inside the solenoid the field lines are parallel, uniform and strong; one end acts as a north pole and the other as a south pole, and outside the field looks like that of a bar magnet." },
      { g: 6, marks: 2, q: "State the three factors on which the force on a current-carrying conductor depends.", scheme: ["The magnetic flux density (B)", "The current (I) and the length of wire in the field (L)"], answer: "The magnetic flux density, the current, and the length of the conductor in the field." },
      { g: 6, marks: 2, q: "Explain how Fleming's left-hand rule is used.", scheme: ["First finger = field, seCond finger = current", "thuMb shows the direction of the force/motion"], answer: "The first finger points along the field, the second finger along the current, and the thumb then shows the direction of the force." },
      { g: 6, marks: 3, q: "A wire carries a current at 90 degrees to a magnetic field of flux density 0.3 T. The current is 5 A and 0.2 m of wire is in the field. Calculate the force.", scheme: ["F = B x I x L", "= 0.3 x 5 x 0.2", "= 0.3 N"], answer: "F = BIL = 0.3 x 5 x 0.2 = 0.3 N." },
      { g: 6, marks: 2, q: "Explain what happens to the force on a wire if the direction of the current is reversed.", scheme: ["The direction of the force reverses", "Because force direction depends on current direction"], answer: "The force acts in the opposite direction, because the direction of the force depends on the direction of the current." },
      { g: 6, marks: 2, q: "State two ways to reverse the direction of the force on a current-carrying wire in a magnetic field.", scheme: ["Reverse the direction of the current", "Reverse the direction of the magnetic field"], answer: "Reverse the direction of the current, or reverse the direction of the magnetic field." },
      { g: 6, marks: 3, q: "A conductor experiences a force of 0.6 N. It is 0.4 m long and sits in a 0.5 T field at 90 degrees. Calculate the current.", scheme: ["I = F / (B x L)", "= 0.6 / (0.5 x 0.4)", "= 3 A"], answer: "I = F / (BL) = 0.6 / (0.5 x 0.4) = 3 A." },
      { g: 6, marks: 2, q: "Explain why there is no force on a wire when the current is parallel to the magnetic field.", scheme: ["Force is greatest at 90 degrees to the field", "When parallel there is no component across the field, so no force"], answer: "The force is greatest when the wire is at 90 degrees to the field; when the wire is parallel to the field there is no force." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "A wire of length 0.25 m carries a current of 6 A at 90 degrees to a magnetic field of flux density 0.4 T. Calculate the force on the wire.", scheme: ["F = B x I x L", "= 0.4 x 6 x 0.25", "= 0.6 N"], answer: "F = BIL = 0.4 x 6 x 0.25 = 0.6 N." },
      { g: 7, marks: 4, q: "Describe how a simple electric motor works.", scheme: ["Current in the coil produces a force in the magnetic field (motor effect)", "Forces on the two sides act in opposite directions", "This creates a turning effect / torque so the coil rotates", "The split-ring commutator reverses the current every half turn to keep it spinning"], answer: "A current flows through the coil in the magnetic field, so the motor effect produces a force on each side. The forces on opposite sides act in opposite directions, creating a turning effect that rotates the coil, and the split-ring commutator reverses the current every half turn so it keeps turning the same way." },
      { g: 7, marks: 3, q: "A conductor experiences a force of 1.2 N in a field of flux density 0.6 T while carrying a current of 4 A. Calculate the length of wire in the field.", scheme: ["L = F / (B x I)", "= 1.2 / (0.6 x 4)", "= 0.5 m"], answer: "L = F / (BI) = 1.2 / (0.6 x 4) = 0.5 m." },
      { g: 7, marks: 3, q: "Explain how the size of the turning force in a motor can be increased.", scheme: ["Increase the current", "Increase the strength of the magnetic field", "Add more turns to the coil"], answer: "The turning force can be increased by increasing the current, using a stronger magnetic field, or adding more turns to the coil." },
      { g: 7, marks: 4, q: "A wire carries a current of 8 A in a magnetic field of flux density 0.15 T. The length of wire in the field is 0.30 m. Calculate the force, then state what happens to it if the current is doubled.", scheme: ["F = B x I x L = 0.15 x 8 x 0.30", "= 0.36 N", "Force is directly proportional to current", "Doubling current doubles the force to 0.72 N"], answer: "F = BIL = 0.15 x 8 x 0.30 = 0.36 N. Force is proportional to current, so doubling the current doubles the force to 0.72 N." },
      { g: 7, marks: 3, q: "Explain the role of the split-ring commutator in a d.c. motor.", scheme: ["It reverses the direction of the current in the coil", "It does this every half turn", "This keeps the coil rotating in the same direction"], answer: "The split-ring commutator reverses the current in the coil every half turn, so the force on each side always acts to keep the coil turning in the same direction." },
      { g: 7, marks: 3, q: "The force on a 0.5 m wire carrying 3 A is 0.9 N when at 90 degrees to a field. Calculate the magnetic flux density.", scheme: ["B = F / (I x L)", "= 0.9 / (3 x 0.5)", "= 0.6 T"], answer: "B = F / (IL) = 0.9 / (3 x 0.5) = 0.6 T." },
      { g: 7, marks: 3, q: "Explain how a compass provides evidence that the Earth has a magnetic field, and where the core comes into it.", scheme: ["A compass needle is a small magnet that lines up with a field", "It settles pointing north, showing a field is present", "The field is thought to be produced by the Earth's (liquid iron) core"], answer: "A compass needle is a small magnet that aligns with a magnetic field; it always settles pointing north, showing the Earth has a magnetic field, which is thought to be produced by the movement of the Earth's liquid iron core." },
      { g: 7, marks: 4, q: "Describe an experiment to show how the force on a current-carrying wire depends on the current.", scheme: ["Place a wire between the poles of a magnet on a top-pan balance", "Vary the current and record the balance reading (force) each time", "Keep length and field the same (control variables)", "Plot force against current to show the relationship"], answer: "Place a wire between magnet poles resting on a top-pan balance, vary the current and record the change in the balance reading, which shows the force, keeping the field and length constant, then plot force against current to show force increases with current." },
      { g: 7, marks: 3, q: "A wire experiences a force of 0.24 N. The field is 0.2 T and the wire length in the field is 0.40 m. Calculate the current in the wire.", scheme: ["I = F / (B x L)", "= 0.24 / (0.2 x 0.40)", "= 3 A"], answer: "I = F / (BL) = 0.24 / (0.2 x 0.40) = 3 A." },
      { g: 7, marks: 3, q: "Explain why the two sides of a motor coil experience forces in opposite directions.", scheme: ["Current flows in opposite directions on the two sides", "The field direction is the same for both sides", "By Fleming's left-hand rule the forces are opposite, giving a turning effect"], answer: "The current flows in opposite directions along the two sides of the coil, so with the same field Fleming's left-hand rule gives forces in opposite directions, producing a turning effect." },
      { g: 7, marks: 4, q: "A motor wire of length 0.10 m carries 12 A in a 0.25 T field at 90 degrees. Calculate the force on this side of the coil and explain what the equal force on the opposite side does.", scheme: ["F = B x I x L = 0.25 x 12 x 0.10", "= 0.3 N", "The opposite side has an equal force in the opposite direction", "The pair of forces produces a turning effect (couple)"], answer: "F = BIL = 0.25 x 12 x 0.10 = 0.3 N. The opposite side carries an equal force in the opposite direction, and this pair of forces produces a turning effect that rotates the coil." },
      { g: 7, marks: 3, q: "Explain how reversing both the current and the magnetic field affects the direction of the force on a wire.", scheme: ["Reversing the current alone reverses the force", "Reversing the field alone reverses the force", "Reversing both together leaves the force in its original direction"], answer: "Reversing the current reverses the force and reversing the field reverses the force, so reversing both at the same time cancels out and the force stays in its original direction." },
      { g: 7, marks: 4, q: "A wire carries 2.5 A in a field of 0.8 T. The force on it is 1.0 N. Calculate the length of wire in the field and state one assumption you have made.", scheme: ["L = F / (B x I) = 1.0 / (0.8 x 2.5)", "= 0.5 m", "Assumption: the wire is at 90 degrees to the field", "(so the full force equation applies)"], answer: "L = F / (BI) = 1.0 / (0.8 x 2.5) = 0.5 m. The assumption is that the wire is at 90 degrees to the magnetic field." },
      { g: 7, marks: 3, q: "Explain why an electromagnet with a soft iron core is used in an electric bell rather than a permanent magnet.", scheme: ["The electromagnet can be switched on and off with the current", "Soft iron loses its magnetism quickly when current stops", "This allows the make-and-break circuit to ring the bell repeatedly"], answer: "An electromagnet can be turned on and off by the current, and soft iron loses its magnetism quickly when the current stops, so the make-and-break circuit can repeatedly attract and release the striker to ring the bell." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "A wire of length 0.35 m carries a current of 9 A at 90 degrees to a magnetic field of flux density 0.20 T. Calculate the force, then calculate the new force if the length in the field is halved.", scheme: ["F = B x I x L = 0.20 x 9 x 0.35", "= 0.63 N", "Force is proportional to length", "Halving length halves force to 0.315 N"], answer: "F = BIL = 0.20 x 9 x 0.35 = 0.63 N. Force is proportional to length, so halving the length gives 0.315 N." },
      { g: 8, marks: 4, q: "Explain how the generator effect is used in an alternator to produce a current.", scheme: ["A coil is rotated in a magnetic field (or field rotated in coil)", "This induces a potential difference across the coil", "Slip rings and brushes connect the coil to the circuit", "The induced p.d. and current alternate as the coil turns, giving a.c."], answer: "In an alternator a coil is rotated in a magnetic field, which induces a potential difference across it. Slip rings and brushes keep it connected to the circuit, and as the coil turns the induced p.d. and current continually change direction, producing alternating current." },
      { g: 8, marks: 4, q: "Explain the difference between how an alternator and a dynamo are connected and the type of current each produces.", scheme: ["Alternator uses slip rings", "Alternator produces alternating current (a.c.)", "Dynamo uses a split-ring commutator", "Dynamo produces direct current (d.c.)"], answer: "An alternator uses slip rings and produces alternating current, while a dynamo uses a split-ring commutator that reverses the connections every half turn, so it produces direct current." },
      { g: 8, marks: 4, q: "A transformer has 200 turns on the primary coil and 50 turns on the secondary coil. The primary voltage is 240 V. Calculate the secondary voltage.", scheme: ["Vp / Vs = np / ns, so Vs = Vp x ns / np", "Vs = 240 x 50 / 200", "= 240 x 0.25", "= 60 V"], answer: "Using Vp/Vs = np/ns, Vs = Vp x ns/np = 240 x 50/200 = 60 V." },
      { g: 8, marks: 4, q: "Explain how a transformer changes the size of a voltage.", scheme: ["Alternating current in the primary produces a changing magnetic field", "The iron core carries this changing field to the secondary coil", "The changing field induces a p.d. in the secondary coil", "The ratio of turns sets the ratio of the voltages"], answer: "The alternating current in the primary coil produces a changing magnetic field, which the iron core carries to the secondary coil. This changing field induces a potential difference in the secondary coil, and the ratio of the number of turns determines how much the voltage is changed." },
      { g: 8, marks: 4, q: "A step-up transformer has a primary voltage of 25 V and a secondary voltage of 100 V. The primary coil has 500 turns. Calculate the number of turns on the secondary coil.", scheme: ["Vp / Vs = np / ns, so ns = np x Vs / Vp", "ns = 500 x 100 / 25", "= 500 x 4", "= 2000 turns"], answer: "ns = np x Vs/Vp = 500 x 100/25 = 2000 turns." },
      { g: 8, marks: 4, q: "Explain how a moving-coil loudspeaker uses the motor effect to produce sound.", scheme: ["An alternating current from the amplifier flows through the coil", "The coil is in a magnetic field, so the motor effect exerts a force on it", "The changing current makes the coil (and cone) move back and forth", "This makes the cone vibrate, producing sound waves"], answer: "An alternating current from the amplifier flows through the coil in a magnetic field, so the motor effect pushes the coil back and forth as the current changes. The coil is attached to a cone, so the cone vibrates and produces sound waves." },
      { g: 8, marks: 3, q: "A transformer is 100% efficient. The primary has a power input of 60 W and the secondary voltage is 12 V. Calculate the current in the secondary coil.", scheme: ["Power in = power out, so Vs x Is = 60 W", "Is = 60 / 12", "= 5 A"], answer: "For a 100% efficient transformer Vs x Is = power in, so Is = 60/12 = 5 A." },
      { g: 8, marks: 4, q: "Explain how a microphone converts sound into an electrical signal using the generator effect.", scheme: ["Sound waves make the diaphragm vibrate", "The diaphragm moves a coil near a magnet (or in a field)", "The movement induces a potential difference in the coil (generator effect)", "The induced current varies in step with the sound wave"], answer: "Sound waves make the diaphragm vibrate, which moves an attached coil within a magnetic field. This movement induces a changing potential difference in the coil by the generator effect, producing an electrical signal that varies in step with the original sound." },
      { g: 8, marks: 4, q: "A transformer has 800 turns on the primary and 200 turns on the secondary. The primary current is 2 A and the primary voltage is 230 V. Assuming it is 100% efficient, calculate the secondary current.", scheme: ["Vp x Ip = Vs x Is (100% efficient)", "Power in = 230 x 2 = 460 W", "Vs = 230 x 200/800 = 57.5 V", "Is = 460 / 57.5 = 8 A"], answer: "Power in = Vp x Ip = 230 x 2 = 460 W. Vs = 230 x 200/800 = 57.5 V, so Is = 460/57.5 = 8 A." },
      { g: 8, marks: 4, q: "Explain why transformers only work with alternating current and not direct current.", scheme: ["A changing magnetic field is needed to induce a p.d. in the secondary", "a.c. constantly changes, so the field in the core keeps changing", "d.c. gives a steady, unchanging field", "A steady field induces no p.d., so no output"], answer: "A transformer needs a changing magnetic field to induce a potential difference in the secondary coil. Alternating current constantly changes, so the field in the core keeps changing, but direct current gives a steady field that does not change and so induces no output voltage." },
      { g: 8, marks: 4, q: "A step-down transformer reduces 230 V to 11.5 V. The secondary coil has 60 turns. Calculate the number of turns on the primary coil.", scheme: ["Vp / Vs = np / ns, so np = ns x Vp / Vs", "np = 60 x 230 / 11.5", "= 60 x 20", "= 1200 turns"], answer: "np = ns x Vp/Vs = 60 x 230/11.5 = 1200 turns." },
      { g: 8, marks: 3, q: "Explain how the size of the induced potential difference from a generator can be increased.", scheme: ["Rotate the coil faster", "Use a stronger magnetic field / more turns on the coil", "Each of these increases how quickly the field is cut / changes"], answer: "The induced potential difference is increased by rotating the coil faster, using a stronger magnetic field, or adding more turns to the coil, as each increases how quickly the magnetic field is cut." },
      { g: 8, marks: 4, q: "A wire carries a current of 7 A at 90 degrees to a 0.30 T field. The force on it is 0.42 N. Calculate the length of wire in the field, then find the force if the field is increased to 0.45 T.", scheme: ["L = F / (B x I) = 0.42 / (0.30 x 7) = 0.20 m", "New F = B x I x L = 0.45 x 7 x 0.20", "= 0.63 N", "Force is proportional to flux density"], answer: "L = F/(BI) = 0.42/(0.30 x 7) = 0.20 m. With B = 0.45 T, F = 0.45 x 7 x 0.20 = 0.63 N." },
      { g: 8, marks: 4, q: "Explain how the output of an alternator varies during one complete rotation of the coil.", scheme: ["p.d. is greatest when the coil moves at 90 degrees to the field (cutting field lines fastest)", "p.d. is zero when the coil moves parallel to the field lines", "The output rises and falls as the coil turns", "It reverses direction each half turn, giving an alternating output"], answer: "The induced p.d. is greatest when the coil is cutting field lines fastest and zero when it moves parallel to the field lines, so the output rises and falls during a rotation and reverses direction every half turn, producing an alternating output." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Explain fully how a d.c. electric motor works, including how it is kept turning and how its speed can be increased.", scheme: ["Current in the coil in a magnetic field experiences a force (motor effect)", "Forces on opposite sides act in opposite directions", "This produces a turning effect / couple that rotates the coil", "Split-ring commutator reverses the current every half turn", "So the force keeps turning the coil the same way", "Speed increased by more current, stronger field or more turns"], answer: "When current flows through the coil in the magnetic field, the motor effect produces a force on each side. The forces on opposite sides act in opposite directions, creating a turning effect that rotates the coil. The split-ring commutator reverses the current every half turn so the force always turns the coil the same way. The speed is increased by increasing the current, using a stronger magnetic field, or adding more turns." },
      { g: 9, marks: 6, q: "A transformer steps up 25 kV to 400 kV for the National Grid. The primary coil has 3000 turns. Calculate the number of secondary turns, then explain why power is transmitted at high voltage.", scheme: ["ns = np x Vs / Vp = 3000 x 400000 / 25000", "= 3000 x 16 = 48000 turns", "Higher voltage means lower current for the same power (P = VI)", "Lower current reduces energy lost as heat in the cables", "Because power loss = I squared x R", "So transmission is more efficient"], answer: "ns = np x Vs/Vp = 3000 x 400000/25000 = 48 000 turns. Power is transmitted at high voltage because for the same power a higher voltage means a lower current (P = VI), and since power loss in the cables is I squared x R, a lower current greatly reduces the energy wasted as heat, making transmission more efficient." },
      { g: 9, marks: 6, q: "Compare an alternator and a dynamo, explaining how each produces its output and how the output would appear on an oscilloscope.", scheme: ["Both rotate a coil in a magnetic field to induce a p.d. (generator effect)", "Alternator uses slip rings, output is alternating current (a.c.)", "Alternator trace is a wave going above and below zero", "Dynamo uses a split-ring commutator", "Commutator reverses the connections every half turn, giving direct current (d.c.)", "Dynamo trace stays on one side of zero, rising and falling"], answer: "Both induce a potential difference by rotating a coil in a magnetic field. An alternator uses slip rings, so its output alternates and shows on an oscilloscope as a wave crossing above and below zero. A dynamo uses a split-ring commutator that reverses the connections every half turn, so its output is direct current, shown as a trace that stays on one side of zero while still rising and falling." },
      { g: 9, marks: 6, q: "A transformer is 100% efficient. The primary is connected to a 230 V supply and draws 0.50 A. The secondary voltage is 11.5 V. Calculate the secondary current and the turns ratio np:ns, showing full working.", scheme: ["Power in = Vp x Ip = 230 x 0.50 = 115 W", "Power out = power in (100% efficient) = 115 W", "Is = Power out / Vs = 115 / 11.5 = 10 A", "Turns ratio np:ns = Vp:Vs = 230:11.5", "= 20:1"], answer: "Power in = Vp x Ip = 230 x 0.50 = 115 W. As it is 100% efficient, power out = 115 W, so Is = 115/11.5 = 10 A. The turns ratio np:ns equals Vp:Vs = 230:11.5 = 20:1." },
      { g: 9, marks: 6, q: "Explain fully how a transformer works and derive why the ratio Vp/Vs equals np/ns.", scheme: ["a.c. in the primary produces a continually changing magnetic field", "The iron core carries the changing field to the secondary coil", "The changing field induces a p.d. in each turn of both coils", "Each coil has the same p.d. induced per turn", "So total p.d. is proportional to the number of turns", "Therefore Vp/Vs = np/ns"], answer: "Alternating current in the primary produces a constantly changing magnetic field, which the iron core carries to the secondary coil. The changing field induces the same potential difference in every turn of both coils, so each coil's total voltage is proportional to its number of turns. Therefore Vp/Vs = np/ns." },
      { g: 9, marks: 6, q: "Explain, using the generator effect, how both a microphone and a loudspeaker work, and state how the two are related.", scheme: ["Microphone: sound vibrates a diaphragm and its coil in a field", "This induces a varying p.d. (generator effect) matching the sound", "Loudspeaker: a varying current in a coil in a field feels a force (motor effect)", "The force moves the coil and cone to make sound waves", "They are the reverse of each other", "One turns sound into electrical signals, the other electrical signals into sound"], answer: "In a microphone sound waves vibrate a diaphragm and its attached coil in a magnetic field, inducing a varying potential difference by the generator effect that matches the sound. In a loudspeaker a varying current in a coil in a magnetic field experiences a force by the motor effect, moving the coil and cone to produce sound waves. The two devices are essentially the reverse of each other, one converting sound to an electrical signal and the other an electrical signal to sound." },
      { g: 9, marks: 6, q: "A wire carrying 15 A lies at 90 degrees to a 0.40 T field, with 0.30 m in the field. Calculate the force. Then explain how this force is used in a motor and what limits how large the current can be.", scheme: ["F = B x I x L = 0.40 x 15 x 0.30 = 1.8 N", "In a motor this force acts on each side of the coil", "Opposite forces create a turning effect that rotates the coil", "Large currents heat the wire (heating effect / resistance)", "Too much heat could melt insulation or damage the coil", "So the current is limited to prevent overheating"], answer: "F = BIL = 0.40 x 15 x 0.30 = 1.8 N. In a motor this force acts on each side of the coil, and the opposite forces create a turning effect that rotates it. The current is limited because a large current heats the wire due to its resistance, and too much heat could melt the insulation or damage the coil, so the current cannot be increased without limit." },
      { g: 9, marks: 6, q: "Explain how the strength and direction of the field around a solenoid can be controlled, and why a solenoid with an iron core is used as an electromagnet.", scheme: ["Field strengthened by more current or more turns per unit length", "Adding an iron core greatly increases the field strength", "Direction of the field is reversed by reversing the current", "Iron core becomes strongly magnetised, boosting the field", "Iron loses magnetism when current is off, so it can be switched off", "Uniform strong internal field makes it a useful electromagnet"], answer: "The field of a solenoid is strengthened by increasing the current or the number of turns per unit length, and its direction is reversed by reversing the current. An iron core is added because it becomes strongly magnetised and greatly increases the field, yet loses its magnetism when the current is switched off, so the electromagnet can be turned on and off. The strong, uniform internal field makes it very useful as an electromagnet." },
      { g: 9, marks: 6, q: "The National Grid uses step-up and step-down transformers. A step-up transformer raises 20 kV to 132 kV to carry 100 MW. Calculate the current in the transmission line, then explain the benefit compared with transmitting at 20 kV.", scheme: ["I = P / V = 100000000 / 132000", "= 758 A (to 3 s.f.)", "At 20 kV: I = 100000000 / 20000 = 5000 A", "Higher voltage gives a much smaller current", "Power loss = I squared x R, so lower current wastes far less energy as heat", "So high-voltage transmission is much more efficient"], answer: "At 132 kV, I = P/V = 100000000/132000 = 758 A. At 20 kV the current would be 100000000/20000 = 5000 A. Because power loss in the cables is I squared x R, the much smaller current at high voltage wastes far less energy as heat, making high-voltage transmission much more efficient." },
      { g: 9, marks: 6, q: "Explain fully how the generator effect can be demonstrated with a wire and a magnet, and state all the factors that affect the size and direction of the induced potential difference.", scheme: ["Moving a wire through a magnetic field (cutting field lines) induces a p.d.", "No p.d. is induced if the wire is stationary or moves parallel to the field", "Size increased by moving faster", "Size increased by a stronger field or more turns/longer wire", "Direction reverses if the movement direction reverses", "Direction reverses if the field/pole direction reverses"], answer: "Moving a wire through a magnetic field so it cuts field lines induces a potential difference; no p.d. is induced if the wire is still or moves parallel to the field. The size of the induced p.d. is increased by moving faster, using a stronger field, or using more turns or a longer wire. Its direction reverses if the direction of movement is reversed, or if the direction of the magnetic field is reversed." },
      { g: 9, marks: 6, q: "A motor coil has 20 turns, each side 0.08 m long, in a 0.50 T field carrying 3 A. Calculate the total force on one side of the coil, then explain how this produces rotation.", scheme: ["Force on one wire = B x I x L = 0.50 x 3 x 0.08 = 0.12 N", "For 20 turns, total force = 20 x 0.12 = 2.4 N", "The opposite side has an equal force in the opposite direction", "This pair of opposite forces forms a couple", "The couple produces a turning effect on the coil", "So the coil rotates about its axis"], answer: "Force on one wire = BIL = 0.50 x 3 x 0.08 = 0.12 N, so for 20 turns the total force on one side = 20 x 0.12 = 2.4 N. The opposite side carries an equal force in the opposite direction, and this pair of forces forms a couple that produces a turning effect, so the coil rotates about its axis." },
      { g: 9, marks: 6, q: "Explain why induced magnetism always causes attraction, and use this to explain how a scrapyard electromagnet can pick up and then drop steel.", scheme: ["A magnet induces magnetism in the steel", "The near end of the steel becomes an opposite pole to the magnet", "Opposite poles attract, so the steel is always attracted", "Current in the electromagnet induces magnetism to pick up the steel", "Switching off the current removes the field", "The soft iron core loses its magnetism, so the steel is dropped"], answer: "A magnet induces magnetism in nearby steel, making the near end of the steel an opposite pole to the magnet, and since opposite poles attract, induced magnetism always causes attraction. A scrapyard electromagnet uses a current to magnetise its core and induce magnetism in the steel, so the steel is attracted and picked up. Switching off the current removes the field and the soft iron core loses its magnetism, so the steel is released and dropped." },
      { g: 9, marks: 6, q: "A transformer has a primary power input of 500 W and is 100% efficient. The secondary has 1500 turns and the primary has 300 turns. The primary voltage is 40 V. Calculate the secondary voltage, the secondary current and the primary current.", scheme: ["Vs = Vp x ns/np = 40 x 1500/300 = 200 V", "Power out = power in = 500 W", "Is = P / Vs = 500 / 200 = 2.5 A", "Ip = P / Vp = 500 / 40 = 12.5 A", "Check: Vp x Ip = 40 x 12.5 = 500 W = Vs x Is"], answer: "Vs = Vp x ns/np = 40 x 1500/300 = 200 V. As it is 100% efficient, power out = 500 W, so Is = 500/200 = 2.5 A and Ip = 500/40 = 12.5 A. Checking: Vp x Ip = 40 x 12.5 = 500 W = Vs x Is." },
      { g: 9, marks: 6, q: "Explain how an alternator produces alternating current, including why the output is zero at certain positions and maximum at others during one rotation.", scheme: ["A coil rotates in a magnetic field, cutting field lines and inducing a p.d.", "Slip rings keep the coil connected to the circuit", "When the coil is parallel to the field it cuts lines fastest, giving maximum p.d.", "When the coil is perpendicular (moving parallel to lines) it cuts none, giving zero p.d.", "Each half turn the sides swap direction relative to the field", "So the induced p.d. reverses each half turn, giving alternating current"], answer: "A coil rotates in a magnetic field and cuts field lines, inducing a potential difference, with slip rings keeping it connected to the circuit. When the coil is moving so it cuts field lines fastest the p.d. is maximum, and when it moves parallel to the field lines it cuts none, so the p.d. is zero. Each half turn the two sides swap their direction of motion relative to the field, so the induced p.d. reverses every half turn, producing alternating current." },
      { g: 9, marks: 6, q: "Evaluate the use of transformers in the National Grid, referring to efficiency, the transformer equation and the power equation.", scheme: ["Step-up transformers raise the voltage for transmission", "Higher voltage means lower current for the same power (P = VI)", "Lower current reduces heating losses (loss = I squared x R)", "Transformers are close to 100% efficient, so Vp x Ip = Vs x Is", "Step-down transformers lower the voltage for safe use in homes", "Overall the grid transmits power efficiently and safely"], answer: "Step-up transformers raise the voltage for transmission; since P = VI, a higher voltage means a lower current for the same power, and because power loss in the cables is I squared x R, this greatly reduces energy wasted as heat. Transformers are almost 100% efficient, so Vp x Ip = Vs x Is and little power is lost in them. Step-down transformers then lower the voltage for safe use in homes. Overall, transformers allow the grid to transmit power both efficiently and safely." },
    ],
    "8. Space physics": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What is at the centre of our solar system?", scheme: ["The Sun (a star)"], answer: "The Sun, which is a star." },
      { g: 4, marks: 1, q: "How many planets are there in our solar system?", scheme: ["Eight"], answer: "Eight planets." },
      { g: 4, marks: 1, q: "What type of object is the Sun?", scheme: ["A star"], answer: "The Sun is a star." },
      { g: 4, marks: 1, q: "What name is given to a natural satellite that orbits a planet?", scheme: ["A moon"], answer: "A moon." },
      { g: 4, marks: 1, q: "What do we call an object put into orbit by humans, such as for TV signals?", scheme: ["An artificial satellite"], answer: "An artificial satellite." },
      { g: 4, marks: 1, q: "Name the force that keeps the planets in orbit around the Sun.", scheme: ["Gravity / gravitational force"], answer: "Gravity." },
      { g: 4, marks: 1, q: "What is the name of the huge cloud of dust and gas from which stars form?", scheme: ["A nebula"], answer: "A nebula." },
      { g: 4, marks: 1, q: "What are the small rocky objects that orbit the Sun mainly between Mars and Jupiter called?", scheme: ["Asteroids"], answer: "Asteroids." },
      { g: 4, marks: 1, q: "What is the first stage of a star's life called, before it becomes a main sequence star?", scheme: ["A protostar"], answer: "A protostar." },
      { g: 4, marks: 1, q: "What theory describes how the universe began from a tiny, hot, dense point?", scheme: ["The Big Bang theory"], answer: "The Big Bang theory." },
      { g: 4, marks: 1, q: "Name the process in the Sun that releases energy by joining hydrogen nuclei together.", scheme: ["(Nuclear) fusion"], answer: "Nuclear fusion." },
      { g: 4, marks: 1, q: "What is a small planet-like object such as Pluto called?", scheme: ["A dwarf planet"], answer: "A dwarf planet." },
      { g: 4, marks: 1, q: "What shape is the orbit of a planet, moon or satellite (roughly)?", scheme: ["(Almost) circular"], answer: "It is roughly circular." },
      { g: 4, marks: 1, q: "What does the Sun mainly produce that reaches the Earth?", scheme: ["Light / heat (energy)"], answer: "Light and heat energy." },
      { g: 4, marks: 1, q: "What happens to a very large star at the end of its life in a huge explosion?", scheme: ["Supernova"], answer: "It explodes as a supernova." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 1, q: "Name the pulling force that holds a moon in orbit around a planet.", scheme: ["Gravity / gravitational force"], answer: "Gravity." },
      { g: 5, marks: 2, q: "State two types of object, other than planets, that orbit the Sun.", scheme: ["Any two of: dwarf planets, asteroids, comets, moons (via planets)"], answer: "Dwarf planets and asteroids (also comets)." },
      { g: 5, marks: 2, q: "Describe how the Sun and solar system first began to form.", scheme: ["From a nebula (cloud of dust and gas)", "Pulled together by gravity"], answer: "They formed from a nebula, a cloud of dust and gas that was pulled together by gravity." },
      { g: 5, marks: 1, q: "What is the difference between a natural satellite and an artificial satellite?", scheme: ["Natural is not made by humans (e.g. a moon); artificial is made/launched by humans"], answer: "A natural satellite such as a moon is not made by humans, while an artificial satellite is built and launched by people." },
      { g: 5, marks: 2, q: "State the order of the first two stages in the life cycle of a star.", scheme: ["Nebula", "Protostar"], answer: "A nebula, then a protostar." },
      { g: 5, marks: 1, q: "What keeps a main sequence star stable in size?", scheme: ["Balance between gravity (inward) and pressure from fusion/expansion (outward)"], answer: "A balance between the inward pull of gravity and the outward force from fusion." },
      { g: 5, marks: 1, q: "What is red-shift?", scheme: ["Light from distant galaxies is shifted towards the red (longer wavelength) end of the spectrum"], answer: "Light from distant galaxies is shifted towards the red end of the spectrum." },
      { g: 5, marks: 2, q: "Name the two possible final stages for a star about the same size as the Sun.", scheme: ["Red giant", "White dwarf"], answer: "It swells into a red giant and then becomes a white dwarf." },
      { g: 5, marks: 1, q: "What does the red-shift of distant galaxies tell us about the universe?", scheme: ["The universe is expanding"], answer: "The universe is expanding." },
      { g: 5, marks: 2, q: "Give two examples of objects that are held in orbit by the Sun's gravity.", scheme: ["Any two of: planets, dwarf planets, asteroids, comets"], answer: "Planets and asteroids (also dwarf planets and comets)." },
      { g: 5, marks: 1, q: "In which part of a star does nuclear fusion take place?", scheme: ["The core / centre"], answer: "In its core." },
      { g: 5, marks: 2, q: "Name two of the eight planets in our solar system.", scheme: ["Any two of: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune"], answer: "Earth and Mars (any two of the eight planets)." },
      { g: 5, marks: 1, q: "What two elements are the Sun mainly made of?", scheme: ["Hydrogen and helium"], answer: "Hydrogen and helium." },
      { g: 5, marks: 2, q: "State what dark matter and dark energy are examples of in science.", scheme: ["Current areas of research", "Things we do not yet fully understand / limits of knowledge"], answer: "They are current areas of research that scientists do not yet fully understand, showing the limits of our knowledge." },
      { g: 5, marks: 1, q: "During fusion in the Sun, which element is being turned into helium?", scheme: ["Hydrogen"], answer: "Hydrogen." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Explain why gravity is described as a centripetal force for a planet in orbit.", scheme: ["Gravity acts towards the centre (the Sun)", "This keeps the planet moving in a circular path"], answer: "Gravity acts towards the Sun at the centre, and this inward force keeps the planet moving in a circular orbit." },
      { g: 6, marks: 2, q: "Explain why the Sun stays the same size during its main sequence stage.", scheme: ["Inward force of gravity", "Balanced by the outward pressure from fusion (expansion)"], answer: "The inward pull of gravity is balanced by the outward pressure from nuclear fusion, so the star stays a stable size." },
      { g: 6, marks: 3, q: "Describe the life cycle of a star about the same size as our Sun, from nebula onwards.", scheme: ["Nebula -> protostar -> main sequence", "Red giant", "White dwarf"], answer: "It forms from a nebula into a protostar, then a main sequence star, then swells into a red giant and finally becomes a white dwarf." },
      { g: 6, marks: 2, q: "Explain how a nebula forms into a protostar.", scheme: ["Dust and gas pulled together by gravity", "Getting hotter and denser as it collapses"], answer: "Gravity pulls the dust and gas of the nebula together, and as it collapses it becomes hotter and denser, forming a protostar." },
      { g: 6, marks: 2, q: "Explain why more distant galaxies show a greater red-shift.", scheme: ["More distant galaxies are moving away faster", "Faster movement gives greater red-shift"], answer: "More distant galaxies are moving away from us faster, and the faster they move the greater the red-shift observed." },
      { g: 6, marks: 3, q: "Describe how the elements up to iron are created in a star.", scheme: ["Nuclear fusion in the core", "Fusion joins lighter nuclei into heavier ones", "Creates elements up to iron"], answer: "Nuclear fusion in the star's core joins lighter nuclei together to make heavier ones, creating elements up to iron." },
      { g: 6, marks: 2, q: "Explain why an object needs a particular speed to stay in a stable orbit at a given radius.", scheme: ["Speed must match the gravitational force at that radius", "Too fast or too slow changes the radius / it leaves orbit"], answer: "The speed must match the gravitational force at that radius; if it is too fast or too slow the orbit radius changes and the orbit is not stable." },
      { g: 6, marks: 2, q: "Explain the difference between the Sun and a planet in terms of light.", scheme: ["The Sun produces/emits its own light", "A planet only reflects light (from the Sun)"], answer: "The Sun produces its own light, whereas a planet does not; it only reflects light from the Sun." },
      { g: 6, marks: 3, q: "Describe what happens to a star much larger than the Sun after its main sequence stage.", scheme: ["Becomes a red super giant", "Explodes as a supernova", "Leaves a neutron star or black hole"], answer: "It becomes a red super giant, then explodes as a supernova, leaving behind a neutron star or a black hole." },
      { g: 6, marks: 2, q: "Explain how red-shift supports the idea that the universe is expanding.", scheme: ["Galaxies are moving away from us (red-shift)", "In all directions, so space itself is expanding"], answer: "The red-shift shows galaxies are moving away from us in all directions, which suggests the whole universe is expanding." },
      { g: 6, marks: 2, q: "Explain why an artificial satellite in a stable orbit does not need engines firing to stay up.", scheme: ["Gravity provides the centripetal force", "It keeps the satellite in orbit at a steady speed"], answer: "Gravity provides the centripetal force that keeps it in orbit, so no engine thrust is needed once it is at the right speed." },
      { g: 6, marks: 2, q: "Explain why a satellite in a circular orbit is constantly changing velocity even at a constant speed.", scheme: ["Its direction is always changing", "Velocity depends on direction as well as speed"], answer: "Its direction is always changing as it moves round the circle, and velocity depends on direction, so the velocity changes even though the speed is constant." },
      { g: 6, marks: 3, q: "Describe how heavier elements end up spread through space to form new planets.", scheme: ["Heavier elements made in stars/supernovae", "Supernova explosion scatters/distributes them into space", "They form part of new stars and planets"], answer: "Heavier elements are made in stars and supernovae, and the supernova explosion distributes them into space, where they can form new stars and planets." },
      { g: 6, marks: 2, q: "Explain why scientists describe dark matter as a current area of research.", scheme: ["It cannot be seen/detected directly", "Its effects are observed but it is not yet understood"], answer: "Dark matter cannot be seen or detected directly; its gravitational effects are observed but it is not yet understood, so it is still being researched." },
      { g: 6, marks: 2, q: "Explain why a nebula begins to collapse in the first place.", scheme: ["Gravity acts between the particles of dust and gas", "Pulls them together"], answer: "Gravity acts between the particles of dust and gas and pulls them together, so the nebula begins to collapse." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 4, q: "Describe the full life cycle of a star the same size as the Sun, in order.", scheme: ["Nebula pulled together by gravity", "Protostar -> main sequence star", "Red giant", "White dwarf (eventually cooling)"], answer: "A nebula is pulled together by gravity to form a protostar, which becomes a main sequence star. When its hydrogen runs low it swells into a red giant, then collapses to become a white dwarf that slowly cools." },
      { g: 7, marks: 4, q: "Describe the life cycle of a star much more massive than the Sun.", scheme: ["Nebula -> protostar -> main sequence", "Red super giant", "Supernova explosion", "Leaves a neutron star or black hole"], answer: "A massive star forms from a nebula, becoming a protostar then a main sequence star. It later swells into a red super giant, then explodes as a supernova, leaving behind a neutron star or, if massive enough, a black hole." },
      { g: 7, marks: 3, q: "Explain how the balance of forces in a main sequence star keeps it stable.", scheme: ["Gravity pulls inwards", "Fusion causes outward pressure/expansion", "Forces are balanced so size stays constant"], answer: "Gravity pulls the star's material inwards while the pressure from fusion pushes outwards; these forces are balanced, so the star stays a stable size during the main sequence." },
      { g: 7, marks: 3, q: "Explain why a satellite closer to Earth must travel faster than one further away.", scheme: ["Closer orbit has stronger gravity / larger centripetal force needed", "A higher speed is needed to stay in the smaller orbit", "Further out, weaker gravity, so slower speed"], answer: "Closer to Earth gravity is stronger, so a larger centripetal force acts, requiring a higher orbital speed; further away gravity is weaker, so the satellite can travel more slowly and still stay in orbit." },
      { g: 7, marks: 4, q: "Describe how the elements found in planets like Earth were made and spread through space.", scheme: ["Light elements formed by fusion in stars", "Elements heavier than iron formed in a supernova", "Supernova explosion distributes elements into space", "New stars and planets form from this material"], answer: "Elements up to iron were made by fusion in stars, and elements heavier than iron were formed during a supernova. The supernova explosion distributes all these elements into space, where they can form new stars and planets such as Earth." },
      { g: 7, marks: 3, q: "Explain why greater red-shift for more distant galaxies is evidence for an expanding universe.", scheme: ["Greater red-shift means faster recession", "The further away, the faster it moves", "Consistent with space expanding everywhere"], answer: "A greater red-shift means the galaxy is moving away faster, and since the most distant galaxies move fastest, this pattern is what we would expect if the whole of space were expanding." },
      { g: 7, marks: 3, q: "Explain why a planet moving in a circular orbit is accelerating even though its speed is constant.", scheme: ["Velocity includes direction", "Direction constantly changes in a circle", "Changing velocity means it is accelerating"], answer: "Velocity depends on both speed and direction. In a circular orbit the direction is constantly changing, so the velocity changes, which means the planet is accelerating even though its speed stays the same." },
      { g: 7, marks: 3, q: "Explain what would happen to a satellite's orbit if it slowed down.", scheme: ["Gravity would be greater than the force needed for that orbit", "It would move to a smaller radius / spiral inwards", "A stable orbit needs the correct speed for the radius"], answer: "If it slowed down, gravity would be stronger than needed for that radius, so it would move to a smaller radius (spiral inwards); a stable orbit requires the correct speed for a given radius." },
      { g: 7, marks: 3, q: "Explain the role of gravity at two different stages of a star's life cycle.", scheme: ["Formation: gravity pulls the nebula together to form a protostar", "Main sequence: gravity balances the outward force of fusion", "Gravity acts throughout, e.g. later collapse"], answer: "During formation, gravity pulls the nebula together to form a protostar. During the main sequence, gravity's inward pull balances the outward force from fusion to keep the star stable." },
      { g: 7, marks: 3, q: "Explain why the theory of how the solar system formed involves both dust and gas and gravity.", scheme: ["The dust and gas provide the material (the nebula)", "Gravity pulls this material together", "Concentration in the centre formed the Sun; the rest formed planets"], answer: "The dust and gas of the nebula provided the material, and gravity pulled it together; most gathered at the centre to form the Sun, while the remaining material formed the planets and other objects." },
      { g: 7, marks: 4, q: "Describe how a spectrum of light from a distant galaxy differs from one from a nearby source, and what this shows.", scheme: ["Lines shifted towards the red end", "Wavelength appears longer / frequency lower", "Greater shift for more distant galaxies", "Shows galaxies moving away / universe expanding"], answer: "The lines in the spectrum are shifted towards the red end, so the wavelength appears longer, and this shift is greater for more distant galaxies. This shows the galaxies are moving away from us and that the universe is expanding." },
      { g: 7, marks: 3, q: "Explain why the Sun is expected to become a red giant and then a white dwarf, but not a supernova.", scheme: ["Its mass is not large enough for a supernova", "Lower mass stars swell to a red giant then become a white dwarf", "Only much more massive stars go supernova"], answer: "The Sun is not massive enough to explode as a supernova; stars of its size swell into a red giant and then collapse to a white dwarf, while only much more massive stars end in a supernova." },
      { g: 7, marks: 3, q: "Explain why observations of red-shift in all directions support the Big Bang theory.", scheme: ["Galaxies moving away in every direction", "Suggests everything was once together and expanded outwards", "Consistent with an expansion from a single point"], answer: "Galaxies are moving away from us in every direction, which suggests that everything was once close together and has since expanded outwards from a single point, as the Big Bang theory describes." },
      { g: 7, marks: 3, q: "Explain why dark matter and dark energy show the limits of current scientific knowledge.", scheme: ["Observations cannot be fully explained by known matter/forces", "Dark matter/dark energy proposed to explain them", "But they are not yet understood or directly detected"], answer: "Some observations, such as how galaxies rotate and how the universe's expansion is speeding up, cannot be explained by known matter and forces. Dark matter and dark energy are proposed to explain them, but they are not yet understood or directly detected, showing the limits of current knowledge." },
      { g: 7, marks: 4, q: "Describe how the material from a dying massive star can eventually form a new planet.", scheme: ["Massive star explodes as a supernova", "Distributes heavy elements into space", "This forms part of a new nebula", "Gravity pulls it together to form new stars and planets"], answer: "A massive star explodes as a supernova, distributing heavy elements into space. This material becomes part of a new nebula, which gravity pulls together to form new stars, and the leftover material can form new planets containing those heavier elements." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "Explain how the life cycle of a star depends on its mass, comparing a Sun-sized star with a much more massive star.", scheme: ["Both start as nebula -> protostar -> main sequence", "Sun-sized: red giant -> white dwarf", "Massive: red super giant -> supernova", "Supernova leaves a neutron star or black hole"], answer: "Both types form from a nebula into a protostar and then a main sequence star. A Sun-sized star then becomes a red giant and collapses to a white dwarf, while a much more massive star becomes a red super giant and explodes as a supernova, leaving a neutron star or a black hole." },
      { g: 8, marks: 4, q: "Explain fully how the forces in a star change from the main sequence to the red giant stage.", scheme: ["Main sequence: gravity balanced by outward pressure from fusion", "Hydrogen in the core runs low so fusion rate changes", "Balance is lost / outer layers expand", "Star swells into a red giant"], answer: "During the main sequence, gravity's inward pull is balanced by the outward pressure from fusion. When the hydrogen in the core runs low the fusion changes and the balance of forces is lost, so the outer layers expand and the star swells into a red giant." },
      { g: 8, marks: 4, q: "Explain how a stable orbit is maintained and what happens if the orbital speed changes.", scheme: ["Gravity provides the centripetal force towards the centre", "For a given radius a particular speed is needed", "If it speeds up, it moves to a larger radius", "If it slows down, it moves to a smaller radius"], answer: "Gravity provides the centripetal force towards the centre, and for a given radius a particular speed is needed to stay in orbit. If the object speeds up it moves to a larger radius, and if it slows down it moves to a smaller radius, so changing the speed changes the orbit." },
      { g: 8, marks: 4, q: "Explain how fusion in stars and supernovae are responsible for the elements found in the universe.", scheme: ["Fusion in stars makes elements up to iron", "Elements heavier than iron are made in a supernova", "The supernova explosion distributes the elements into space", "These elements form new stars and planets"], answer: "Fusion in stars produces elements up to iron, and elements heavier than iron are made during a supernova. The supernova then distributes all of these elements into space, where they become the material for new stars and planets." },
      { g: 8, marks: 4, q: "Explain how red-shift provides evidence for both the expansion of the universe and the Big Bang theory.", scheme: ["Light from galaxies is red-shifted", "Greater red-shift for more distant galaxies -> faster recession", "Shows the universe is expanding", "Tracing expansion back suggests it began from a single point (Big Bang)"], answer: "Light from distant galaxies is red-shifted, and the shift is greater for more distant galaxies, showing they are moving away faster. This means the universe is expanding, and tracing that expansion backwards suggests everything began from a single hot, dense point, supporting the Big Bang theory." },
      { g: 8, marks: 4, q: "Explain why a satellite in a circular orbit accelerates continuously, using ideas about velocity and force.", scheme: ["Speed is constant but direction constantly changes", "So velocity changes -> acceleration", "Gravity provides the centripetal force towards the centre", "This force causes the change in direction"], answer: "Although the speed is constant, the direction is always changing, so the velocity changes, which means the satellite is accelerating. Gravity provides the centripetal force acting towards the centre, and this is the force that continuously changes the satellite's direction." },
      { g: 8, marks: 4, q: "Explain the sequence of events by which our solar system formed from a nebula.", scheme: ["Nebula of dust and gas", "Gravity pulls material together", "Most mass concentrates in the centre -> Sun; fusion begins", "Remaining material forms planets, moons and other objects"], answer: "The solar system began as a nebula of dust and gas. Gravity pulled this material together, and most of the mass concentrated at the centre to form the Sun, where fusion began. The remaining material orbiting the centre clumped together to form the planets, moons, asteroids and other objects." },
      { g: 8, marks: 4, q: "Explain why elements heavier than those in the young universe could only be made once stars existed.", scheme: ["The early universe had mostly hydrogen and helium", "Fusion in stars builds heavier elements up to iron", "Supernovae make and distribute elements heavier than iron", "So heavy elements needed stars to form"], answer: "The early universe contained mostly hydrogen and helium. Heavier elements up to iron are built by fusion inside stars, and elements heavier than iron are made and scattered by supernovae, so these heavier elements could only appear once stars had formed and died." },
      { g: 8, marks: 4, q: "Explain why a main sequence star does not collapse under its own gravity or blow itself apart.", scheme: ["Gravity acts inwards on all the star's material", "Fusion in the core produces an outward pressure/force", "The two forces are balanced", "So the star stays a stable, constant size"], answer: "Gravity pulls all of the star's material inwards, but fusion in the core produces an outward pressure. Because these inward and outward forces are balanced, the star neither collapses nor blows apart and stays a stable, constant size." },
      { g: 8, marks: 4, q: "Explain how scientists can tell that the universe is expanding rather than the galaxies simply moving through fixed space.", scheme: ["Red-shift is observed for galaxies in all directions", "More distant galaxies show greater red-shift", "All galaxies moving apart from each other", "Best explained by space itself expanding"], answer: "Red-shift is observed for galaxies in all directions, and it is greater for more distant galaxies, meaning every galaxy is moving away from every other one. This pattern is best explained by space itself expanding, rather than galaxies simply moving through fixed space." },
      { g: 8, marks: 4, q: "Explain why the discovery of dark matter and dark energy shows that scientific models can be incomplete.", scheme: ["Galaxy rotation and expansion cannot be explained by visible matter/known forces", "Dark matter proposed to explain extra gravity", "Dark energy proposed to explain accelerating expansion", "Not directly detected, so current models are incomplete"], answer: "The way galaxies rotate and the accelerating expansion of the universe cannot be explained by visible matter and known forces alone. Dark matter is proposed to account for the extra gravity and dark energy for the accelerating expansion, but neither has been directly detected, showing that current scientific models are still incomplete." },
      { g: 8, marks: 4, q: "Explain what happens to a very massive star from the main sequence to its final remnant, and the role of forces.", scheme: ["Main sequence: gravity balanced by fusion pressure", "Fuel runs low -> swells to red super giant", "Gravity causes rapid collapse then supernova explosion", "Remnant is a neutron star or black hole"], answer: "On the main sequence gravity is balanced by the outward pressure of fusion. When the fuel runs low the star swells into a red super giant; gravity then causes a rapid collapse, triggering a supernova explosion. The core left behind becomes a neutron star, or a black hole if the star was massive enough." },
      { g: 8, marks: 4, q: "Explain how a nebula containing the remains of old stars can lead to a solar system rich in heavy elements.", scheme: ["Old stars made heavy elements by fusion and supernovae", "These elements are spread into the nebula", "Gravity pulls the nebula together into a new star and planets", "The new planets therefore contain those heavy elements"], answer: "Old stars produced heavy elements by fusion and scattered even heavier ones in supernovae, enriching the nebula. When gravity pulls this nebula together to form a new star and its planets, those planets contain the heavy elements made by the earlier generations of stars." },
      { g: 8, marks: 4, q: "Explain why two satellites at different heights above Earth take different times to complete one orbit.", scheme: ["Lower orbit has stronger gravity, needs a higher speed", "Also travels a shorter distance per orbit", "Higher orbit has weaker gravity, slower speed and longer path", "So higher orbits take longer / lower orbits are quicker"], answer: "A lower satellite experiences stronger gravity, so it must travel faster, and it also has a shorter distance to travel each orbit, so it completes an orbit quickly. A higher satellite has weaker gravity, moves more slowly and travels a longer path, so it takes much longer to complete one orbit." },
      { g: 8, marks: 4, q: "Explain why the idea that the Sun formed from a nebula is consistent with the Sun being mostly hydrogen and helium.", scheme: ["Nebulae are mostly hydrogen and helium", "Gravity pulled this gas together to form the Sun", "Fusion of hydrogen still powers the Sun", "So the Sun's composition matches its origin from a nebula"], answer: "Nebulae are made mostly of hydrogen and helium, and it was this gas that gravity pulled together to form the Sun. The Sun is still powered by the fusion of hydrogen into helium, so its composition being mostly hydrogen and helium is consistent with it having formed from a nebula." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Evaluate the evidence from red-shift for the Big Bang theory, and explain any limitations.", scheme: ["Light from galaxies is red-shifted", "Greater red-shift for more distant galaxies -> faster recession", "Shows universe is expanding in all directions", "Tracing back suggests a single origin (Big Bang)", "Limitation: does not explain what caused it / conditions before", "Dark energy suggests expansion is accelerating, still not fully understood"], answer: "Light from distant galaxies is red-shifted, and the shift is greater for more distant galaxies, showing they recede faster and that the universe is expanding in all directions. Tracing this expansion backwards points to a single hot, dense origin, supporting the Big Bang. However, red-shift does not explain what caused the Big Bang or the conditions before it, and the discovery that expansion is accelerating (linked to dark energy) shows our model is still incomplete, so the theory is strongly supported but not the whole story." },
      { g: 9, marks: 6, q: "Explain fully how the life cycle of a massive star both creates and distributes the elements found in planets like Earth.", scheme: ["Star forms from nebula pulled together by gravity", "Fusion on main sequence makes elements up to iron", "Becomes a red super giant when fuel runs low", "Supernova explosion creates elements heavier than iron", "Explosion distributes all elements into space", "These form new nebulae, then stars and planets"], answer: "A massive star forms as gravity pulls a nebula together. On the main sequence, fusion builds elements up to iron in its core. When the fuel runs low it swells into a red super giant, then explodes as a supernova, and this explosion both creates elements heavier than iron and distributes all of the elements into space. This enriched material forms new nebulae that gravity pulls together into new stars and planets, so planets like Earth contain elements forged in earlier stars." },
      { g: 9, marks: 6, q: "Explain fully, in terms of forces, why a star is stable on the main sequence but changes at the end of its life.", scheme: ["Gravity acts inwards on the star's mass", "Fusion produces an outward pressure/force", "On main sequence these are balanced -> stable size", "When core hydrogen runs low, fusion changes", "Balance is lost, outer layers expand (red giant/super giant)", "Final collapse under gravity -> white dwarf, or supernova then neutron star/black hole"], answer: "On the main sequence the inward pull of gravity is balanced by the outward pressure from fusion, so the star stays a stable size. When the hydrogen in the core runs low the fusion changes and this balance is lost, so the outer layers expand to form a red giant or red super giant. Finally gravity causes the star to collapse: a Sun-sized star becomes a white dwarf, while a massive star explodes as a supernova, leaving a neutron star or, if massive enough, a black hole." },
      { g: 9, marks: 6, q: "Explain how gravity acts as a centripetal force and why a stable orbit requires a particular speed for a given radius.", scheme: ["Gravity acts towards the centre of the orbit", "This provides the centripetal force needed for circular motion", "Direction constantly changes -> continuous acceleration towards the centre", "For a given radius, one speed makes gravity exactly provide the needed force", "Too fast -> moves to a larger radius; too slow -> smaller radius", "So each radius has its own required orbital speed"], answer: "Gravity acts towards the centre of the orbit, providing the centripetal force that keeps an object moving in a circle; because the direction is always changing, the object is continuously accelerating towards the centre. For a given radius there is one particular speed at which gravity exactly provides the force needed for that circle. If the object moves faster it needs a larger radius and drifts outwards, and if it moves slower it drops to a smaller radius, so a stable orbit requires a particular speed for each radius." },
      { g: 9, marks: 6, q: "Evaluate the claim that dark matter and dark energy prove our current understanding of the universe is wrong.", scheme: ["Observations (galaxy rotation, accelerating expansion) not explained by known matter/forces", "Dark matter proposed to explain extra gravity", "Dark energy proposed to explain accelerating expansion", "Neither directly detected -> current models incomplete", "But existing theories still explain much successfully", "Conclusion: shows models are incomplete rather than simply wrong"], answer: "Observations such as the way galaxies rotate and the accelerating expansion of the universe cannot be explained by visible matter and known forces, so dark matter is proposed to provide extra gravity and dark energy to drive the accelerating expansion. Because neither has been directly detected, our models are clearly incomplete. However, existing theories still successfully explain a great deal, so dark matter and dark energy show that our understanding is incomplete and developing, rather than proving it simply wrong." },
      { g: 9, marks: 6, q: "Describe and explain the complete formation of the solar system from a nebula, referring to the Sun, planets and other objects.", scheme: ["Begins as a nebula of dust and gas", "Gravity pulls the material together, it heats up", "Most mass gathers at the centre -> protostar -> Sun; fusion begins", "Remaining material orbits and clumps together", "Larger clumps form planets and their moons", "Smaller leftover material forms dwarf planets and asteroids"], answer: "The solar system began as a nebula of dust and gas. Gravity pulled this material together, causing it to heat up, and most of the mass gathered at the centre to form a protostar that became the Sun once fusion began. The remaining material orbited the centre and clumped together: larger clumps formed the planets and their moons, while the smaller leftover material formed dwarf planets and asteroids, giving the solar system we see today." },
      { g: 9, marks: 5, q: "Explain why, even at constant speed, a planet in a circular orbit is accelerating, and state what provides the force.", scheme: ["Velocity depends on speed and direction", "In a circle the direction constantly changes", "So velocity changes even at constant speed -> acceleration", "Acceleration is directed towards the centre", "Gravity provides this centripetal force"], answer: "Velocity depends on both speed and direction, and in a circular orbit the direction is constantly changing, so the velocity changes even though the speed is constant, which means the planet is accelerating. This acceleration is directed towards the centre of the orbit, and it is gravity that provides the centripetal force causing it." },
      { g: 9, marks: 6, q: "Compare the final stages of a low-mass star and a high-mass star, explaining the role of gravity and fusion throughout.", scheme: ["Both: gravity forms them and balances fusion on the main sequence", "Low mass: red giant when fuel runs low", "Low mass: collapses to a white dwarf under gravity", "High mass: red super giant then supernova", "High mass: gravity collapses core to neutron star or black hole", "Supernova distributes heavy elements into space"], answer: "In both stars gravity forms them from a nebula and, on the main sequence, is balanced by the outward pressure of fusion. When the fuel runs low a low-mass star swells into a red giant and then collapses under gravity into a white dwarf. A high-mass star becomes a red super giant and explodes as a supernova; gravity then collapses its core into a neutron star or a black hole. The supernova also distributes heavy elements into space to form new stars and planets, so mass determines the very different final stages." },
      { g: 9, marks: 6, q: "Explain how observations of red-shift, and the idea of an expanding universe, changed scientific thinking about the origin of the universe.", scheme: ["Red-shift shows galaxies moving away in all directions", "Greater red-shift for more distant galaxies -> universe expanding", "Suggests it was once smaller, hotter and denser", "Led to the Big Bang theory", "Theory accepted because it explains the observations", "Shows how evidence changes accepted scientific models"], answer: "Red-shift shows that galaxies are moving away from us in all directions, with more distant galaxies showing greater red-shift, which means the universe is expanding. This implies that in the past it was smaller, hotter and denser, leading scientists to the Big Bang theory of a single origin. The theory became widely accepted because it explains these observations, illustrating how new evidence such as red-shift can change accepted scientific models of the universe." },
      { g: 9, marks: 5, q: "Explain why a satellite that gradually loses speed due to friction with the thin upper atmosphere will eventually fall to Earth.", scheme: ["Friction reduces the satellite's speed", "For its radius it is now too slow for a stable orbit", "Gravity is greater than needed -> moves to a smaller radius", "At a lower radius it needs a higher speed, but keeps losing speed", "So it spirals inwards and falls to Earth"], answer: "Friction with the thin upper atmosphere reduces the satellite's speed, so it is now travelling too slowly for a stable orbit at that radius. Gravity is then greater than the force needed, so the satellite moves to a smaller radius. At the lower radius an even higher speed would be required, but friction keeps slowing it, so it continues to spiral inwards and eventually falls to Earth." },
      { g: 9, marks: 6, q: "Explain how the composition of stars and planets provides evidence for the life and death of earlier stars.", scheme: ["Early universe was mostly hydrogen and helium", "Elements up to iron are made by fusion in stars", "Elements heavier than iron are made in supernovae", "Presence of heavy elements in the Sun/planets shows earlier stars existed", "Those stars must have died (supernovae) to distribute the elements", "Our solar system formed from this enriched material"], answer: "The early universe was mostly hydrogen and helium, yet the Sun and planets contain heavier elements. Elements up to iron are made by fusion inside stars, and elements heavier than iron are made in supernovae, so the presence of these heavy elements shows that earlier stars must have existed and then died in supernovae to create and distribute them. Our solar system therefore formed from material enriched by earlier generations of stars." },
      { g: 9, marks: 6, q: "Evaluate the strengths and limitations of the Big Bang theory as an explanation for the universe.", scheme: ["Strength: explains red-shift and the expanding universe", "Strength: predicts the universe was once hot and dense", "Strength: supported by wide-ranging observations", "Limitation: does not explain what caused it or came before", "Limitation: dark matter/dark energy still unexplained", "Justified conclusion: best current theory but incomplete"], answer: "The Big Bang theory successfully explains the red-shift of galaxies and the expansion of the universe, and it predicts that the universe was once hot and dense, which is supported by a wide range of observations. However, it does not explain what caused the Big Bang or what, if anything, came before it, and phenomena such as dark matter and dark energy remain unexplained. On balance it is the best current theory for the origin of the universe, but it is still incomplete." },
      { g: 9, marks: 5, q: "Explain why increasing a satellite's speed in orbit does not simply make it circle faster at the same height.", scheme: ["A stable orbit needs a particular speed for a given radius", "Extra speed means gravity is too weak to hold that radius", "So the satellite moves to a larger radius", "At the larger radius the required orbital speed is actually lower", "So it settles into a different, higher, slower orbit"], answer: "A stable orbit requires a particular speed for a given radius, so if the satellite speeds up, gravity is no longer strong enough to hold it at that radius and it moves outwards to a larger radius. At the larger radius the speed needed for a stable orbit is actually lower, so rather than simply circling faster at the same height, it settles into a higher, slower orbit." },
      { g: 9, marks: 6, q: "Explain the full sequence by which hydrogen in a nebula eventually becomes the varied elements in a rocky planet.", scheme: ["Gravity pulls a hydrogen-rich nebula together to form a star", "Fusion joins hydrogen into helium, then heavier nuclei up to iron", "Massive star ends in a supernova, making elements heavier than iron", "Supernova distributes all elements into space", "Gravity pulls this enriched material into a new nebula", "New star and rocky planets form, containing the varied elements"], answer: "Gravity pulls a hydrogen-rich nebula together to form a star, where fusion joins hydrogen into helium and then builds heavier nuclei up to iron. If the star is massive it ends in a supernova, which creates elements heavier than iron and distributes all of these elements into space. Gravity then pulls this enriched material into a new nebula, which collapses to form a new star and rocky planets, so the original hydrogen has been transformed and combined into the varied elements found in a rocky planet." },
      { g: 9, marks: 6, q: "Discuss how scientific ideas about the universe, such as the Big Bang and dark energy, show that scientific knowledge can change over time.", scheme: ["Red-shift evidence led to the Big Bang theory replacing older ideas", "Theory accepted because it explained observations", "Later observations showed expansion is accelerating", "Dark energy proposed to explain this new evidence", "Dark matter proposed for unexplained gravitational effects", "Conclusion: models are revised as new evidence appears"], answer: "The observation of red-shift led scientists to the Big Bang theory, which replaced older ideas because it explained the expanding universe. Later observations showed that this expansion is actually accelerating, so dark energy was proposed to explain the new evidence, and dark matter was proposed to explain unexplained gravitational effects such as galaxy rotation. This shows that scientific knowledge is not fixed: models like these are revised or extended as new evidence appears, and current ideas may themselves be improved in the future." },
    ],
  },
}
